INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(165, 6180, 9, 15, 'Zona Urbana: Lago Azul, Bela Vista, Mirante do Lago, São Francisco e AMG-0320. ( faz parte também da zona rural)', '2025-09-24 16:55:18', '2025-09-24 16:55:18', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(166, 6180, 10, 15, 'No dia 13 de setembro as 16.30 o município foi afetado por fortes chuvas acompanhadas de vendaval que trouxeram vários dados e\nprejuízos ao município, pessoas ficaram desalojadas, casas danificadas , houve prejuízos públicos, quedas de arvores ', '2025-09-24 16:55:18', '2025-09-24 16:55:18', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(167, 6180, 1, 15, 'Todos as pessoas que foram desalojadas foram direcionadas para casas de parentes e amigos, devido aos telhando das suas residências\nque sofreram danos devido as as fortes chuvas e vendaval. Outras pessoas que danos em suas residências, perdas de moveis, alimentos ,\neletrodomésticos, falta de luz e falta de agua', '2025-09-24 16:55:18', '2025-09-24 16:55:18', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(168, 6180, 2, 15, 'Os danos foram relação a imóveis, sendo a maior parte voltadas para o destelhamento de telhas, principalmente em casas com telhas de\namianto, telhas colonial e francesa. Sendo a maior parte de famílias em situação de vulnerabilidade social. O usina de reciclagem teve o seu\ntelhado parcialmente danificado. Um carro sendo uma Van Escolar da administração pública: Valor estimado: 30 mil reais. parte do asfalto\nda rua Minas Gerais no bairro São Francisco foi parcialmente destruída.', '2025-09-24 16:55:19', '2025-09-24 16:55:19', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(169, 6180, 3, 15, 'Houve várias quedas de arvores', '2025-09-24 16:55:19', '2025-09-24 16:55:19', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(170, 6180, 11, 15, NULL, '2025-09-24 16:55:19', '2025-09-24 16:55:19', NULL);
