	(340, 3700, 8, 22, 'Toda a zona rural é afetada pela seca devido a diminuição do volume hídrico, causando perdas de pasto e deixando comunidades rurais sem abastecimento de água.\n', '2025-10-10 13:16:40', '2025-10-10 13:16:40', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
