INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(342, 3700, 10, 22, 'O regime hídrico diminuiu drasticamente no último mês, comprometendo atividades de irrigação, dessedentação dos rebanhos bovinos e abastecimento de comunidades rurais deixando vários munícipes sem água para subsistência.', '2025-10-10 13:16:40', '2025-10-10 13:16:40', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(343, 3700, 1, 22, 'Aproximadamente 5000 (cinco mil) munícipes principalmente produtores rurais foram afetados pela seca que causou perda de produção e aproximadamente 3000 (três mil) habitantes estão sem água potável.\n', '2025-10-10 13:16:40', '2025-10-10 13:16:40', NULL);
