	(346, 3700, 11, 22, 'Foram utilizados recursos públicos para distribuição de água.', '2025-10-10 13:16:40', '2025-10-10 13:16:40', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(347, 3700, 12, 22, 'A seca prejudica os produtores rurais ao reduzir drasticamente a produção agrícola e a disponibilidade de pasto, o que leva à quebra de safras, perdas na pecuária e, consequentemente, a grandes prejuízos financeiros e risco à subsistência. Houveram perdas significativas de culturas de Milho, feijão, abóbora, banana, cana de açúcar e mandioca, bem como prejuízos na área da pecuária devido a seca. ', '2025-10-10 13:16:40', '2025-10-10 13:16:40', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(380, 7030, 8, 17, '', '2025-10-17 15:11:08', '2025-12-30 17:26:48', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(381, 7030, 9, 17, 'Toda Zona rural : comunidade sem terra, comunidade do Muquem , córrego Getolina , córrego Salinas / areia ,córrego do engenho, córrego Manelão margens do rio Umburana , margem do rio Alcobaça ,margens do rio pampam , córrego Itaúna/ Prates , comunidade sorte grande , córrego Damásio , córrego alegrete e toda Área Urbana: Bairro centro , bairro recanto das rosas I e II , bairro baixinha , bairro área , bairro centro , Distrito de São Pedro do pampam.\n', '2025-10-17 15:11:08', '2025-10-17 15:11:08', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(382, 7030, 10, 17, 'Na área rural temos animais morrendo por conta da falta de chuva e assim a escassez de alimentos . Na área Urbana já se encontra com falta de agua algumas vezes nos bairros pela baixa do nível do rio de onde é captada a agua , tendo dificuldade na captação de agua pela empresa responsável assim tendo que ser feito racionamento algumas vezes e em alguns momentos tento falta de abastecimentos por um período', '2025-10-17 15:11:08', '2025-10-17 15:11:08', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(383, 7030, 1, 17, 'Toda a população afetada pelas altas ondas de calor e baixa umidade do ar e com os níveis de agua baixando tendo que fazer racionamento \nde agua alguns desencadeando problemas respiratórios e com pele. Atendimento de aproximadamente 700 pessoas com o caminhão pipa \npróprio para abastecimento de agua para animais e consumo humano ( utilidades exceto beber ) e aproximadamente 1600 pessoas sofrendo com pouca agua ', '2025-10-17 15:11:08', '2025-12-30 17:26:49', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(384, 7030, 2, 17, NULL, '2025-10-17 15:11:08', '2025-10-17 15:11:08', NULL);
