	(385, 7030, 3, 17, 'NIVEL DOS RIOS ALCOBAÇA, RIO PAMPAM, RIO ITANHEM (UMBURANA) QUE PASSAM PELO MUNICIPIO E SERVEM PARA CAPTAÇÃO DE AGUA ESTÃO MUITO BAIXOS E ALGUNS AFLUENTESE CORREGOS JA SECARAM .', '2025-10-17 15:11:09', '2025-10-17 15:11:09', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(386, 7030, 11, 17, 'Gastos com operador e combustível para uso de retroescavadeira na criação que pequenas barragens para armazenar agua para os animais e também no abastecimento do caminhão pipa e operador para levar agua a quem necessita para uso domestico ', '2025-10-17 15:11:09', '2025-10-17 15:11:09', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(387, 7030, 12, 17, 'Agricultura : falta de agua esta causando perda de lavouras de mandioca , capineiras de capiaçu e cana de açúcar , plantio de hortaliças secando e sem desenvolvimento por falta de agua . Pecuária : os animais estão morrendo e perdendo peso por falta de agua , a produção de leite caindo devido a falta de agua .', '2025-10-17 15:11:09', '2025-10-17 15:11:09', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
