	(24852, 4620, 8, 26, NULL, '2025-11-03 12:09:00', '2025-11-03 12:09:00', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(24853, 4620, 9, 26, 'ÁREA URBANA: BAIRRO ANA ROSA FERREIRA - RUA JOSÉ FERNANDES DE AZEVEDO, RUA PROF.ª SEBASTIANA MARCIA PEREIRA DANTAS,\nPROF. AUSTROGÉSIO WALDEMAR ELLER; BAIRRO CENTRO - RUA SÃO JOÃO, RUA IRMÃ MARIA MURINI E RUA JOAQUIM DE OURO\nBAIRRO LOURENÇO RESENDE. ÁREA RURAL: CÓRREGO QUILOMBO CARNEIRO, CÓRREGO NORTE, CÓRREGO TERRA BOA, CÓRREGO\nNOVATOS E CÓRREGO QUEIXADA II\n', '2025-11-03 12:09:00', '2025-11-03 12:09:00', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(24854, 4620, 10, 26, 'REGISTROS DO DIA 19 DE OUTUBRO DE 2025, POR VOLTA DAS 16H40MIN. SOFREU COM CHUVA INTENSA DE GRANDE VOLUME,\nCHEGANDO A MAIS DE 100MM DE CHUVA COM DURAÇÃO DE APROXIMADAMENTE 40 MINUTOS, CHEGANDO A SE FALAR DE TROMBA\nD\'ÁGUA, OCORRERAM INÚMEROS DERRAMAMENTOS DE MASSA/SOLO E INUNDAÇÃO DE RUAS E CASAS. ÁREA URBANA: NO BAIRRO ANA\nROSA RODRIGUES A RUA JOSÉ FERNANDES DE AZEVEDO, 06 UNIDADES HABITACIONAIS FORAM INVADIDAS PELA ÁGUA E TERRA\nADVINDO A CORRIDA DE MASSA EM DECORRÊNCIA AO GRANDE VOLUME DE ÁGUA DESCIDA E COLAPSO DA REDE COLETORA, 03 (TRÊS)\nFAMÍLIAS SE ENCONTRAM DESALOJADA, ESTANDO PROVISORIAMENTE EM CASA DE FAMILIARES, A RUA Prof.ª SEBASTIANA MARCIA\nPEREIRA DANTAS TEVE SEU ACESSO TOTALMENTE INTERDITADO, A RUA PROF. AUSTROGÉSIO WALDEMAR ELLER O LAR DE IDOSOS\nCONHECIDO COMO CASA DE APOIO TEVE SUA ÁREA INVADIDA PELA ÁGUA E TERRA. NA RUA SÃO JOÃO O GRANDE VOLUME DE CHUVA\nPROVOCOU ENTUPIMENTO DO BUEIRO SITUADO NO CEMITÉRIO MUNICIPAL CAUSANDO EROSÃO E LEVANDO OSSADAS DE CAMPAS\nPARA O PERÍMETRO URBANO, DUAS UNIDADES HABITACIONAIS PRÓXIMAS AO CEMITÉRIO MUNICIPAL, SITUADOS A RUA IRMÃ MARIA\nMURINI E RUA JOAQUIM DE OURO TIVERAM SUAS ESTRUTURAS DANIFICADAS EM DECORRÊNCIA AO VOLUME DE ÁGUA SENDO\nAGRAVADAS PELA VULNERABILIDADE DAS FAMÍLIAS, NO BAIRRO LOURENÇO RESENDE RUAS FICARAM PARCIALMENTE DANIFICADAS.\nÁREA RURAL: ESTRADAS VICINAIS FORAM ASSOLADAS COM MOVIMENTAÇÕES DE TERRAS, DESLIZAMENTO DE BARREIRAS,\nINUNDAÇÕES E ALAGAMENTOS, MUITAS DAS QUAIS DURANTE O PERÍODO CURTO FICARAM INTRANSITÁVEIS, O CÓRREGO QUILOMBO\nCARNEIRO TEVE SUAS ESTRADAS TOTALMENTE INTERDITADAS, FICANDO ISOLADA E SEM ACESSO, NO CÓRREGO QUILOMBO CARNEIRO\n01 (UM) BUEIRO FORA DANIFICADO, OS CÓRREGOS NORTE, TERRA BOA E NOVATOS, TIVERAM ESTRADAS PARCIALMENTE\nINTERDITADAS E CÓRREGO QUEIXADA II OBRA DE CALÇAMENTO FORA DANIFICADO\n', '2025-11-03 12:09:00', '2025-11-03 12:09:00', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(24855, 4620, 1, 26, 'DEVIDO A CHUVAS INTENSAS QUE ACONTECEU NO MUNICÍPIO DE OURO VERDE DE MINAS FORAM ATINGIDAS MÉDIA ORA APURADA DE\n1.458 PESSOAS, A QUAL ALGUMAS TIVERAM SUAS CASAS INVADIDAS POR ÁGUA E/OU ENXURRADAS TENDO PERCA DE MÓVEIS E\nELETRODOMÉSTICOS, 05 PESSOAS (03 FAMÍLIAS) SE ENCONTRAM DESALOJADAS ESTANDO ESTAS PROVISORIAMENTE EM CASAS DE\nFAMILIARES, CASAS COM A ESTRUTURA DANIFICADAS, COMUNIDADES ISOLADAS POR APROXIMADAMENTE 2 DIAS, HAVENDO ASSIM\nPERCA DE ALIMENTOS PERECÍVEIS. NÃO HAVENDO REGISTRO DE ÓBITOS.', '2025-11-03 12:09:00', '2026-01-05 13:34:28', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(24856, 4620, 2, 26, 'OBRAS DE DESOBSTRUÇÃO DE ESTRADAS NO CÓRREGO QUILOMBO CARNEIRO, NORTE, TERRA BOA E NOVATOS, CONSTRUÇÃO DE\nBUEIRO NO CÓRREGO CARNEIRO, REESTABELECIMENTO DE OBRA DE CALÇAMENTO ESTRADA CÓRREGO QUEIXADA II; ZONA URBANA:\nBAIRRO ANA ROSA FERREIRA: DESOBSTRUÇÃO E LIMPEZA DA RUA PROF. SEBASTIANA MARCIA, RUA RUA JOSÉ FERNANDES DE\nAZEVEDO. NA REGIÃO CENTRAL NA RECONSTRUÇÃO DE UM BUEIRO NA RUA SÃO JOÃO NO CEMITÉRIO MUNICIPAL, RESTABELECIMENTO\nDE RUAS NO BAIRRO LOURENÇO RESENDE.\n', '2025-11-03 12:09:00', '2025-11-03 12:09:00', NULL);
