	(24858, 4620, 11, 26, 'OS VALORES GASTOS FORAM COM LIMPEZAS DE VIAS, LIMPEZA DE BUEIRO, DESOBSTRUÇÃO DE VIAS E ESTRADAS QUE DÃO ACESSO A COMUNIDADES QUILOMBOLAS.', '2025-11-03 12:09:01', '2025-11-03 12:09:01', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(24859, 4620, 12, 26, 'O MUNICÍPIO REGISTROU JUNTO AOS SEUS PRODUTORES RURAIS PERCAS NAS CULTURAS DE HORTALICAS E CEREAIS, CULTIVOS DA AGRICULTURA FAMILIAR, DEVIDO AO GRANDE VOLUME DE ÁGUAS QUE CHEGARAM ATE AS PLANTAÇÕES, BEM COMO OS PREJUÍZOS NA PECUÁRIA DE LEITE, UMA VEZ QUE AS VIAS UTILIZADAS PARA O TRANSPORTE DA PRODUÇÃO SE TORNARAM INTRANSITÁVEIS.', '2025-11-03 12:09:01', '2025-11-03 12:09:01', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
