INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(24861, 2120, 9, 27, 'Todo município de Delfinópolis foi afetado pelo forte vendaval, falta de energia, internet.\n', '2025-11-03 12:24:14', '2025-11-03 12:24:14', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(24862, 2120, 10, 27, 'no dia 30/10/2025 o município oi acometido de um forte vendaval, causando vários danos humanos, onde pessoas ficaram desalojadas,\nvarias casas alagadas , varias foram destelhadas, unidades saúde afetada, escola afetada, houve queda de postes causando falta de energia\nno município, sem internet , prédios públicos , quadra poliesportiva afetada, gerando assim , prejuízos econômicos públicos e privados ,\nquedas de arvores, perdas de medicamentos , lavouras destruídas.\n', '2025-11-03 12:24:14', '2026-01-05 16:54:44', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(24863, 2120, 1, 27, '25 PESSOAS FICARAM DESALOJADAS INDO PARA CASA DE PARENTES E AMIGOS. VÁRIAS PESSOAS TIVERAM SUAS CASAS ALAGADAS,\nDESTELHADAS, PERDAS DE MOVEIS, COLCHOES, ALIMENTOS UTENSÍLIOS DOMÉSTICOS,ESTRADAS INTERDITADAS POR QUEDAS DE\nARVORES IMPEDINDO O TRAFEGO DE PESSOAS, FALTA DE ENERGIA ELÉTRICA DO MUNICÍPIO, ALGUNS PONTOS DA CIDADE SEM\nINTERNET. PRODUTORES PERDARAM SUAS LAVOURAS.', '2025-11-03 12:24:14', '2026-01-05 16:54:44', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(24864, 2120, 2, 27, '45 casas foram danificadas, com alagamentos e destelhamentos. 01 posto de saúde houve varias telhas e o toldo danificadas 01 hospital teve alagamentos e danos em algumas partes 01 escola municipal Conego Marinho destelhamento do banheiro da escola 01 Samu caiu o teto do banheiro e alagamento 01 quadra poliesportiva municipal alagada, e danos no telhado 01 velório municipal foi alagado e danos no\ntelhado 01 quadra esporte no bairro São Sebastião foi alagada e teve seu alambrado arrancado 01creche municipal foi destelhada parcialmente 01 cad- portal de entrada da Cidade - atendimento ao turista, até o momento são as informações colhidas, os levantamentos ainda estão em andamento.', '2025-11-03 12:24:14', '2025-11-03 12:24:14', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(24865, 2120, 3, 27, 'houve varias arvores arrancadas pelo forte vendaval em quase todo o município', '2025-11-03 12:24:15', '2025-11-03 12:24:15', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(24866, 2120, 11, 27, 'Houve a necessidade do abastecimento do maquinário para a limpeza da cidade, estradas . e abastecimento das motosserras para as podas de árvores. ENSINO: Se refere a horas extras de 10 funcionários que trabalharam para limpeza das ruas ruas e recolhimentos de entulhos do município.\n', '2025-11-03 12:24:15', '2025-11-03 12:24:15', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(24867, 2120, 12, 27, 'Agricultura: Perdas da lavoura da plantação de bananas. O comercio teve prejuízo com perdas, em lojas, farmácias e supermercados.\n', '2025-11-03 12:24:15', '2025-11-03 12:24:15', NULL);
