INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(25409, 930, 3, 28, 'Os incêndios florestais, tanto em áreas urbanas quanto rurais, trouxeram inúmeros prejuízos ao município de Buritis. Houve necessidade de deslocamentos constantes e grande consumo de recursos, como o abastecimento de água potável,o meio ambiente foi severamente afetado, com destruição significativa da fauna e flora locais, cuja recomposição demandará muitos anos,diante dessa situação, torna-se\nindispensável a adoção de medidas urgentes de recuperação ambiental e apoio aos setores impactados', '2025-11-03 12:44:07', '2025-11-03 12:44:07', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
