INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27039, 5690, 1, 30, 'O MUNCIPIO DE SACRAMENTO TEVE 322 PESSOAS AFETADAS PELO DESASTRE, QUE TIVERAM O TELHADO DO IMOVEL DANIFICADOS - 12 PESSOAS DESALOJADA QUE FORAM ASSISTIDAS E ENCAMINAHDAS PARA CASA DE PARENTES, 8 DESABRIGADAS - QUE FORAM ENCAMINHADAS PARA CASA DE PASSAGEM (GETUFA), E 302 PESSOAS AFETADAS DIRETAMENTE. FOTAM REGISTRADAS PESSOAS\nAFETADAS (TIVERAM SUS CASAS INVADIDAS PELA ÁGUAS, PERDERAM MOBILIÁRIOS, VESTUÁRIOS, GÊNEROS ALIMENTÍCIOS, DENTRE OUTROS), PORÉM APÓS LIMPEZA E JIGIENIZAÇÃO DOS IMÓVEIS, FORAM ASSISTIDAS PELA EQUIPE DA PREFEITURA, PUDERAM PERMANECER NOS IMÓVEIS. OS DANOS EM DECORRÊNCIA FORAM RELEVANTES, DESTACANDO QUE VARIAS EQUIPES DA PREFEITURA\n(ASSISTENCIA SOCIAL, OBRAS E SAÚDE), ESTIVERAM APOIO A COMPDEC NAS AÇÕES DE REPOSTA, ASSISTINDO À POPULAÇÃO AFETADA.', '2025-11-03 17:23:46', '2025-11-03 17:23:46', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27040, 5690, 2, 30, 'UNIDADES HABITACIONAIS: Danificadas - casas que tiveram os telhados, dentro outros, perderam imobilirios e colchões, porém com a limpeza e higienização, puderam permanecer no imovel. Áreas Urbanas atingidas, bairro Perpetuo Socorro - Toda a extensão da Rua Argila,Rua Caramuru Paraguaçu, Rua Uberaba, Avenida Coronel Julio Borges. Bairro Lauro Afonso Borges - Toda a extensão da Rua Marlene\nRamos Scalon, Angelina Bernadeli Fraga. Bairro - Parque Todas as extensão da Rua Osório Fernandes de Oliveira, Bairro Alto da Estação - toda a extensão da Rua Abraão Abdão Amui, Ivaldo Pereira de Almeida, Bairro Santo Antonio - Toda a extensão da Rua Major Ataliba Jose da Cunha. - Destruídas: não houve. Instalações públicas de ensino: Escola Silvia Vieira, CEMEI Aparecida Loiola Cerchi. Instalações Públicas\nPrestadoras de Outros Serviços - Prédio do CRAS e Almoxarifado (Obras) e Camara Municipal de Sacramento, Obras de infraestrutura publica não houve.\n', '2025-11-03 17:23:47', '2025-11-03 17:23:47', NULL);
