INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27485, 3840, 9, 32, 'Toda a área urbana do município de Leopoldina foi afetada pelo evento climatológico. Na zona rural, comunidades e todos os distritos como:\nArraial dos Montes, Abaíba, Boa Sorte, Bonfim, Caeté e Estiva', '2025-11-10 15:48:35', '2026-01-05 14:09:28', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27486, 3840, 10, 32, 'No dia 04 de novembro do corrente ano, às 14 horas e 5 minutos, a cidade de Leopoldina foi acometida durante aproximadamente 30 minutos, com forte chuva, com tempestade de granizo e vendaval, com acumulados de 58 mm de precipitações e ventos acima de 80 km/h, que afetou vários pontos da zona urbana e rural do município. Em decorrência do elevado volume de precipitação registrado, diversas vias\nda região central do município apresentaram pontos de alagamento. Foram identificados múltiplos danos em áreas urbanas e rurais do município, incluindo residências destelhadas, colapsos de muros e paredes, e avarias em mobiliários e colchões devido à infiltração de água. A ação dos ventos intensos provocou danos estruturais em edificações públicas e privadas. Na Casa de Caridade Leopoldinense, o setor de\nhemodiálise teve o telhado completamente comprometido, também foram registradas avarias nas grades das quadras poliesportivas municipais, bem como em telhados e estruturas de alvenaria de escolas da rede municipal de ensino. O vendaval arrancou ainda as placas da usina fotovoltaica municipal, resultando em danos à estrutura de fixação e comprometendo o funcionamento do sistema. Houve registro de quedas de árvores e deslizamentos de barreiras em estradas vicinais, ocasionando bloqueios parciais e dificultando o acesso a comunidades rurais.', '2025-11-10 15:48:35', '2025-11-10 15:48:35', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27487, 3840, 1, 32, NULL, '2025-11-10 15:48:35', '2025-11-10 15:48:35', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27488, 3840, 2, 32, 'totalmente destruídas. 06 instalações publicas de ensino Escola Municipal Professora Maria da Conceição Monteiro de Resende (CAIC),\nlocalizado na Rua Sebastião Ferreira Lacerda, s/n - Eldorado, em Leopoldina, teve cobertura metálica danificada. Escola Municipal Judith\nLintz, localizada na Av. dos Expedicionários, 1501 - Bela Vista, em Leopoldina, teve o telhado colonial danificado com a força do vendaval.\nEscola Municipal Cirene Fernandes Valentim, Rua Aloísio Soares Fajardo, Nova Leopoldina, em Leopoldina, teve o telhado danificado. C.M.E.\nI. Ilídio Raimundo, Avenida Angelo Correa do Bem, Imperador, em Leopoldina, teve a estrutura do telhado comprometida. Creche Anita\nBorela, instalada na Rua Madre Cândida Maria de Jesus, 22 - Limoeiro, Leopoldina também registrou danos no telhado e estruturas\ncomplementares, Creche Municipal Santa Luzia, localizada na Manoel Januário, Santa Cruz, em Leopoldina, também registrou danos na\nestrutura da cobertura metálica do imóvel. A Casa de Caridade Leopoldinense (Hospital de Leopoldina), localizado na Rua Padre Júlio, 138,\nCatedral, em Leopoldina teve o telhado gravemente danificado, deixando o setor de hemodiálise completamente descoberto e afetando\ntambém os anexos Posto Nobre, a Enfermaria Feminina, o Posto G, ocorreram ainda infiltração na estrutura da Farmácia Municipal,\nlocalizada na rua Gustavo Barbosa de Miranda, nº 25, no bairro Fabrica e em 7 Unidades de Saúde da Família (ESF) que tiveram os telhados\ne estruturas comprometidas, discriminados abaixo: Três Cruzes: localizado na rua Projeta S/N, Bairro Três Cruzes, Leopoldina - falta de\nenergia, galhos de árvores sobre o muro, caixa d¿água destampada e telhas quebradas São Cristóvão I: localizado na rua Nilo Colono dos\nSantos, nº 144, Bairro São Cristóvão, Leopoldina - quebra da janela de vidro da sala do NASF Vale do Sol (CAIC): localizado na rua\nSebastião Ferreira Lacerda, nº 20, Bairro Eldorado, Leopoldina - desabamento parcial do telhado Academia da Saúde: localizado na Avenida\ndos Expedicionários S/N, Bairro Bela Vista, Leopoldina - vidros das portas e das janelas quebrados Ribeiro Junqueira: localizado na Avenida\nAurélio Pimentel n° 20, Ribeiro Junqueira, Leopoldina - vidro da cozinha quebrado Bela Vista II: localizado na Avenida Expedicionário, nº\n1499, Bairro Bela Vista, Leopoldina - Vidro atrás do PSF CEO: localizado na rua Gabriel Andrade Junqueira, S/N, Centro, Leopoldina - vidro\nfrente Prestadora de serviços A Usina Fotovoltaica Municipal, instalada á margem MG -120, sofreu danos expressivos devido à força dos\nventos, que arrancaram 120 módulos fotovoltaicos, dos quais 87 apresentaram danos físicos permanentes, comprometendo o desempenho\ndo sistema. Instalações públicas de uso comunitário 03 quadras de ginásio poliesportivas Foram danificadas as grades e portões de,\nlocalizadas na Rua Manoel Januário, bairro Alto cemitério, Rua Madre Cândida de Jesus, Bairro Limoeiro e na Cohab Nova, em Leopoldina;\n01 campo de futebol municipal, localizado na R. Alan Kardec, 104, Redentor, Leopoldina. Obras de infraestrutura pública Trecho da Avenida\ndos Expedicionários, no Bairro Bela Vista, em Leopoldina. A margem do corpo hídrico vem cedendo, gerando risco significativo para\npedestres e veículos que trafegam pelo local. Ressalta-se que a estrutura já se encontrava em processo erosivo, porém teve a situação\nagravada diante da força da enxurrada, comprometendo ainda mais a segurança dos pedestres e o trafego da via. Sendo identificada a\nnecessidade de construção de um muro de gabião para contenção de talude, com o objetivo de conter o avanço da erosão e estabilizar o\ntrecho afetado', '2025-11-10 15:48:35', '2026-01-05 14:09:29', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27489, 4530, 8, 33, NULL, '2025-11-10 16:00:30', '2025-11-10 16:00:30', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27490, 4530, 9, 33, 'RUA JORGE CHAIN, RUA JACINTO CARVALHO, RUA VALMIRO DA SILVA CATA PRETTA, RUA INACIO BAHIA, RUA UBALDA, ALEXANDRE\nBAIANO RUA TRANCEDO NEVES; TRAVESSA AMADEU FARIA, RUA ANTONIO ESTEVES LIMA, RUA JOÃO PACIÊNCIA, RUA SANTA CHACARA;\nRUA MANOEL TOMÉ, RUA BENEDITO ROCHA, RUA JOÃO TOUTEIRO, RUA JOAQUIM PEREIRA, RUA JOSÉ MARIA PRETA, PRÇA FREI\nUBALDO (HOSPITAL SÃO BENTO), NOS BAIRROS, SÃO FRANCISCO, CRISTO REI, TRIANGULO E ANASTACIO ROQUE, SÃO BENTO, CENTRO', '2025-11-10 16:00:31', '2026-01-05 16:50:12', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27491, 4530, 10, 33, 'Devido as chuvas intensas, vendaval e granizo acometidas no município de Novo Cruzeiro, no dia 06/11/2025, por volta das 14h40, com\naproximadamente 54mm, segundo a COPASA, com duração de, aproximadamente 1 hora, a qual causou diversos alagamentos nas vias\nurbanas, derrubou árvores, cortou o fornecimento de energia elétrica em toda a cidade, enxurradas que abriram várias crateras nas ruas:\nDanos na rede de esgoto, pavimentação e alagamentos. Caiu uma árvore e interditou a rua.', '2025-11-10 16:00:31', '2026-01-05 16:50:12', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27492, 4530, 1, 33, 'Foram avaliadas as consequências das chuvas acometidas na tarde do dia 06/11/2025 na cidade de Novo Cruzeiro: 3.527 pessoas afetadas;\n20 pessoas desalojadas que tiveram que sair de suas casas no momento do desastre para irem para residências de parentes e amigos, 7\npessoas desabrigadas, as quais foram hospedadas pela Prefeitura Municipal no hotel da cidade e 3.500 afetadas, pois tiveram sua rotina\nalterada pelos danos causados pelas fortes chuvas, devido a alagamentos em varias ruas, danos em moveis, com falta de energia elétrica\nem vários bairros.\n\n', '2025-11-10 16:00:31', '2026-01-05 16:05:40', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27493, 4530, 2, 33, 'Devido as chuvas intensas, 57 casas foram alagadas e tiveram destelhamentos, nos seguintes bairros: São Francisco, Centro da cidade, Vila\nBarrinha, Cristo Rei, Triangulo e Anastácio Roque. Com perdas de sofás, televisões, moveis, roupas etc. DANIFICADOS: 02 instalações de\nsaúde foram danificadas: A Policlínica Municipal e a Unidade de Saúde São Bento teve danos no teto de gesso, danos em diversos\nequipamentos. 01 Hospital São Bento, reconstrução de telhado e reboco em paredes 01 Rede de Ensino Creche Gente Miúda, alagamento e\nqueda de forro pvc do telhado Rua Tancredo Neves, destruição da pavimentação e rede pluvial. Rua João Toureiro, reconstrução de\ncalçamento e muro. Rua Benedito Rocha, construção de muro de arrimo. Rua Antonio Esteves Lima, reconstrução de calçamento. Danos a\nvários pontos de rede de esgoto. Bairro Anastácio Roque- Pedro Gomes Filho , centro Rua santa Chacara , Bairro Cristo Rei Rua Santa\nChácara, construção de muro de arrimo. Travessa Amadeu Farias, reconstrução de calçamento. Igreja São Francisco, reconstrução de\ntelhado. Rua Teobaldo Leal, pavimentação asfáltica. Rede de esgotamento sanitário - Bairro Anastácio Roque- Pedro Gomes Filho , centro\nRua santa Chacara , Bairro Cristo Rei', '2025-11-10 16:00:31', '2026-01-05 16:05:40', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27494, 4530, 11, 33, 'FOI NECESSÁRIO LIMPEZA URBANA ATÍPICA, ONDE HAVIAM VÁRIAS SUJIDADES PROVENIENTES DAS FORTES ENXURRADAS, TAMBÉM HOUVE A NECESSIDADE DE RETIRADA DE BARREIRAS DE ENCOSTAS EM MUITAS RESIDÊNCIAS , TAMBÉM NA SEDE DO MUNICÍPIO HOUVE MOVIMENTAÇÃO DE TERRAS DEVIDO CHUVAS FREQUENTES. O MUNCÍPIO ESTA FAZENDO A LIMPEZA DAS VIAS URBANAS COM OS RECURSOS HUMANOS E LOGÍSTICOS EXISTENTES, FEZ CONTRATAÇÕES DE NOVOS FUNCIONÁRIOS PARA ATENDER A DEMANDA', '2025-11-10 16:00:31', '2026-01-05 16:50:12', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27495, 4700, 8, 34, NULL, '2025-11-10 17:43:07', '2025-11-10 17:43:07', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27496, 4700, 9, 34, 'Toda Zona Rural e Urbana.', '2025-11-10 17:43:07', '2025-11-10 17:43:07', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27497, 4700, 10, 34, 'Toda a população paracatuense vem sofrendo com registros de diversos incêndios em áreas de vegetação nativa e pastagens, intensificados por altas temperaturas, baixa umidade e ventos fortes. Os focos provocaram destruição ambiental, morte de animais silvestres e deterioração da qualidade do ar, afetando bairros urbanos com fumaça densa e aumento de casos respiratórios. Houve ainda riscos à\ninfraestrutura rural e às margens de rodovias, além de prejuízos à produção agropecuária e custos elevados com ações de combate e controle do fogo.\n', '2025-11-10 17:43:07', '2025-11-10 17:43:07', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27498, 4700, 1, 34, 'Toda a área rural está afetada onde concentra uma população de aproximadamente 30.000 pessoas que sofrem com os incêndios florestais. O municipio de Paracatu tem Caminhões Pipas contratados para distribuição de água na áreas afetadas, sendo assim não necessita de ajuda do Estado e da União no momento.', '2025-11-10 17:43:07', '2025-11-10 17:43:07', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27499, 4700, 3, 34, 'Os incêndios florestais que atingiram a cidade causaram uma grande degradação da qualidade do ar, perceptível em toda a área urbana e\nna zona rural. A fumaça espessa e a fuligem permaneceram por dias sobre o município, formando uma névoa constante que dificultava a\nrespiração e reduzia a visibilidade. O ar tornou-se pesado e irritante, afetando principalmente crianças, idosos e pessoas com problemas\nrespiratórios. Além do desconforto à população, a liberação de gases e partículas finas contaminou o ambiente, prejudicando a fauna, a\nflora e contribuindo para o desequilíbrio climático local. De acordo com informações do Corpo de Bombeiros Militar de Paracatu, estima-se\nque mais de 15.000 hectares de vegetação foram consumidos pelo fogo, abrangendo áreas de pastagens, matas nativas e propriedades\nrurais. Os incêndios também ocasionaram o aumento da temperatura local e da vulnerabilidade do solo à erosão, agravando os impactos\nambientais e dificultando a regeneração natural da vegetação. Observou-se ainda a perda significativa da cobertura vegetal nativa, com\nconsequente redução da biodiversidade local e morte de fauna silvestre, alterando ecossistemas inteiros e comprometendo o equilíbrio\nambiental da região. Esses efeitos deixaram uma marca visível na paisagem e na saúde coletiva, evidenciando o impacto profundo dos\nincêndios sobre o meio ambiente e a vida cotidiana dos moradores do município.', '2025-11-10 17:43:07', '2025-11-10 17:43:07', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27500, 4700, 12, 34, 'Os incêndios florestais registrados em Paracatu/MG também provocaram danos significativos à infraestrutura elétrica do município. De\nacordo com relatório emitido pela CEMIG (Companhia Energética de Minas Gerais), as chamas atingiram postes, cabos de transmissão e\noutros equipamentos da rede de distribuição, resultando em prejuízo estimado em R$ 758.312,56 (setecentos e cinquenta e oito mil,\ntrezentos e doze reais e cinquenta e seis centavos). Esses danos comprometeram o fornecimento de energia em diversas comunidades\nrurais e bairros urbanos, causando interrupções no abastecimento, prejuízos a produtores locais, estabelecimentos comerciais e serviços\npúblicos essenciais. A situação exigiu ações emergenciais de reparo e substituição de estruturas danificadas, mobilizando equipes técnicas e\ngerando custos adicionais para restabelecer a normalidade no sistema elétrico do município', '2025-11-10 17:43:07', '2025-11-10 17:43:07', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27501, 2520, 8, 35, 'Forte deslocamento de uma massa de ar em uma região.\n', '2025-11-10 18:09:01', '2025-11-10 18:09:01', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27502, 2520, 9, 35, 'Todo município de Fama, especialmente na zona urbana foi afetado pelo forte vendaval, com falta de energia, internet e rede móvel. O\nturismo foi afetado devido aos danos na marina fama e falta de energia e danos aos restaurantes que é um dos principais atrativos da\ncidade, bem como o lago de furnas.', '2025-11-10 18:09:02', '2026-01-05 14:47:02', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27503, 2520, 10, 35, 'No dia 07/11/2025, por volta das 21h33, o município de Fama foi acometido por um forte vendaval, causando danos humanos, onde\npessoas ficaram desalojadas, várias residências danificadas (destelhadas), unidades educacionais afetadas, queda do muro do cemitério\nmunicipal com danos em diversos túmulos, houve queda de energia, internet e rede móvel, por conta das quedas de postes e árvores de\ngrande porte, gerando um grande prejuízo econômico público e particular.', '2025-11-10 18:09:02', '2026-01-05 14:47:02', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27504, 2520, 1, 35, 'Cerca de 150 pessoas ficaram desalojadas e 02 desabrigadas, várias pessoas tiveram suas casas danificadas (destelhamento) e alagadas, perda de móveis, colchões, alimentos, utensílios domésticos, estradas interditadas por queda de árvores impedindo o trafego de pessoas, falta de energia elétrica do município, alguns pontos da cidade sem internet e rede móvel.', '2025-11-10 18:09:02', '2025-11-10 18:09:02', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27505, 2520, 2, 35, 'Aproximadamente 50 casas foram danificadas, com alagamentos e destelhamentos, 02 unidades escolares com danificações nos telhados,\ncoberturas e calhas, alagamento do refeitório da escola municipal Olinto Magalhães, parte da cobertura da Creche Municipal Jayr Prado teve sua estrutura removido pela força do vento, queda do muro do cemitério municipal com danos em diversos túmulos e demais levantamentos ainda em andamento.\n', '2025-11-10 18:09:02', '2026-01-05 14:47:02', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27506, 2520, 3, 35, 'Várias árvores foram arrancadas em várias partes do município. ', '2025-11-10 18:09:02', '2025-11-10 18:09:02', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27507, 2520, 11, 35, 'Houve a necessidade de abastecimento de maquinário, caminhões e equipamentos para limpeza da cidade e estradas, abastecimentos de\nmotosserras para podas de árvores', '2025-11-10 18:09:02', '2026-01-05 14:47:02', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27508, 2520, 12, 35, 'O comércio teve prejuízo com perdas em restaurantes e lojas.', '2025-11-10 18:09:02', '2025-11-10 18:09:02', NULL);
