	(27509, 3050, 8, 37, NULL, '2025-11-12 13:22:12', '2025-11-12 13:22:12', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27510, 3050, 9, 37, 'ZONA URBANA: Bairro Centro; Rua Sergipe, Rua Edson Bernardes Bairro Monsenhor Francisco Figueiredo. Bairro Glória - Represa Lagoa\nseca Travessa sentido Guapé, Praça da independência ZONA RURAL: comunidade do Capão Grande e Campinho', '2025-11-12 13:22:12', '2026-01-05 14:42:38', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27511, 3050, 10, 37, 'Chuvas intensas com vendaval e grandes volume acumulado de 85 mm que durou aproximadamente 6hr, o Município de Ilicínea recebeu na\npresente data do ocorrido 3 alertas da Defesa Civil Estadual de tempestades com raios e rajadas de vento, sendo as 9:54Hr, 11:22 Hr e 12:\n26Hr, sendo o momento mais intenso ocorrido por volta de 11:30Hr causando enxurradas, inundações danos públicos em bocas de lobo,\ndanos na pavimentação, meios fios, galerias pluviais nos endereços citados: Rua Sergipe, Bairro Centro , inundação de residências e\ncomércios; Rua Edson Bernardes, Bairro centro- Erosão em via pública; Bairro Monsenhor Francisco Figueiredo, Erosão em via pública e\ncolapso da galeria de drenagem pluvial; Bacia seca de passagem, Bairro Glória - Transbordo da bacia com erosão e movimentação de solo\ndo talude da represa causando assoreamento em uma represa secundária; Represa Lagoa seca, bairro Glória ¿ Transbordo com invasão de\nvias pública; Travessa sentido Guapé, Praça da independência ¿ Transbordo do córrego da mata. Foram um total de 15 residências com um\ntotal de 60 pessoas que foram afetadas diretamente pelas enxurradas e inundação ocasionados na Rua Sergipe na travessa do Córrego da\nMáquina, onde houve a invasão da água nas residências causando danos privados em imóveis devido o volume das águas , lamas e detritos.\nNo dia 08/11/2025 o município foi afetado novamente devido à queda de uma torre de transmissão da CEMIG que abastece o município,\ndeixando toda população sem energia elétrica, sem água potável devido as bombas não funcionarem sem energia elétrica, falta de telefonia\ne internet. Afetando diretamente 12741 pessoas existentes no município, conforme SENSO 2022, População sofreu perda de produtos\nperecíveis pela falta de energia. Inclusive os pecuaristas com fornecimento de leite e agricultores.', '2025-11-12 13:22:12', '2026-01-05 14:42:38', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27512, 3050, 1, 37, 'Foram um total de 13 residências com um total de 60 pessoas que foram afetadas diretamente pelas enxurradas e inundação ocasionados\nna Rua Sergipe casas nº 15, 25, 31, 33, 35, 47, 56, 67, 72, 80, 93, 102, 110 com travessa do Córrego da Máquina, onde houve a invasão da\nágua nas residências causando danos privados em imóveis devido o volume das águas , lamas e detritos. No dia 08/11/2025 o município foi\nafetado novamente devido à queda de uma torre de transmissão da CEMIG que abastece o município, deixando toda população sem energia\nelétrica, sem água potável devido as bombas não funcionarem sem energia elétrica, falta de telefonia e internet. Afetando diretamente\n12741pessoas existentes no município, conforme SENSO 2022, População sofreu perda de produtos perecíveis pela falta de energia.\nInclusive os pecuaristas com fornecimento de leite e agricultores', '2025-11-12 13:22:12', '2026-01-05 14:42:38', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27513, 3050, 2, 37, 'Chuvas intensas com vendaval e grandes volume acumulado de 85 mm que durou aproximadamente 6hr, o Município de Ilicínea recebeu na\npresente data do ocorrido 3 alertas da Defesa Civil Estadual de tempestades com raios e rajadas de vento, sendo as 9:54Hr, 11:22 Hr e 12:\n26Hr, sendo o momento mais intenso ocorrido por volta de 11:30Hr causando enxurradas, inundações danos públicos em bocas de lobo,\ndanos na pavimentação, meios fios, galerias pluviais nos endereços citados: Rua Sergipe, Bairro Centro ¿ inundação de residências e\ncomércios; Rua Edson Bernardes, Bairro centro- Erosão em via pública; Bairro Monsenhor Francisco Figueiredo ¿ Erosão em via pública e\ncolapso da galeria de drenagem pluvial; Bacia seca de passagem, Bairro Glória - Transbordo da bacia com erosão e movimentação de solo\ndo talude da represa causando assoreamento em uma represa secundária; Represa Lagoa seca, bairro Glória ¿ Transbordo com invasão de\nvias pública; Travessa sentido Guapé, Praça da independência ¿ Transbordo do córrego da mata. No dia 08/11/2025 o município foi afetado\nnovamente devido à queda de uma torre de transmissão da CEMIG que abastece o município, deixando toda população sem energia\nelétrica, sem água potável devido as bombas não funcionarem sem energia elétrica, falta de telefonia e internet. Afetando diretamente\n12741 pessoas existentes no município, conforme SENSO 2022, População sofreu perda de produtos perecíveis pela falta de energia.\nInclusive os pecuaristas com fornecimento de leite e agricultores.', '2025-11-12 13:22:12', '2025-11-12 13:22:12', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27514, 3050, 11, 37, 'Foram um total de 15 residência com um total de 60 pessoas que foram afetadas diretamente com enxurradas e inundação ocasionados na\nRua Sergipe na travessa do Córrego da Máquina, onde ouve a invasão da água nas residências causando danos e privados em imóveis e\nutensílios domésticos e outros devido o volume das águas , lamas e detritos. Moradores tiveram que fazer buracos em muros para permitir\no escoamento da água acumulada e prevenir danos maiores . Os moradores tiveram que fazer buracos nas paredes e muros para agua sair\ndas casas. Os moradores não necessitaram sair dos imóveis devido terem realizado a limpeza. No dia 08/11/2025 o município foi afetado\nnovamente devido à queda de uma torre de transmissão da CEMIG que abastece o município, deixando toda população sem energia\nelétrica, sem água potável devido as bombas não funcionarem sem energia elétrica, falta de telefonia e internet. Afetando diretamente\n12741 pessoas existentes no município, conforme SENSO 2022, População sofreu perda de produtos perecíveis pela falta de energia.\nInclusive os pecuaristas com fornecimento de leite e agricultores. ZONA RURAL: Chuvas Intensas, que causou queda de árvores obstruindo\naa estrada da comunidade do Capão Grande e Campinho afetando diretamente os moradores locais dessa região que utilizam o local para\nacessibilidade', '2025-11-12 13:22:12', '2025-11-12 13:22:12', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27515, 3050, 12, 37, 'No dia 08/11/2025 o município foi afetado novamente devido à queda de uma torre de transmissão da CEMIG que abastece o município,\ndeixando toda população sem energia elétrica, sem água potável devido as bombas não funcionarem sem energia elétrica, falta de telefonia\ne internet. Afetando diretamente 12741 pessoas existentes no município, conforme SENSO 2022, População sofreu perda de produtos\nperecíveis pela falta de energia. Inclusive os pecuaristas com fornecimento de leite e agricultores. Danos ainda não contabilizados devido a\ndimensão do evento', '2025-11-12 13:22:12', '2025-11-12 13:22:12', NULL);
