INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27549, 2810, 9, 43, 'ZONA URBANA: Rua Dona Leopoldina Maia nº 435, centro queda de muro que divide o Pelotão PM com Forúm; Avenida Brasil Igreja Matriz, centro quedas de árvore em cima fiação elétrica; Rua Professor Antônio Bernardes nº 400, centro queda de árvore em cima do muro da residência; Rua Mário Rocha (Praça Bangalo) queda de uma árvore destruiu banco de cimento, danificou poste de luminária; queda de árvore na estrada do barreirinho causando obstruindo a via. Devido queda de torre de distribuição energia todo município ficou sem energia por mais de 30 horas, afetando diretamente as redes de telefonia, abastecimento de água potável e internet.', '2025-11-13 12:52:27', '2025-11-13 12:52:27', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27550, 2810, 10, 43, 'Chuvas intensas com vendaval que atingiu o município na madrugada do dia 08/11/2025 e outra chuva intensa com ventos acima de 60 km/h que ocorreu por volta das 14:00 horas do dia 08/11/2025 que causou diversos danos e derrubou no município de Coqueiral uma torre de transmissão da CEMIG que leva energia para o município de Guapé afetando toda população, sendo aproximadamente 13.838 pessoas.', '2025-11-13 12:52:27', '2025-11-13 12:52:27', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27551, 2810, 1, 43, 'Toda População afetada sendo aproximadamente 13.838 pessoas, que devido chuvas intensas com vendaval que atingiu o município na madrugada do dia 08/11/2025 e outra chuva intensa com ventos acima de 60 km/h que ocorreu por volta das 14:00 horas do dia 08/11/2025 que derrubou no município de Coqueiral uma torre de transmissão da CEMIG que leva energia para o município de Guapé, deixando todos sem energia elétrica, água potável, internet e telefonia. Muitos moradores, fazendeiros e comerciantes por todo município  perderam produtos perecíveis devido ficarem por mais de 30 horas sem energia elétrica.', '2025-11-13 12:52:27', '2025-11-13 12:52:27', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27552, 2810, 2, 43, 'Devido a chuva intensa, da madrugada do dia 08/11/2025, onde o volume da enxurradas derrubou muro dos fundos do quartel da Policia Militar que faz divisão com fórum local. Localizado na  rua dona Leopoldina maia, N435, centro e na  Rua Mário Rocha (Praça Bangalo) queda de uma árvore que  destruiu um banco de cimento, e  danificou um  poste de luminária.', '2025-11-13 12:52:27', '2025-11-13 12:52:27', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27553, 2810, 3, 43, 'Não Houve, no entanto devido a chuva forte com vendaval, ocorreu diversas quedas de arvores em vários locais do município, principalmente zona rural.', '2025-11-13 12:52:27', '2025-11-13 12:52:27', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27554, 2810, 11, 43, 'Devido as chuvas com vendaval onde deixou o município sem energia por mais de 30 horas, onde o hospital Santa casa de misericórdia de Guapé, gastou diesel em um gerador, para  manter a energia no local. foi gasto com limpeza urbana, maquinários, agentes, transporte, combustíveis e desobstrução de vias dos locais que houve quedas de arvores.', '2025-11-13 12:52:27', '2025-11-13 12:52:27', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27555, 2810, 12, 43, 'Houve perdas nos setores de agricultura, pecuária, indústria, comercio e serviços devido a falta de energia, porem como afetou toda a cidade não teve como estimar o prejuízo.', '2025-11-13 12:52:27', '2025-11-13 12:52:27', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
