	(27590, 6130, 10, 49, 'O evento adverso registrado no município de São Francisco de Sales/MG foi caracterizado por um vendaval acompanhado de chuva intensa, ocorrido em [inserir data do evento, se desejar].\nO fenômeno teve duração média de aproximadamente 20 minutos, sendo marcado por ventos fortes, sem velocidade registrada, e precipitação volumosa concentrada em curto intervalo de tempo.', '2025-11-13 13:27:27', '2025-11-13 13:27:27', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
