INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27592, 4590, 9, 50, 'Bairros primeiro de maio e metalúrgicos, dois destelhamentos de imóvel com área total de mais de 100m², seis quedas de árvores afetando muros e telhados, sendo uma dessas caiu sobre a rede elétrica e no ponto de ônibus localizado na rua itabirito, permanecendo interditada por mais de 24h até atendimento da CEMIG. Nas mesmas localidades tivemos dois equipamentos de aquecedor solar que deslocaram da parte superior do imóvel, sem maiores danos.', '2025-11-13 13:31:04', '2025-11-13 13:31:04', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27593, 4590, 10, 50, 'Devido às chuvas de 20mm/h e vendavais com média de 20km/h com picos de rajadas de vento com mais de 100km/h que atingiram o município de Ouro Branco nos últimos dias 04 e 05 de Novembro de 2026, a Coordenadoria Municipal de Proteção e Defesa Civil foi acionada em diversas ocorrências pela cidade. Tais números foram registrados nas estações climáticas localizadas no Alto da Serra de Ouro Branco e na base da Coordenadoria Municipal de Proteção e Defesa Civil. ', '2025-11-13 13:31:04', '2025-11-13 13:31:04', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27594, 4590, 1, 50, 'Este número está relacionado aos moradores dos imóveis que foram destelhados no bairro primeiro de Maio e aos moradores da comunidade rural no bairro campestre, que ficaram com acesso limitado devido aos eucaliptos e sem energia elétrica por aproximadamente 72h.', '2025-11-13 13:31:04', '2025-11-13 13:31:04', NULL);
