INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27597, 3800, 9, 51, 'ZONA URBANA: \n\nCENTRO: \nRUA: PEDRO VAIRO BERNO, Nº280 - Danificação do telhado imóvel residencial;\nRUA: ZILDA, GARCIA MENDES, Nº480 - Danificação do telhado imóvel residencial;\nRUA GUSTAVO GARCIA DA SILVA, Nº 75 - Danificação do telhado imóvel residencial;\nRUA: ANTÔNIO JOSÉ DO BEM, Nº 120 - Danificação do telhado imóvel residencial;\nRUA: PRESIDENTE GETÚLIO VARGAS, Nº 50 - Danificação do telhado imóvel residencial;\nRUA EUPÍDIO LIMA, Nº 10 - Danificação do telhado imóvel residencial; RUA: MARIA SOARES DA SILVA, S/Nº - Danificação dos telhados de dois prédios da Secretaria Municipal de Saúde; Danificação do telhado da Capela Mortuária; Danificação do Telhado da sede do SAMU, bem como muro de divisa, localizado nos fundos deste imóvel;\nRUA: OSCAR ESPINDOLA, S/Nº - Danificação da parte Elétrica do Cemitério Municipal \nRUA: EUPÍDIO LIMA, S/Nº - Danificação do muro de divisa do Campo de Futebol Municipal XV de novembro;\nRUA: EUPÍDIO LIMA, Nº10 - Danificação do telhado imóvel residencial;\nRUA JEREMIAS DIAS DE OLIVEIRA - Queda de galhos e/ou arvores localizados em 08 PONTOS PRÓXIMOS AO PARQUE DE EXPOSIÇÃO, 08 PONTOS EM FRENTE E ATRÁS DA SEDE DA SECRETARIA DE ASSISTÊNCIA SOCIAL DO MUNICÍPIO E DA SEDE DO PROJETO CURUMIN);\nESTRADA VICINAL QUE DÁ ACESSO A COMUNIDADE DO CRISTAL, NA ALTURA DA REPRESA DA COPASA (AINDA NA ÁREA URBANA) - dois pontos com queda de galhos e/ou arvores.\n\nBAIRRO NORBERTO BERNO\nRUA FRANCISCO GAMA ABREU, Nº205 - Danificação do telhado imóvel residencial\n\n\nZONA RURAL:\n\nESTRADA VICINAL QUE LIGA A COMUNIDADE PONTE NOVA (04 PONTOS COM Queda de galhos e/ou arvores: NA ALTURA PRÓXIMO AO SITIO DO SR. MOISES; NA ALTURA PRÓXIMO AO SITIO DO SR. WELLINGTON; NA ALTURA DO SITIO DO SR. WILLIAN E NA ALTURA DO SITIO DO SR. GILBERTO); \n\nESTRADA VICINAL QUE DÁ ACESSO A COMUNIDADE DE ARACATI, PRÓXIMO A PONTE VELHA, AO LADO DO SITIO DO SR. JEOVÁ - Queda de galhos e/ou arvores\n\nESTRADA VICINAL QUE DÁ ACESO A COMUNIDADE DUAS BARRAS (03 PONTOS PRÓXIMO AO SITIO DO SR. TARCÍSIO E 14 PONTOS Queda de galhos e/ou arvores - PRÓXIMO A FAZENDA DUAS BARRAS).', '2025-11-13 13:38:50', '2025-11-13 13:38:50', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27598, 3800, 10, 51, 'Por volta das 16h00min do dia 04 de novembro de 2025, ocorreu um evento climático caracterizado como Tempestade Local/Convectiva, acompanhada de vendaval, que atingiu áreas urbanas e rurais do município de Laranjal/MG. O fenômeno teve duração aproximada de 40 (quarenta) minutos e em decorrência dos fortes ventos foram registrados diversos pontos de queda de galhos e/ou arvores nas áreas afetadas, que inclusive bloquearam vias públicas. Tal evento, trouxe ainda danificações a imóveis públicos e privados', '2025-11-13 13:38:50', '2025-11-13 13:38:50', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27599, 3800, 1, 51, 'Tempestade local/convectiva, acompanhada de vendaval atingiu áreas urbanas e rurais do município de Laranjal - MG, por volta das 16h00min do dia 04 de novembro de 2025.  A Secretaria de Assistência Social após levantamentos, contabilizou 12 pessoas desalojadas em decorrência dos destelhamentos de imóveis (essas pessoas temporariamente estão em casa de parentes/amigos), não foram registrados nenhuma pessoa desabrigada, estima-se que 450 pessoas foram afetadas direta e indiretamente pelo desastre.', '2025-11-13 13:38:50', '2025-11-13 13:38:50', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27600, 3800, 2, 51, 'A TEMPESTADE LOCAL/CONVECTIVA, ACOMPANHADA DE VENDAVAL ATINGIU ÁREAS URBANAS E RURAIS DO MUNICÍPIO DE LARANJAL - MG, POR VOLTA DAS 16H00MIN DO DIA 04 DE NOVEMBRO DE 2025, DURANDO CERCA DE 40 MINUTOS. \n\nO SERVIÇO DE ENGENHARIA DA PREFEITURA ESTIMA QUE PARA RECUPERAR TODO O CENÁRIO, SERÁ NECESSÁRIO O MONTANTE DE R$212.000,00 (DUZENTOS E DOZE MIL REAIS), CONFORME SE PODE OBSERVAR ABAIXO DISCRIMINADO:\n\n1) RECUPERAÇÃO DO TELHADO DO PRÉDIO DA SECRETÁRIA MUNICIPAL DE SAÚDE DE LARANJAL -MG, SITUADO A RUA: MARIA SOARES DA SILVA, S/Nº, CENTRO,  ONDE SERÃO NECESSÁRIOS O APORTE DE R$45.000,00 (QUARENTA E CINCO MIL REAIS). ALÉM DISSO EXISTE NECESSIDADE DE RECUPERAR O TELHADO DA SEDE DO SAMU DE LARANJAL -MG, QUE PERTENCE A PREFEITURA, BEM COMO UMA PEQUENO MURETA LOCALIZADO NA PARTE DOS FUNDOS DO REFERIDO IMÓVEL, SITUADO A RUA: MARIA SOARES DA SILVA, S/Nº, CENTRO,  ONDE TAMBÉM SERÃO NECESSÁRIO O APORTE DE R$22.000,00 (VINTE E DOIS MIL REAIS);\n\n2) RECUPERAÇÃO DO TELHADO DA CAPELA MORTUÁRIA MUNICIPAL, SITUADO A RUA: MARIA SOARES DA SILVA, S/Nº, CENTRO, SERÃO NECESSÁRIOS O APORTE DE R$10.000,00 (DEZ MIL REAIS). RECUPERAÇÃO DE DOIS POSTES DE ILUMINAÇÃO, SITUADO A RUA: OSCAR ESPINDOLA, S/Nº, CENTRO, ONDE SERÃO NECESSÁRIO O APORTE DE R$20.000,00(VINTE MIL REAIS). RECUPERAÇÃO DO MURO DE DIVISA DO CAMPO DE FUTEBOL MUNICIPAL XV DE NOVEMBRO, SITUADO A RUA: EUPÍDIO LIMA, S/Nº, CENTRO, ONDE SERÃO NECESSÁRIOS O APORTE DE R$45.000,00 (QUARENTA E CINCO MIL REAIS).\n\n3) POR FIM RECUPERAÇÃO DOS TELHADOS DE 07 IMOVEIS RESIDENCIAIS, SITUADOS NOS SEGUINTES ENDEREÇOS (01 - RUA: PEDRO VAIRO BERNO, Nº280, CENTRO; 02 - RUA: ZILDA, GARCIA MENDES, Nº480, CENTRO; 03 - RUA FRANCISCO GAMA ABREU, Nº205, BAIRRO NORBERTO BERNO; 04 - RUA GUSTAVO GARCIA DA SILVA, Nº 75, CENTRO;  05 - RUA: ANTÔNIO JOSÉ DO BEM, Nº 120, CENTRO; 06 - RUA: PRESIDENTE GETÚLIO VARGAS, Nº 50, CENTRO E 07 - RUA EUPÍDIO LIMA, Nº 10, CENTRO, ONDE SERÃO NECESSÁRIOS O APORTE DE R$70.000,00 (SETENTA MIL REAIS).', '2025-11-13 13:38:50', '2025-11-13 13:38:50', NULL);
