	(27601, 3800, 3, 51, 'A Tempestade local/convectiva, acompanhada de vendaval atingiu áreas urbanas e rurais do município de Laranjal - MG, por volta das 16h00min do dia 04 de novembro de 2025, durando cerca de 40 minutos, ENTRETANTO, O PRESENTE EVENTO, NÃO CAUSOU DANOS AMBIENTAIS. ', '2025-11-13 13:38:50', '2025-11-13 13:38:50', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27602, 3800, 11, 51, 'A Tempestade local/convectiva, acompanhada de vendaval atingiu áreas urbanas e rurais do município de Laranjal - MG, por volta das 16h00min do dia 04 de novembro de 2025, durando cerca de 40 minutos. Para tanto, a Prefeitura empregou boa parte do efetivo da Secretaria de Obras com veículos leves, veículos pesados e maquinário pesado, que foram usados para limpar e/ou desobstruir vias públicas em decorrência de grande quantidade de queda de galhos e/ou arvores nas áreas afetadas. Além disso, equipes da COMPDEC e da Secretaria de Assistência Social percorreram todos os pontos afetados e tiveram contato com a população atingida pelo evento. Assim, foram gastos cerca de R$2.300,00 (dois mil e trezentos reais para abastecer os veículos utilizados para responde o sinistro).', '2025-11-13 13:38:50', '2025-11-13 13:38:50', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
