	(27624, 960, 9, 55, 'Foram constatados diversos danos materiais diretamente relacionados à força dos ventos e às chuvas intensas. O evento afetou vários bairros urbanos, ocasionando prejuízos tanto em edificações públicas quanto privadas.', '2025-11-13 14:10:11', '2025-11-13 14:10:11', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
