INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27628, 6570, 9, 56, 'Rua Padre Jacinto - Bairro Centro, Rua Anônio Braz - Bairro Centro, Rua Levindo Coelho - Bairro Centro, Rua Hortencio Vilela - Bairro Centro, Rua Rubi - Bairro Chacara', '2025-11-13 14:24:49', '2025-11-13 14:24:49', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27629, 6570, 10, 56, 'O evento adverso ocorrido em 30/10/2025 foi caracterizado por uma chuva intensa de curta duração, acompanhada de alto volume de precipitação e forte enxurrada, o que provocou alagamentos em diversos pontos do centro da cidade e deslizamento de material em áreas de morro.\n\nA magnitude do evento foi evidenciada pelo acúmulo rápido de água nas vias públicas, transbordamento de bocas de lobo, carreamento de lama e resíduos sólidos, além da danificação de pavimentações asfálticas e calçamentos. O volume de chuva excedeu a capacidade de drenagem urbana, resultando em interrupção temporária do tráfego, alagamento de estabelecimentos comerciais e danos à infraestrutura pública.', '2025-11-13 14:24:49', '2025-11-13 14:24:49', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27630, 6570, 2, 56, 'Foram identificados danos em diferentes vias do município, sendo eles:\n\nRua Antônio Braz, Bairro Centro ¿ presença de grande acúmulo de lama e fissuras no pavimento asfáltico;\n\nOs danos materiais observados apresentam relação direta com os efeitos do evento de alagamento ocorrido em 30/10/2025, conforme segue:\n\nRua Antônio Braz ¿ Bairro Centro: o grande volume de água das chuvas arrastou lama e detritos, ocasionando acúmulo de sedimentos e trincas no pavimento asfáltico, comprometendo a trafegabilidade.\n\nRua Levindo Coelho ¿ Bairro Centro: a enxurrada formou correnteza intensa, que resultou em depósito de lama e fissuras no asfalto, exigindo limpeza e posterior recuperação do pavimento.\n\nRua Rubi ¿ Bairro Chácara: o escoamento superficial da água provocou erosão na base do calçamento, levando ao deslocamento de blocos e afundamento parcial da via.\n\nRua Padre Jacinto: a força da água e o carreamento de material sólido causaram o afundamento parcial da galeria pluvial, comprometendo a estrutura de drenagem e aumentando o risco de novos desabamentos.\n\nEsses danos são consequência direta da chuva intensa e do escoamento superficial concentrado, que superaram a capacidade de drenagem urbana.', '2025-11-13 14:24:49', '2025-11-13 14:24:49', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27631, 6570, 3, 56, NULL, '2025-11-13 14:24:49', '2025-11-13 14:24:49', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27632, 6570, 11, 56, 'O alagamento ocorrido em 30/10/2025 provocou o acúmulo de lama e detritos nas vias públicas, exigindo a mobilização imediata de equipes e maquinários da Secretaria de Obras para realizar a limpeza e desobstrução das ruas afetadas.\nEsse trabalho envolveu o uso de caminhões, retroescavadeiras e mão de obra operacional, resultando em custos adicionais de combustível, horas extras de servidores e desgaste de equipamentos públicos, configurando, assim, prejuízo econômico direto ao município.', '2025-11-13 14:24:49', '2025-11-13 14:24:49', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27633, 6570, 12, 56, 'O alagamento ocorrido em 30/10/2025 atingiu diretamente estabelecimentos comerciais localizados na região central da cidade, ocasionando a entrada de água e lama em seus interiores. O efeito do desastre resultou em prejuízos econômicos privados relacionados à necessidade de limpeza dos imóveis, descarte de mercadorias molhadas e interrupção temporária das atividades comerciais.', '2025-11-13 14:24:49', '2025-11-13 14:24:49', NULL);
