INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27703, 420, 9, 69, 'Comunidade São Domingos, zona rural do Município de Arcos.', '2025-11-13 17:03:23', '2025-11-13 17:03:23', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27704, 420, 10, 69, 'Incêndio Florestal na zona rural do Município de Arcos na comunidade São Domingos.\n\nNo dia 07 de outubro de 2025 as 11: 47hs a Defesa Civil Foi acionadas e compareceu em incêndio florestal na zona rural do município de Arcos na comunidade São Domingos "448771.97 m E 7759870.70 m S".\n\n As chamas atingiram uma área de 74,30 hectares em um perímetro 5.959m, com várias frentes ativas, consumindo completamente as postagens de Braquiária, Capim Napiê, plantação de eucalipto, reserva legal, e Áreas de Preservação Permanente A.P.P. As chamas queimaram um poste e ocorreu a queda de fiação da CEMIG, queima cercas de várias propriedades, as chamas atingiram as copas de árvores, o incêndio destruiu cercas em varia propriedades, também consumiu madeiras. O incêndio durou 02 dias e duas noites. No combate foi utilizado água, abafadores, sopradores, enxada. Além do combate direto para controle das chamas, foi realizado acero em diversos terrenos para evitar a propagação das chamas. Os trabalhos durante a noite foram realizados pela COMPDEC, com a finalidade de garantir que as chamas não atingissem as áreas habitadas próximas. Um senhor idoso foi orientado a não permanecer em sua residência devido ao risco e a má qualidade do ar proveniente dos gases e foliem gerado pelo incêndio.', '2025-11-13 17:03:23', '2025-11-13 17:03:23', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27705, 420, 1, 69, 'O incêndio provocou chamas em várias frentes ativas atingiram áreas de diversas propriedades, consumindo completamente as pastagens. no decorrer da operação as pessoas ficaram em pânico devido a incerteza do evento. com a baixa humidade relativa do ar e o tempo seco associada as altas temperaturas o ar ficou comprometido devido o grande volume de monóxido e ou dióxido de carbono somado a grande quantidade de particulado gerado pela fuligem proveniente da queimada o ar ficou impróprio para respiração. ', '2025-11-13 17:03:23', '2025-11-13 17:03:23', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27706, 420, 2, 69, 'As chamas queimaram um poste e ocorreu a queda de fiação da CEMIG.\n', '2025-11-13 17:03:23', '2025-11-13 17:03:23', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27707, 420, 3, 69, 'O ar ficou comprometido devido o grande volume de monóxido e ou dióxido de carbono somado a grande quantidade de particulado gerado pela fuligem proveniente da queimada o ar ficou impróprio para respiração. com a queima de A.P.P.s, Reserva Legal Florestal, e grotas, afetou consideravelmente a fauna e flora.', '2025-11-13 17:03:23', '2025-11-13 17:03:23', NULL);
