INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27724, 3440, 9, 73, 'O vazamento de óleo ocorrido na subestação de energia da empresa ISA Energia, situada dentro da área operacional da Usina Hidrelétrica Auren (UHE Água Vermelha), atingiu diretamente a Área de Preservação Permanente (APP) do Rio Grande, em território do município de Iturama/MG.\n\nA contaminação se estendeu por aproximadamente 12,5 km de margem do rio, afetando propriedades rurais e comunidades ribeirinhas localizadas ao longo do trecho impactado.\n\nEntre os principais grupos atingidos estão:\n\nPescadores profissionais e amadores, fixos e flutuantes, que exercem atividades de pesca e subsistência nas margens do Rio Grande;\n\nFamílias ribeirinhas que utilizam a água do rio para consumo e pequenas atividades domésticas;\n\nProdutores rurais que realizam captação de água para irrigação de lavouras e dessedentação de animais, cujas captações ficaram comprometidas em razão da contaminação;\n\nÁreas de vegetação ciliar e APP, com risco de contaminação do solo e prejuízos à fauna aquática e terrestre.\n\nO trecho afetado compreende zona de uso misto (residencial ribeirinho e rural produtiva), de relevância ambiental e socioeconômica para o município.', '2025-11-13 17:20:29', '2025-11-13 17:20:29', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27725, 3440, 3, 73, 'Registro detalhado dos danos ambientais e efeitos do desastre\n\nContaminação das águas do Rio Grande\n\nDano: Vazamento de óleo sobre a superfície da água, formando filme oleoso.\n\nEfeito direto: Redução da qualidade da água, comprometendo oxigenação, toxicidade para organismos aquáticos.\n\nImpacto na população/ecossistema: Mortandade de peixes e crustáceos; diminuição da pesca profissional e amadora; risco de contaminação da água utilizada para consumo, irrigação e atividades agrícolas.\n\nComprometimento das Áreas de Preservação Permanente (APP)\n\nDano: Penetração do óleo na vegetação ripária e margens do rio.\n\nEfeito direto: Quebra da função protetora das APPs (controle de erosão, filtração de poluentes, abrigo da fauna).\n\nImpacto na população/ecossistema: Perda de habitat para fauna local (peixes, aves, anfíbios); risco de erosão e assoreamento; redução da biodiversidade e serviços ambientais essenciais para a comunidade ribeirinha.\n\nContaminação do solo nas áreas rurais adjacentes\n\nDano: Infiltração do óleo no solo de propriedades agrícolas.\n\nEfeito direto: Redução da fertilidade do solo, toxicidade para plantas, contaminação de lençóis freáticos.\n\nImpacto na população/ecossistema: Perda temporária ou permanente de áreas produtivas; risco à saúde de agricultores; impacto econômico para famílias dependentes da agricultura.\n\nImpacto na fauna aquática e terrestre\n\nDano: Contato direto de animais com óleo, ingestão acidental e envenenamento.\n\nEfeito direto: Mortalidade de peixes, crustáceos, anfíbios e aves; alterações nos ciclos reprodutivos.\n\nImpacto na população/ecossistema: Redução de recursos pesqueiros; desequilíbrio ecológico; perda de subsistência para pescadores tradicionais.\n\nImpacto socioeconômico para pescadores e ribeirinhos\n\nDano: Perda de acesso a áreas de pesca e contaminação do pescado.\n\nEfeito direto: Suspensão temporária ou redução da atividade pesqueira.\n\nImpacto na população/ecossistema: Comprometimento da renda familiar; insegurança alimentar; aumento da vulnerabilidade socioeconômica de comunidades ribeirinhas.', '2025-11-13 17:20:29', '2025-11-13 17:20:29', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27726, 6720, 8, 74, NULL, '2025-11-13 17:24:39', '2025-11-13 17:24:39', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27727, 6720, 10, 74, 'A GU BM DESLOCOU PARA 5º DIA DE OPERAÇÃO DE INCÊNDIO FLORESTAL EM UNIDADE DE CONSERVAÇÃO MUNICIPAL SERRA DE\nSANTA HELENA, MUNICÍPIO DE SETE LAGOAS/MG, CONFORME REGISTROS REDS NÚMEROS 2025-045498734-001 ATÉ 2025-\n045498734-012.\nGUBM FOI DIVIDIDAS EM TRÊS GCIFS. DUAS DELAS FORAM PARA A ÁREA DA TRILHA DA ESQUERDINHA PARA MONITORAMENTO E\nAVALIAÇÃO DA REGIÃO E VERIFICAÇÃO DE POTENCIAIS FOCOS SECUNDÁRIOS OU REIGNIÇÃO. FOI LOCALIZADA UMA FUMAÇA NAS\nPROXIMIDADES E FOI REALIZADO UM SOBREVOO DE DRONE PELO SGT RICARDO (GUARDA DA SEDE ADMINISTRATIVA, EMPENHADO\nPARA FIM ESPECÍFICO DE RPA) PARA MELHOR AVALIAÇÃO. FEITO ISSO, FOI CONSTATADO QUE A FUMAÇA PROVINHA DE TRONCOS DE ÁRVORE FUMEGANDO EM ÁREA QUEIMADA. POR VOLTA DAS 11:30, AS GCIFS SUBIRAM AO POSTO DE COMANDO PARA ALMOÇO. APÓS O ALMOÇO, FOI REALIZANDO UM NOVO SOBREVOO DE DRONE, SOB ORIENTAÇÃO DO COMANDANTE DA OPERAÇÃO, SENDO LOCALIZADO PRÓXIMO A REGIÃO DA CASCATA ALGUNS TRONCOS FUMEGANDO, SENDO REALIZADO RESCALDO DESSA REGIÃO PARA MITIGAR RISCOS DE REIGNIÇÃO E COMBATER ALGUNS FOCOS SECUNDÁRIOS. ADEMAIS, PRÓXIMO AO BAIRRO DA ALVORADA, TAMBÉM HOUVE UM TERCEIRO FOCO DE INCÊNDIO QUE FOI DETECTADO NO DIA ANTERIOR, PORÉM NESTE DIA DE OPERAÇÃO, O FOCO JÁ HAVIA SIDO DEBELADO, RESTANTO ÀS GCIF DO DIA APENAS MONITORAMENTO. NO LOCAL, TRATAVA-SE DE UMA ÁREA DE BIOMA CERRADO, COM CARACTERÍSTICAS DE VEGETAÇÃO TÍPICAS DO CERRADO SENSU STRICTO, INCLUINDO VEGETAÇÃO DE MATA SECA COM ÁRVORES RETORCIDAS, ARBUSTOS, VEGETAÇÃO HERBÁCEA E MATA DE GALERIA NAS ÁREAS MAIS BAIXAS. REGISTROU-SE CONSUMO DE VEGETAÇÃO NATIVA E SECUNDÁRIA, INCLUINDO ÁREAS DE MATA CILIAR E TRECHOS DE VEGETAÇÃO DENSA EM REGIÃO DE GROTA. COMO O DIA FOI APENAS DE MONITORAMENTO E RESCALDO DE FOCOS SECUNDÁRIOS OU TRONCOS FUMEGANDO, NÃO HÁ O QUE SE FALAR DE LINHA DE INCÊNDIO. O VENTO PREDOMINANTE ESTAVA NO SENTIDO NORDESTE-SUDOESTE, COM 13 KM/H, COM TEMPERATURA ESTIMADA DE 29°C E UMIDADE RELATIVA DO AR MÍNIMA EM TORNO DE 36%. VERIFICOU-SE QUE SE TRATAVA DE INCÊNDIO SUPERFICIAL. A GU BM, COM USO DE ABAFADORES, MOCHILAS COSTAIS, SOPRADORES PARA ATAQUE DIRETO ÀS CHAMAS REALIZOU COMBATE E RESCALDO DO INCÊNDIO DURANTE 13HORAS E 10 MINUTOS QUE A CAUSA SEJA ANTRÓPICA E QUE, SEGUNDO RELATOS DOS BRIGADISTAS, TENHA COMEÇADO EM ALGUM PONTO DA BR040. NO LOCAL, HAVIA ACEIROS E HAVIA INDÍCIOS DE ACÚMULO DE COMBUSTÍVEL. FORAM GASTOS CERCA DE 60 LITROS DE ÁGUA, EQUIVALENTE A 3 BOMBAS COSTAIS UTILIZADAS PARA OS RESCALDOS. A ÁREA QUEIMADA TOTAL FOI DE XXX HEC DE ACORDO COM O MÉTODO DE AFERIÇÃO: COPERNICUS BROWSER. O INCÊNDIO CAUSOU DANOS CONSIDERÁVEIS À VEGETAÇÃO NATIVA DE CERRADO, COM PERDA DE ÁREAS DE MATA CILIAR E VEGETAÇÃO DE GROTA. AS EQUIPES BM RECEBERAM APOIO DO EXÉRCITO BRASILEIRO E DOS BRIGADISTAS DA BRIGADA BH. ALÉM DISSO, HOUVE APOIO AÉREO DO BOA. O COMANDO DA OPERAÇÃO FOI DO MAJOR LUIZ PAULO, UNIDADE BM RESPONSÁVEL: 1ºCOB/5ª CIA IND/1ºPEL - SETE LAGOAS. O SISTEMA DE COMANDO EM OPERAÇÕES (SCO) FOI INSTALADO E FUNCIONOU COM COORDENAÇÃO ESTRATÉGICA DURANTE OS 5 DIAS DE ATUAÇÃO. AS ALAS DOS DIAS CONSECUTIVOS FORAM ORIENTADAS A REALIZAREM MONITORAMENTO NA REGIÃO PARA AVERIGUAR A EXISTÊNCIA DE REIGNIÇÃO E MITIGAR POSSÍVEIS RISCOS DE FOCOS SECUNDÁRIOS, MESMO APÓS O TÉRMINO DA OPERAÇÃO .\n05:30: APRESENTAÇÃO E PREPARAÇÃO DA TROPA BM.\n06:00: CHEGADA DA AERONAVE ARCANJO 02 E INÍCIO DO RECONHECIMENTO NOS PONTOS DOS FOCOS.\n06:40: CHEGADA DA TROPA DO EB PARA APOIO.\n08:30: GCIFS REALIZANDO RESCALDO NAS TRÊS FRENTES.\n13:30: VÔO DE RECONHECIMENTO COM O ARCANJO 02.\n14:00: RETORNO DO ARCANJO 02 PARA BH\n15:00: DESMOBILIZAÇÃO DO EB\n16:00: CONTINUIDADE DO RESCALDO E MONITORAMENTO PELOS MILITARES BM\n18:40: DESMOBILIZAÇÃO DO PC E PLANEJAMENTO PARA CONTINUIDADE DO MONITORAMENTO.', '2025-11-13 17:24:39', '2025-11-13 17:24:39', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27728, 6720, 3, 74, 'LOCALIZAÇÕES DOS FOCOS DE INCÊNDIO REMANESCENTES\nFOCO 1 (FRENTE CASCATA): 19°27\'19.89"; S, 44°16\'53.05"; W\nFOCO 2 (FRENTE TORRE): 19°27\'27.4" S, 44°16\'32.2" W\nFOCO 3 (REGIÃO DO ALVORADA): 19°25\'19" S, 44°15\'37" W', '2025-11-13 17:24:39', '2025-11-13 17:24:39', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27729, 6720, 8, 75, NULL, '2025-11-13 17:28:03', '2025-11-13 17:28:03', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27730, 6720, 10, 75, 'HISTÓRICO TÉCNICO 4º DIA DE OPERAÇÕES DE COMBATE A INCÊNDIO FLORESTAL APA SERRA DE SANTA HELENA SETE\nLAGOAS/MG\nNO QUARTO DIA DE OPERAÇÕES DE *RESPOSTA AO DESASTRE AMBIENTAL*, OS MILITARES DO CORPO DE BOMBEIROS MILITAR\nDE MINAS GERAIS (CBMMG) APRESENTARAM-SE ÀS 05H00 NA SEDE DA 5ª COMPANHIA OPERACIONAL INDEPENDENTE, COM A\nFINALIDADE DE REALIZAR DESLOCAMENTO PARA A *ÁREA DE PRESERVAÇÃO AMBIENTAL (APA) SERRA DE SANTA HELENA*,\nMUNICÍPIO DE SETE LAGOAS/MG, OBJETIVANDO A *CONTINUIDADE DAS AÇÕES DE COMBATE AO INCÊNDIO FLORESTAL* QUE\nACOMETIA A REFERIDA UNIDADE DE CONSERVAÇÃO, CUJA GESTÃO É DE RESPONSABILIDADE MUNICIPAL.\nAS GUARNIÇÕES CHEGARAM POR VOLTA DAS 06H00 AO PONTO DE APOIO LOGÍSTICO ESTABELECIDO NO ESTACIONAMENTO DO\nPARQUE, NAS PROXIMIDADES DO POSTO DE COMANDO (PCO). APÓS REALIZAÇÃO DE BRIEFING OPERACIONAL E DEFINIÇÃO DAS ESTRATÉGIAS TÁTICAS DE COMBATE, AS\nEQUIPES FORAM ORGANIZADAS EM DUAS FRENTES PRINCIPAIS:\n1. *PRIMEIRA FRENTE DE COMBATE**, SOB O COMANDO DO CAPITÃO JEFERSON E TENENTE EDUARDO, ATUOU COM LINHA\nDIRETA DE COMBATE NAS PROXIMIDADES DA TRILHA DENOMINADA "CACHORRO LOUCO";\n2. *SEGUNDA FRENTE DE COMBATE*, SOB O COMANDO DO TENENTE MATEUS NEVES, TEVE COMO MISSÃO O COMBATE À FRENTE\nDE FOGO ORIUNDA DA BR-040, EM DIREÇÃO AO PARQUE DA CASCATA.\nDURANTE O ANDAMENTO DAS AÇÕES, FOI VERIFICADO QUE A LINHA DE FOGO PROVENIENTE DA BR-040 TRANSPASSOU O ACEIRO\nCONSTRUÍDO PREVIAMENTE E SE BIFURCOU:\n* A PRIMEIRA FRENTE ATINGIU A ENCOSTA DA SERRA VOLTADA PARA A ZONA URBANA,\nLOCAL DE DIFÍCIL ACESSO E TERRENO ÍNGREME, INVIABILIZANDO O COMBATE DIRETO E EXIGINDO **AÇÕES DE MONITORAMENTO\nESTRATÉGICO**;\n* A SEGUNDA FRENTE SEGUIU EM DIREÇÃO NOROESTE, SENDO COMBATIDA PELA EQUIPE POSICIONADA NA TRILHA DO CACHORRO\nLOUCO.\nDURANTE O *PERÍODO DA MANHÃ*, AS AÇÕES CONCENTRARAM-SE NO CONTROLE E EXTINÇÃO DOS FOCOS ATIVOS AO LONGO DA\nTRILHA DO CACHORRO LOUCO E DA LINHA DE FOGO QUE SEGUIA EM DIREÇÃO AO PARQUE DA CASCATA.\nNO *PERÍODO VESPERTINO*, AS ATIVIDADES CONCENTRARAM-SE NA CONTENÇÃO DO AVANÇO DA FRENTE DE INCÊNDIO ORIUNDA\nDA TRILHA DO CACHORRO LOUCO EM DIREÇÃO À *ESTRADA DE CALÇAMENTO HORÁCIO ÍNDIO DO BRASIL*, BEM COMO NA *PREVENÇÃO DE IMPACTOS DIRETOS* ÀS ÁRVORES CENTENÁRIAS PRESENTES NA UNIDADE DE CONSERVAÇÃO, CONSIDERADAS DE ALTO VALOR ECOLÓGICO E HISTÓRICO.\nFOI EMPREGADO *APOIO AÉREO COM RPA (DRONE)* OPERADO PELO CABO ROMANO, CONTRIBUINDO SIGNIFICATIVAMENTE PARA\nO MONITORAMENTO DAS FRENTES DE FOGO, APOIO À *TOMADA DE DECISÃO TÁTICA* E ORIENTAÇÃO EM TEMPO REAL DAS\nEQUIPES EM CAMPO.\nSOB O COMANDO GERAL DO SR. *MAJOR LUIZ PAULO*, AS FRENTES ATIVAS FORAM CONTROLADAS ATÉ APROXIMADAMENTE\n17H00, QUANDO SE INICIOU *UM NOVO FOCO DE INCÊNDIO* NA REGIÃO DOS BAIRROS *ALVORADA E JK*. IMEDIATAMENTE, FORAM DESTACADOS *07 BRIGADISTAS* PARA ATUAÇÃO DIRETA NESSE NOVO SETOR, REFORÇANDO AS AÇÕES DE RESPOSTA.\nDURANTE TODO O DIA, HOUVE *DINÂMICA DE REMANEJAMENTO DE EFETIVO E VIATURA* ENTRE OS SETORES DE COMBATE,\nCONFORME DEFINIÇÃO DO POSTO DE COMANDO, A FIM DE GARANTIR A *OTIMIZAÇÃO DOS RECURSOS* E A *PRIORIZAÇÃO DE\nÁREAS COM MAIOR VALOR AMBIENTAL E RISCO DE PROPAGAÇÃO*.\nAS AÇÕES CONTARAM COM *INTEGRAÇÃO INTERINSTITUCIONAL*, ENVOLVENDO BOMBEIROS MILITARES, BRIGADISTAS DA\nSERRA, MILITARES DO EXÉRCITO BRASILEIRO (4º GAAE).\nENCERRAMENTO E CONTINUIDADE:\nAS EQUIPES DE BRIGADISTAS PERMANECERAM EM PERNOITE NA BASE DA SERRA DE SANTA HELENA, REALIZANDO **MONITORAMENTO ATIVO DE POSSÍVEIS REIGNIÇÕES**, COM RETORNO DOS MILITARES AO PONTO ZERO AO TÉRMINO DAS AÇÕES\nDO DIA. A OPERAÇÃO PERMANECE EM ANDAMENTO, SENDO NECESSÁRIA A MANUTENÇÃO DE ESFORÇOS PARA A COMPLETA\nSUPRESSÃO DOS FOCOS REMANESCENTES E POSTERIOR ENTRADA NA FASE DE RECUPERAÇÃO AMBIENTAL, CONFORME\nDIRETRIZES DA GESTÃO DE RISCOS E DESASTRES.', '2025-11-13 17:28:03', '2025-11-13 17:28:03', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27731, 6720, 3, 75, 'COORDENADAS GEOGRÁFICAS:\n19°27\'19.9" S / 44°16\'33.9" W\n19°27\'38.9" S / 44°17\'8.2" W\n19°28\'2.7" S / 44°17\'10.5" W\n19°27\'46.2" S / 44°17\'8.7" W\n19°27\'41.4" S / 44°17\'14.5" W\n19°27\'23.1" S / 44°16\'45.4" W\n19°25\'19" S / 44°15\'37" W', '2025-11-13 17:28:03', '2025-11-13 17:28:03', NULL);
