INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27733, 6720, 10, 76, 'NO TERCEIRO DIA DE OPERAÇÕES, OS MILITARES DO CBMMG E DO EXÉRCITO BRASILEIRO (EB) APRESENTARAM-SE NA 1ª CIA\nOPERACIONAL ÀS 05H PARA DESLOCAMENTO ATÉ A SERRA SANTA HELENA, VISANDO À CONTINUIDADE DOS TRABALHOS DE COMBATE\nAO INCÊNDIO QUE ATINGIA AQUELA UNIDADE DE CONSERVAÇÃO, CLASSIFICADA COMO ÁREA DE PRESERVAÇÃO AMBIENTAL (APA) E\nDE RESPONSABILIDADE MUNICIPAL.\nAO CHEGAREM AO LOCAL DESIGNADO COMO ESTACIONAMENTO, SITUADO PRÓXIMO AO POSTO DE COMANDO (COORDENADAS: 19°27\n19.9" S, 44°1633.9" W), OS BOMBEIROS MILITARES INICIARAM DE IMEDIATO A MONTAGEM DE UMA LINHA DIRETA PARA\nCOMBATE A UMA FRENTE DE FOGO QUE AVANÇAVA NAS PROXIMIDADES DA REGIÃO DAS TORRES DE ANTENA.\nPOR VOLTA DAS 06H, FOI REALIZADO SOBREVOO DE RECONHECIMENTO COM A AERONAVE ARCANJO 02, COMANDADA PELO\nTENENTE-CORONEL NELSON, MOBILIZADA EM APOIO À OPERAÇÃO.\nNO PRIMEIRO RECONHECIMENTO CONSTATOU-SE QUE A FRENTE DO INCÊNDIO PRÓXIMA À MATA DA CASCATA ENCONTRAVA-SE\nPARCIALMENTE CONTROLADA, SENDO NECESSÁRIAS AÇÕES PONTUAIS DE COMBATE, RESCALDO E MONITORAMENTO. JÁ A FRENTE\nSITUADA EM DIREÇÃO À REGIÃO DAS TORRES E DA ESTRADA PRINCIPAL DE ACESSO À SERRA APRESENTAVA UMA EXTENSA LINHA\nDE FOGO EM TERRENO ÍNGREME E DE DIFÍCIL ACESSO.\nDESSA FORMA, CONFORME PLANEJAMENTO DEFINIDO PELO POSTO DE COMANDO, SOB COORDENAÇÃO DO MAJOR BM LUIZ PAULO,\nCOMANDANTE DA 5ª CIA IND, FORAM DISTRIBUÍDAS 4 GCIFS EM CAMPO, CADA UMA COMPOSTA POR 2 BOMBEIROS MILITARES E 5\nMILITARES DO EB.\n- 2 GCIFS FORAM DIRECIONADAS AO FOCO DA REGIÃO DA CASCATA (COORDENADAS: 19°2719.89" S, 44°1653.05" W);\n- 2 GCIFS FORAM DIRECIONADAS AO FOCO PRÓXIMO ÀS TORRES (COORDENADAS: 19°2727.4" S, 44°1632.2" W).\nEM APOIO AO COMBATE NA REGIÃO DAS TORRES, A AERONAVE ARCANJO 02 REALIZOU APROXIMADAMENTE 30 LANÇAMENTOS DE\nÁGUA, PERMANECENDO EM OPERAÇÃO ATÉ CERCA DAS 15H40.\nDURANTE OS TRABALHOS HOUVE NECESSIDADE DE REMANEJAMENTO DE EFETIVO PARA A FRENTE DA CASCATA, EM RAZÃO DA\nREIGNIÇÃO DE FOCOS DEVIDO ÀS CONDIÇÕES DO TEMPO. A ATUAÇÃO CONJUNTA DE BOMBEIROS MILITARES, MILITARES DO EB E\nBRIGADISTAS DA SERRA RESULTOU NO ÊXITO DO COMBATE ÀS CHAMAS NESSA ÁREA.\nNO PERÍODO NOTURNO, UMA EQUIPE DO CBMMG, COMPOSTA POR 5 MILITARES, PERMANECEU EM COMBATE PRÓXIMO À TRILHA DE\nBICICLETA CONHECIDA COMO "ESQUERDINHA", QUE LIGA A REGIÃO DAS TORRES À AVENIDA PREFEITO ALBERTO MOURA. A\nEQUIPE ATUOU ATÉ POR VOLTA DAS 00H15 DO DIA 03/10/2025, EVITANDO A PROGRESSÃO DO INCÊNDIO PARA OUTRAS ÁREAS DE\nRELEVÂNCIA AMBIENTAL DA UC. AO FINAL, ORIENTARAM OS BRIGADISTAS QUE PERMANECERAM PERNOITE NA BASE DA SERRA A\nMANTEREM O MONITORAMENTO, RETORNANDO EM SEGUIDA AO PONTO ZERO.\nEFETIVO EMPENHADO:\n-15 BOMBEIROS MILITARES (CBMMG);\n- 07 BRIGADISTAS DA BRIGADA BH;\n- 28 MILITARES DO EXÉRCITO BRASILEIRO.\nVIATURAS/VEÍCULOS:\n- ACIF 5790 (CBMMG);\n- UR 3486 (CBMMG);\n- ASL 1080 (CBMMG);\n- APF 4852 (CBMMG);\n- APF 6238 (CBMMG);\n- 01 CAMINHÃO-PIPA (BRIGADA BH);\n- 02 CAMINHONETES 4X4 (BRIGADA BH);\n- 01 CAMINHÃO-PIPA (EXÉRCITO BRASILEIRO);\n- 02 CAMINHÕES DE TRANSPORTE DE TROPA (EXÉRCITO BRASILEIRO).\nAERONAVE:\n- ARCANJO 02 (CBMMG).\nOBSERVAÇÃO: DURANTE A OPERAÇÃO TAMBÉM FORAM REALIZADOS VOOS DE RECONHECIMENTO COM RPA, CONFORME RELATADO EM\nREDS ESPECÍFICO.', '2025-11-13 17:31:01', '2025-11-13 17:31:01', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
