INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27741, 1040, 3, 78, 'A Defesa Civil foi acionada devido a um foco de incêndio aparentemente criminoso ocorrendo as margens do Córrego do André, este que corta a área central da cidade, foi feito o reconhecimento da cena, e constatado o risco de propagações aos imóveis vizinhos. Logo após foram passadas orientações aos proprietários dos lotes que retirassem maquinários que estavam próximo ao fogo. Com a ajuda de voluntários as chamas foram contidas, e não ouve necessidade de solicitar a presença do Corpo de Bombeiros. Danos causados foram apenas ambientais.', '2025-11-13 17:37:21', '2025-11-13 17:37:21', NULL);
