INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27743, 6720, 10, 79, 'NO SEGUNDO DIA DE OPERAÇÕES, OS MILITARES DO CBMMG APRESENTARAM-SE NA 5ª CIA OPERACIONAL ÀS 05H PARA\nDESLOCAMENTO ATÉ A SERRA SANTA HELENA, VISANDO À CONTINUIDADE DOS TRABALHOS DE COMBATE AO INCÊNDIO QUE ATINGIA\nAQUELA UNIDADE DE CONSERVAÇÃO, CLASSIFICADA COMO ÁREA DE PRESERVAÇÃO AMBIENTAL (APA) E DE RESPONSABILIDADE\nMUNICIPAL.\nAO CHEGAREM AO LOCAL DESIGNADO COMO ESTACIONAMENTO DO PARQUE, SITUADO PRÓXIMO AO POSTO DE COMANDO, OS BOMBEIROS MILITARES REALIZARAM BRIEFING E DIVIDIRAM AS GUARNIÇÕES EM DUAS FRENTES DE COMBATE: A PRIMEIRA COM MONTAGEM DE UMA LINHA DIRETA PARA COMBATE A UMA FRENTE DE FOGO QUE AVANÇAVA NAS PROXIMIDADES DA TRILHA DENOMINADA COMO CACHORRO LOUCO, COMANDADA PELO TEN TAVARES E A OUTRA GUBM, COMANDADA PELO TEN MATEUS NEVES, FICOU RESPONSÁVEL PELO COMBATE DA LINHA QUE AVANÇAVA DA BR 040 EM DIREÇÃO AO PARQUE DA CASCATA.\nEM DADO MOMENTO, A LINHA DE INCÊNDIO QUE VINHA DA BR 040, PULOU O ACEIRO E SE DIVIDIU EM DUAS FRENTES: A\nPRIMEIRA NA PARTE DA SERRA DE SANTA HELENA QUE É VOLTADA PARA A CIDADE, A QUAL O\nCOMBATE DIRETO ERA INEFICAZ NESSE MOMENTO DADO QUE O TERRENO ERA BEM ÍNGREME, RESTANDO O MONITORAMENTO. JÁ A\nSEGUNDA LINHA, QUE PULOU O ACEIRO, AVANÇOU NA DIREÇÃO NOROESTE, E FOI COMBATIDA PELA GUARNIÇÃO QUE ESTAVA NA\nTRILHA DO CACHORRO LOUCO.\nDITO ISSO, NO PERÍODO DA MANHÃ OS ESFORÇOS FORAM EM COMBATER OS FOCOS EXISTENTES NA TRILHA DO CACHORRO LOUCO\nE DA LINHA QUE VINHA DA BR 040 EM DIREÇÃO AO PARQUE DA CASCATA.\nPOSTERIORMENTE, NO PERÍODO DA TARDE, O OBJETIVO ERA COMBATER A LINHA QUE AVANÇOU DA TRILHA DO CACHORRO LOUCO\nEM DIREÇÃO A ESTRADA DE CALÇAMENTO HORÁCIO ÍNDIO DO BRASIL E TENTAR CONTER A\nLINHA QUE AVANÇAVA EM DIREÇÃO ÀS ÁRVORES CENTENÁRIAS DO PARQUE, CONFORME AFIRMADO PELOS BRIGADISTAS.\nPOR VOLTA DAS 13H, O SENHOR MAJOR LUIZ PAULO, COMANDANTE DA 5ª CIA IND, CHEGOU AO POSTO DE COMANDO E ASSUMIU\nO COMANDO DA OPERAÇÃO, REALIZANDO A PASSAGEM DO COMANDO JUNTO AO CAPITÃO JEFFERSON, QUE ERA O COMANDANTE ATÉ O\nMOMENTO. APÓS O ALMOÇO, O SGT CAMILO E O SGT CARVALHO DESLOCARAM PARA A CIA OP PARA REFORÇAR O EFETIVO DA ALA,\nVISTO QUE DOIS MILITARES DA ALA ESTAVAM NA OPERAÇÃO (TEN MARTINELLI E SGT RIBEIRO). ADEMAIS, AS 13H O CB\nROMANO TAMBÉM APRESENTOU PARA PARTICIPAR DA OPERAÇÃO COMO PILOTO DE DRONE. APÓS O ALMOÇO O TEN TAVARES DEIXOU\nA OPERAÇÃO POIS ESTAVA COM FORTES DORES DE CABEÇA E FOI PARA ATENDIMENTO NO HOSPITAL.\nDURANTE O PERÍODO NOTURNO, UM DOS BRIGADISTAS TROUXE A INFORMAÇÃO QUE HAVIA UMA LINHA QUE ESTAVA AVANÇADO\nMAIS AO NORTE DO PARQUE E QUE PODERIA CAUSAR GRANDES DANOS AO PARQUE SE NÃO COMBATIDA, DESSA FORMA A GU BM\nREALIZOU O DESLOCAMENTO NA TRILHA AO NORTE DO PARQUE DA CASCATA PARA AVALIAÇÃO. NO LOCAL, FOI VISUALIZADA UMA LINHA DE FOGO COM GRANDE EXTENSÃO, QUE NÃO PODE SER COMBATIDA, POIS ESTAVA\nNUMA REGIÃO REMOTA EM QUE O ACESSO ERA DIFICULTADO PELOS RISCOS DO PERÍODO NOTURNO E TERRENO ÍNGREME. NESSE\nSENTIDO A GUBM AVALIOU E RESOLVEU RETORNAR PARA COMBATER NO DIA SEGUINTE.\nAO RETORNAR DA TRILHA AO NORTE DO PARQUE, ALGUNS MILITARES FORAM LIBERADO PARA RETORNAR AO COMBATE NO DIA\nSEGUINTE, E OUTROS PERMANECERAM ATÉ CERCA DE 00:30 REALIZANDO O COMBATE E PROTEÇÃO DA LINHA QUE AVANÇAVA EM\nDIREÇÃO A ESTRADA HORÁCIO ÍNDIO DO BRASIL, TENDO ÊXITO AO CONSEGUIR CONTER AS CHAMAS ANTES QUE ESTAS CHEGASSEM\nA TAL ESTRADA. DURANTE OS TRABALHOS HOUVE A NECESSIDADE DE REMANEJAMENTO DE EFETIVO EM DIVERSOS MOMENTOS PARA AS FRENTES DADAS COMO PRIORIDADE PARA OS POSTOS DE COMANDO, EM RAZÃO DA PRIORIDADE DE PROTEÇÃO DE DETERMINADAS AREAS DE PROTEÇÃO DO PARQUE. HOUVE O DIA TODO AÇÃO CONJUNTA DE BOMBEIROS MILITARES E BRIGADISTAS DA SERRA. OS BRIGADISTAS FORAM ORIENTADOS PARA PERMANECEREM PERNOITE NA BASE DA SERRA. DURANTE A OPERAÇÃO FORAM REALIZADOS VOOS DE RECONHECIMENTO DA AREA RPA. \nALGUNS MILITARES TIVERAM PARTE DO FARDAMENTO DANIFICADO.', '2025-11-13 17:40:39', '2025-11-13 17:40:39', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27744, 6720, 1, 79, 'APÓS O ALMOÇO O TEN TAVARES DEIXOU A OPERAÇÃO POIS ESTAVA COM FORTES DORES DE CABEÇA E FOI PARA ATENDIMENTO NO HOSPITAL.\nALGUNS MILITARES TIVERAM PARTE DO FARDAMENTO DANIFICADO.', '2025-11-13 17:40:39', '2025-11-13 17:40:39', NULL);
