INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27747, 3380, 9, 80, 'Na noite do dia 02/11/2025, por volta das 20:30hrs, uma forte chuva atingiu a cidade, onde a Av Jove Soares se tornou um verdadeiro rio, invadindo alguns  comércios. Moradores e comerciantes relataram a esta Coordenadoria que a situação se repete a anos, causando prejuízos e transtornos sempre que chove.', '2025-11-13 18:05:30', '2025-11-13 18:05:30', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27748, 3380, 10, 80, 'Chuvas intensas em curto período: as fortes chuvas que atingiram a cidade na noite deste domingo (02), foram suficientes para transformar ruas em rios. \n\nInfiltração/ escoamento rápido da água: O volume e a velocidade da água foram suficientes para invadir residências e danificar pavimentação\n\nInfraestrutura de drenagem limitada ou vulnerável: O fato de ruas ¿virarem rios¿ indica que o sistema de captação e escoamento pluvial se mostrou incapaz de lidar com o evento, seja pela magnitude ou pela condição existente da rede.\n\nPossível saturação do solo ou acumulação prévia de água: em eventos de chuva intensa rápida costuma haver solo já saturado ou rede de drenagem com baixa capacidade.\n\nTopografia e urbanização vulnerável: A área citada (ex: Avenida Jove Soares) provavelmente é zonas de risco mais alto de alagamento ¿ seja por baixa elevação, confluência de águas ou insuficiente cobertura de drenagem', '2025-11-13 18:05:30', '2025-11-13 18:05:30', NULL);
