INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27764, 7070, 9, 87, 'Zona Urbana: Os locais mais afetados pelas enxurradas e inundações foram bairros próximos ao Ribeirão Santana, Av Batistinha, bairro Santa Maria, bairro Santana, bairro Três Bicas, bairro barcelona, bairro belo horizonte, bairro Vila Pinto, bairro Porto Real, bairro bom Pastor, bairro Vila Paiva, bairro Parque Rinald, bairro Jardim Andere, bairro Jardim Europa, bairro Nossa Senhora Aparecida, bairro Alto da Figueira, bairro Sagrado Coração, bairro Campos Elísios, bairro Vila Murad, bairro São Geraldo, bairro Corcetti,  Destacando as Ruas Plínio,  outros bairros também foram afetados pelas enxurradas, alagamentos e inundação os quais ainda estão sendo feitos levantamentos dos danos e prejuízos, em virtude da magnitude do evento de chuvas intensas. Houve vários danos estruturais em diversas residências, dentre alguns comércios, quedas de muros, postes e erosão de ruas, danos em pavimentações, fornecimento de água interrompido no bairro Vila Pinto, galerias pluviais danificadas, bem como veículos submersos e arrastados para o curso da água.\n.\nZona Rural: Chuvas Intensas, com queda de árvores com obstrução de vias, alagamento de vias, erosão do solo, rompimento de manilhas, tubulão danificado, interdição de estradas, deslizamento de terra.', '2025-11-19 12:19:38', '2025-11-19 12:19:38', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27765, 7070, 10, 87, 'Causas e recorrência:\nChuvas intensas com volume de 98,4 mm na noite do dia 15/11/2025 e 18,8 mm no dia 16/11/2025 conforme registrado no pluviômetro da ANA nº 02145046 em menos de 24 horas, com um acumulado pluviométrico de 117,2 mm, sendo que o município recebeu dois alertas de tempestade com raios e rajada de vento da Defesa Civil Estadual sendo às 19:00 e 21:15 do dia 15/11/2025.\nZona Urbana: Os locais mais afetados pelas enxurradas e inundações foram bairros próximos ao Ribeirão Santana, Av Batistinha, bairro Santa Maria, bairro Santana, bairro Três Bicas, bairro barcelona, bairro belo horizonte, bairro Vila Pinto, bairro Porto Real, bairro bom Pastor, bairro Vila Paiva, bairro Parque Rinald, bairro Jardim Andere, bairro Jardim Europa, bairro Nossa Senhora Aparecida, bairro Alto da Figueira, bairro Sagrado Coração, bairro Campos Elísios, bairro Vila Murad, bairro São Geraldo, bairro Corcetti,  Destacando as Ruas Plínio,  outros bairros também foram afetados pelas enxurradas, alagamentos e inundação os quais ainda estão sendo feitos levantamentos dos danos e prejuízos, em virtude da magnitude do evento de chuvas intensas. Houve vários danos estruturais em diversas residências, dentre alguns comércios, quedas de muros, postes e erosão de ruas, danos em pavimentações, fornecimento de água interrompido no bairro Vila Pinto, galerias pluviais danificadas, bem como veículos submersos e arrastados para o curso da água.\n.\nZona Rural: Chuvas Intensas, com queda de árvores com obstrução de vias, alagamento de vias, erosão do solo, rompimento de manilhas, tubulão danificado, interdição de estradas, deslizamento de terra.\n', '2025-11-19 12:19:38', '2025-11-19 12:19:38', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27766, 7070, 1, 87, 'Em decorrência das chuva intensas com inundações, enxurradas e alagamentos causando danos privados, atingindo aproximadamente 3000 pessoas que tiveram a rotina alterada em decorrência do desastre, afetando diretamente 15 imóveis com quedas de muro, danos estruturais, inundação com lama e detritos, veículos submersos, perda de móveis e utensílios domésticos, deixando 53 pessoas desalojadas, que foram casa de amigos e parentes, muitos dos quais retornaram no dia seguinte para limpeza do local.\n\n      Três famílias (sendo o total de 12 pessoas) ficaram desabrigadas, em decorrência de danos significativos no imóvel, precisando de apoio público, sendo encaminhados para hotel do município.\nZona Urbana ¿ Residências atingidas até o momento:\nGrupo A: dano material, dano ao imóvel e interdição parcial ou total do imóvel:\n\nRua José Barcelona de Oliveira, 165\nRua Plínio Salgado, 780\nRua Bráz Nogueira, 114\nRua Pedro Secci, 840\nRua da Fonte, 156\nRua da Fonte, 128\nRua Plínio Salgado, 810\nAv. Dr. Amis Reis, 91\nRua José Barcelona de Olieveira, 165\nTravessa José G. Oliveira, 03\nRua José Cláudio Ferreira, 80\n\n\nGrupo B: dano material, dano ao imóvel, sem interdição:\nAv. Sebastiana Jacob dos Santos, SN\nRua Juarez Mendes Lima, 85.\nAlameda do Café, 322\nRua Alvarina Frota, 70\nRua Dr. Jacy de Figueiredo, 628\nRua José Cláudio Ferreira, 90\nQuadra Semel Bom Pastor, SN.\nRua João dos Reis, 363.\n\nZona Rural: Chuvas Intensas, com queda de árvores com obstrução de vias, alagamento de vias, erosão do solo, rompimento de manilhas, tubulão danificado, interdição de estradas, deslizamento de terra, afetando por vota de 300 pessoas.', '2025-11-19 12:19:38', '2025-11-19 12:19:38', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27767, 7070, 2, 87, 'Zona Urbana:\nGrupo A: dano material, dano ao imóvel e interdição parcial ou total do imóvel:\n\nRua José Barcelona de Oliveira, 165\nRua Plínio Salgado, 780\nRua Bráz Nogueira, 114\nRua Pedro Secci, 840\nRua da Fonte, 156\nRua da Fonte, 128\nRua Plínio Salgado, 810\nAv. Dr. Amis Reis, 91\nRua José Barcelona de Olieveira, 165\nTravessa José G. Oliveira, 03\nRua José Cláudio Ferreira, 80\n\n\nGrupo B: dano material, dano ao imóvel, sem interdição:\n\nAv. Sebastiana Jacob dos Santos, SN\nRua Juarez Mendes Lima, 85.\nAlameda do Café, 322\nRua Alvarina Frota, 70\nRua Dr. Jacy de Figueiredo, 628\nRua José Cláudio Ferreira, 90\nQuadra Semel Bom Pastor, SN.\nRua João dos Reis, 363.\n\nZona Rural: Chuvas Intensas, com queda de árvores com obstrução de vias, alagamento de vias, erosão do solo, rompimento de manilhas, tubulão danificado, interdição de estradas, deslizamento de terra.', '2025-11-19 12:19:38', '2025-11-19 12:19:38', NULL);
