	(27873, 7040, 9, 112, 'Toda área urbana foi afetada pelo evento.', '2025-12-03 12:31:25', '2025-12-03 12:31:25', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27874, 7040, 10, 112, 'No dia 17 de novembro de 2025, por volta das 15h, Unaí foi atingida por uma forte chuva de 50,6 mm, um período de chuva de granizo acompanhada por um vendaval intenso. Os ventos causaram destelhamentos, queda de árvores e galhos em diversos pontos da cidade, como na Praça da Prefeitura, Escola Estadual Izabel Campos Martins, onde uma árvore derrubou parte do muro. Houve também queda de postes e fios, deixando grande parte da cidade sem energia por várias horas. Algumas vias ficaram interditadas, e toldos e placas de comércios foram arrancados.', '2025-12-03 12:31:25', '2025-12-03 12:31:25', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
