INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27931, 3890, 9, 128, 'Bairro monte pascoal, área central, bairro da área e loteamento portal do norte foram diretamente afetados com chuva do dia 06/12/2025 trechos da rua lídio Araújo, rua Juscelino kubitschek, praça do pirulito, Comunidade Córrego Seco e Água Branca', '2025-12-10 15:35:08', '2025-12-23 14:28:32', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27932, 3890, 10, 128, 'A forte chuva que atingiu o Município de Machacalis no dia 6 de Dezembro de 2025, com precipitação intensa, extrapolando a capacidade de drenagem urbana, provocando deslizamento, enxurrada e alguns pontos de alagamento de ruas, com queda de muros e paredão de rua o evento com duração de 3:00 horas de chuva , chegando a 50.1 milímetros, segundo medição da Copasa, com rajada de vento e queda de arvores em alguns pontos.', '2025-12-10 15:35:08', '2025-12-10 15:35:08', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27933, 3890, 1, 128, 'Devido a forte chuva que atingiu o município o rio trasbordou alagando pastagem nas zonas rurais e na cidade, uma casa foi interditada com o risco de queda, a assistência social esteve no local para encaminha a o morador ao aluguel social, no momento o morador segue em casa de familiar.', '2025-12-10 15:35:09', '2025-12-10 15:35:09', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27934, 3890, 2, 128, 'Parte do muro da Escola Estadual José de Alencar desabou, ocasionando o comprometimento parcial da estrutura. O muro de arrimo\nsituado na Rua Lídio Araújo, nº 35, cedeu. Ademais, 01 residência localizada na Rua Olavo Bilac, no bairro Monte Pascoal, foi interditada em\nrazão das inúmeras rachaduras identificadas em sua estrutura, apresentando risco iminente de colapso. Ressalta-se, ainda, que um muro\nrecentemente construído no bairro Portal do Norte também desabou. Por fim, a estrutura do muro de 01 residência, situada no bairro da\nÁrea, apresenta rachaduras, indicando necessidade de avaliação técnica.\n', '2025-12-10 15:35:09', '2025-12-23 14:28:32', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27935, 3890, 11, 128, 'foi mobilizado a secretaria de obras para fazer a limpeza do entulho sobre a rua, onde caiu o muro da escola e a limpeza com retroescavadeira e caçamba para retirar lama e lixo por onde a enxurrada passou, foi feita uma contenção provisória no muro do imóvel no bairro portal do norte.', '2025-12-10 15:35:09', '2025-12-10 15:35:09', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27936, 3600, 9, 121, 'a Zona urbana : area central ( travesa curumin bairro vila newtão. rua duque caxias) e na zona rural o distrito do Giru atingindo as\ncomunidades : 1. Convém, 2. Boa Vista, 3. Mumbuca, 4. Santa Rosa, 5. Córrego de Areia, 6. Jardineira, 7. Córrego de Santana, 8. Marianos,\n9. Água Limpa, 10. Guanabara, 11. Amaralina, 12. Caracol, 13. Quarteirão, 14. Diamantina, 15. Barreirinho. 16 Providencia, 17. Barro Branco, 18. Bonfim, 19. Queixada, 20. Brejaúbas, 21. Santa Helena, 23. Alagoas, 24. Viração, 25. Rocinha, 26. Santa Luzia, 27. Córrego do Rela, 28. São Miguel, 29. Córrego dos Pires. 30- Centro - Rua Leonino Ferreira', '2025-12-10 15:40:37', '2025-12-30 18:10:52', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27937, 3600, 10, 121, 'As chuvas intensas no período de 04 de dezembro á 08 de dezembro causaram desabamento de arvores na sede do município e nas estradas vicinais, casas colapsaram, inundações áreas baixas do distrito do GIRU, estradas interrompidas com arvores caídas e barreiras que impediram acesso , muros caído da ubs do bairro ipe, e sobre igreja evangélica, arvores caídas nas praças da cidade, causando dano material e prejuízos econômicos ao município , necessitando de ações de resposta e restabelecimento para voltar no possível a normalidade.', '2025-12-10 15:40:37', '2025-12-30 18:10:52', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27938, 6110, 8, 129, NULL, '2025-12-10 15:45:53', '2025-12-10 15:45:53', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27939, 6110, 9, 129, 'Zona Urbana Foram afetados os seguintes bairros e vias: Luzia, Centro, Funcionários, Sagrada Família, El Dorado, São Lucas, Santo Antônio\ne São José; Bairro Jardim Regalito, Rua Silva Jardim e Rua Padre Elifaz; Rua Altair Cordeiro, Rua Cornélio Pinto e Rua Padre Melquíades; no\nBairro Sagrada Família, a Avenida Arnaldo Lima; no Bairro Funcionários, a Rua F; Avenida Oscar Caetano Gomes; Rua Amadeu Gomes da\nMata; bem como áreas do Bairro Santo Antônio. Zona Rural Foram atingidas as comunidades de Ilha dos Porteiros, Assentamento São\nFrancisco, Mocambo, Travessão de Minas, Boa Vista e São Domingos. Ressalta-se que todas as áreas do município foram afetadas,\nabrangendo tanto a zona urbana quanto as comunidades da zona rural, em decorrência das chuvas intensas. O município registrou\nalagamentos generalizados, com inundação das áreas ribeirinhas em razão do transbordamento do Rio São Francisco.\n', '2025-12-10 15:45:53', '2025-12-23 14:32:21', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27940, 6110, 10, 129, 'Muitas regiões do nosso município foram afetadas principalmente da zona urbana, com estradas, ruas e bueiros sendo danificados e\nmoradores tendo perdas, principalmente em suas plantações na zona rural devido as chuvas irregulares, sendo que muitos moradores\ntiveram perdas de móveis e danos em suas residências na área urbana devido alagamentos, sendo que cerca de 5 pessoas foram\ndesalojadas, indo para casa de parentes e 5 desabrigadas indo para casa providenciada pela prefeitura através do aluguel social e no total\ncerca de 6.000 pessoas foram afetadas pelo desastre das chuvas intensas e alagamentos em nosso município.', '2025-12-10 15:45:53', '2025-12-23 14:32:21', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27941, 6110, 1, 129, 'O desastre afetou 6.010 pessoas, muitas regiões do nosso município foram afetadas principalmente da zona urbana, com estradas,ruas e\nbueiros sendo danificadas e moradores tendo perdas, principalmente em suas plantações devido as chuvas irregulares, muitos moradores\ntiveram perdas de móveis e danos em suas residências na área urbana devido alagamentos, sendo que cerca de 5 pessoas foram\ndesabrigadas indo para casa providenciada pela prefeitura através do aluguel social, e 5 desalojadas indo para casa de parentes e no total\ncerca de 6.000 pessoas foram afetadas pelo desastre das chuvas intensas e alagamentos em nosso município. As residências afetadas foram\nalagadas, ocasionando perda de móveis, gêneros alimentícios e eletrodomésticos, além de diversas intercorrências, tais como danos em\nmuros e avarias em telhados em decorrência das chuvas.\n', '2025-12-10 15:45:53', '2025-12-23 14:32:21', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27942, 6110, 2, 129, 'Foram registradas 15 unidades habitacionais danificadas, necessitando de reparos para restabelecer condições adequadas de segurança e\ndignidade aos moradores. As residências foram alagadas, ocasionando perda de móveis, gêneros alimentícios e eletrodomésticos, além de\ndiversas intercorrências, tais como danos em muros e avarias em telhados em decorrência das chuvas. DANIFICADO DANIFICADO Na zona\nrural: 01 Estrada da comunidade Ilha das Porteiras, 01 estrada da comunidade Assentamento São francisco e 01 estrada Tapera foram\ndanificadas devido as enxurradas e alagamento no local, 01 estrada que dá acesso a comunidade do Mocambo também foi danificada pelas\nenxurradas com buracos prejudicando a trafegabilidade na região, 01 estrada na comunidade Travessão de Minas foi alagada pelo córrego\ndevido as chuvas prejudicando a trafegabilidade no local, Na comunidade Boa Vista 01 estrada ficou danificada prejudicada pelas chuvas,\ncom buracos na via e lama e Comunidade São Domingos 01 via também ficou alagada e prejudicada pelo desastre. Na zona urbana: As ruas\nmais afetadas foram a Silva Jardim localizada próximo ao centro da cidade no bairro Jardim Regalito que além do lixo entupindo galerias\nteve parte do asfalto arrancado e 01 via danificada, a rua Padre Elifaz que teve 01 galeria pluvial danificada, Ruas Altair Cordeiro, Cornélio\nPinto, Padre Melquíades e Avenida Arnaldo Lima no bairro Sagrada Família e Rua F no bairro Funcionários também foram muito danificadas\npelas enxurradas causando buracos na via e alagamentos que atrapalharam a trafegabilidade na região e prejudicaram moradores locais,\nAvenida Oscar Caetano Gomes que foi danificada e alagada prejudicando a trafegabilidade na região, rua Amadeu Gomes da Mata também\nfoi muito afetada no bairro Santo Antônio. Ruas foram danificadas tendo seu calçamento arrancado, bueiros obstruídos por lixo, causando\nalagamentos em diversos pontos, principalmente na área central da cidade e na zona rural muitas estradas foram afetadas e obras de\ninfraestruturas públicas também. A Até o momento envio do processo, os levantamentos, e as vistorias ainda estão sendo feitos, devido a\ngrande quantidade de danos nas estradas do município tanto na zona urbana como rural.', '2025-12-10 15:45:53', '2025-12-23 14:32:21', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27943, 6110, 11, 129, 'Gastos com:\n\nLocação maquinário para limpeza das rua, vias, desobstrução das estradas, - \nAbastecimento do maquinário em Combustível para as limpeza e obras de restabelecimento das vias do município -\nMão de Obra e Funcionários Contratados para o serviço de limpeza urbana: \nTotalizando: Aproximadamente R$ 600.000,00 de prejuízos em função do desastre.', '2025-12-10 15:45:53', '2025-12-10 15:45:53', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27944, 6110, 12, 129, 'Neste mês as chuvas significativas no município começaram na segunda quinzena, atrasando o início do plantio das lavouras remporárias.\n\nFeijão 3ª Safra - R$ 420.000\nMilho - R$ 480.000\nCana de açúcar - R$ 525.000.000\nTotalizando R$ 525.900.000 de perdas na Agricultura.\n\nNa pecuária houve prejuízo Econômico em função da redução da produção de carne: R$ 10.079.447,04\n\nConforme relatório da Emater', '2025-12-10 15:45:53', '2025-12-10 15:45:53', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27945, 1520, 8, 130, NULL, '2025-12-10 15:49:38', '2025-12-10 15:49:38', NULL);
