INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27958, 4710, 9, 135, 'Praça Galba Veloso entre os números 100 ao 220.  - Bairro Nossa Senhora das Graças -  Zona Urbana\nCMEI Professor Geraldo Martins Ferreira e Melo Creche Santa Terezinha', '2025-12-12 11:11:46', '2025-12-12 11:11:46', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27959, 4710, 10, 135, 'Na noite do dia 18 de novembro de 2025, por volta das 21h15min, registrou-se a passagem de rajadas de vento estimadas entre 40 km/h e 55 km/h na região do bairro Nossa Senhora das Graças. Em decorrência do evento meteorológico adverso, verificou-se o arrancamento parcial de uma cobertura composta por telhas metálicas trapezoidais de aço galvanizado, pertencente à estrutura superior de uma edificação de dois pavimentos.\n\nA movimentação do material desprendido ocasionou o rompimento de cabos da rede elétrica situados à frente da referida construção, resultando na interrupção imediata do fornecimento de energia. O impacto comprometeu não apenas a via frontal, mas também o circuito elétrico que atende ao trecho compreendido entre os números 100 e 208 da Praça Gaçaba Veloso.\n\nEntre os imóveis atingidos pela interrupção encontram-se:\n\nedifícios residenciais e casas;\n\numa agência de viagens;\n\numa clínica veterinária;\n\numa clínica médica;\n\no Centro Municipal de Educação Infantil Professor Geraldo Martins Ferreira e Melo;\n\na Creche Municipal Santa Terezinha.\n\nAs equipes de resposta compostas pelo Corpo de Bombeiros Militar, Cemig, Eletrocamp, Guarda Civil Municipal e Defesa Civil foram mobilizadas imediatamente. Os trabalhos envolveram a isolação da área, a avaliação dos riscos estruturais, a retirada controlada do material metálico desprendido e os procedimentos de restabelecimento da rede elétrica.\n\nA operação de remoção e segurança prosseguiu até aproximadamente 11h00min do dia 19/11/2025, quando toda a área foi considerada estabilizada e livre de materiais soltos. O fornecimento de energia elétrica foi restabelecido às 12h00min do mesmo dia.', '2025-12-12 11:11:46', '2025-12-12 11:11:46', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(27960, 4710, 2, 135, 'Casa habitacional em construção - Praça Galba Veloso nº 220 - Local onde houve o destelhamento.', '2025-12-12 11:11:46', '2025-12-12 11:11:46', NULL);
