	(28015, 2490, 8, 146, NULL, '2025-12-16 19:57:11', '2025-12-16 19:57:11', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28016, 2490, 9, 146, 'ÁREA RURAL: DISTRITO DE QUEIROZES: Estrada vicinal do Distrito de Queirozes, no ponto de travessia sobre o Ribeirão Boa Esperança (local onde se encontra a ponte em tubulão totalmente destruída pelas fortes chuvas ocorridas em 15/12/2025, por volta das 16h00, em decorrência da correnteza intensa das águas).', '2025-12-16 19:57:11', '2025-12-16 19:57:11', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28017, 2490, 10, 146, 'No dia 15/12/2025, por volta das 16h00, o Distrito de Queirozes foi atingido por chuvas intensas, provocando aumento rápido da vazão e da velocidade da correnteza do Ribeirão Boa Esperança. A elevada energia do escoamento gerou sobrecarga hidráulica, causando erosão na fundação e destruição total do tubulão de sustentação, com perda completa da capacidade estrutural da ponte. Não houve registro de alagamentos ou inundações, sendo os danos decorrentes exclusivamente da intensidade da correnteza.', '2025-12-16 19:57:11', '2025-12-16 19:57:11', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28018, 2490, 1, 146, 'Estima-se que aproximadamente 500 pessoas foram afetadas indiretamente pela destruição total da ponte, com interrupção do deslocamento na estrada vicinal do Distrito de Queirozes.', '2025-12-16 19:57:11', '2025-12-16 19:57:11', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
