INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28048, 460, 9, 154, 'Zona Rual: Comunidade da Serra dos Continuos, Colônia Santa Maria Urbano: Rua Manoel Basilio Lopes, Av. Alencar Ribeiro Bairro Laville Distrito de Sant\'Ana do Campestre, Distrito de Sobral Pinto. ', '2025-12-18 15:40:37', '2025-12-18 15:40:37', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28049, 460, 10, 154, 'Na madrugada do dia 17 de dezembro de 2025, ocorreu, no município de Astolfo Dutra/MG e nos distritos de Sobral Pinto e Sant¿Ana do Campestre, um evento de chuvas intensas, com índice pluviométrico aproximado de 111 mm em um período de 2 horas.\nEm razão desse elevado volume de precipitação, tanto a montante quanto no próprio município, foram registrados diversos pontos de inundação, ocasionando a cheia do Córrego Ideal na área urbana, de um córrego localizado na zona rural do distrito de Sobral Pinto e do Rio Paraopeba, localizado no distrito de Sant¿Ana do Campestre, resultando em enxurradas e inundações que causaram danos humanos e materiais, conforme caracterização prevista na Portaria MDR nº 260/2022.', '2025-12-18 15:40:37', '2025-12-18 15:40:37', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28050, 460, 1, 154, 'Um ferido encaminhado para Hospital Olinto Almada no Município \n\n04 pessoas sendo acolhidas temporariamente em residências de familiares, por terem a suas residências parcialmente danificadas , 02 residências destruídas\n\nDurante o sinistro registrado na madrugada do dia 17 de dezembro de 2025, ocorreram inundações em decorrência do transbordamento de córregos no Distrito de Sobral Pinto. Na zona rural, a inundação provocada por um córrego resultou no desabrigo \n\nAinda em decorrência da inundação do Córrego Ideal, aproximadamente 123 pessoas ficaram desalojadas, sendo acolhidas temporariamente em residências de familiares e amigos, além de sofrerem prejuízos materiais.\n\n\nDe forma geral, estima-se que 1.378 pessoas tenham sido afetadas direta ou indiretamente no município e em seus distritos, em razão das inundações registradas e motivo de não poderem transitar devido a queda de pontes. Pessoas ficaram sem energia e telefone. Queda de postes.', '2025-12-18 15:40:37', '2025-12-18 15:40:37', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28051, 460, 2, 154, '¿ 56 residências danificadas no município de Astolfo Dutra e Distrito de Sobral Pinto \n¿ 2 residências parcialmente destruídas no Distrito de Sobral Pinto\n¿ Duas pontes de concreto danificadas, com comprometimento das alas de proteção e das cabeceiras, sendo uma localizada no Distrito de Sant¿Ana do Campestre, responsável pela ligação com a zona rural, e outra situada na Comunidade da Serra dos Contínuos.\n¿ Uma ponte de concreto danificada  com danos em sua cabeceira, localizada na entrada principal do Distrito de Sobral Pinto.\n¿ Um sistema de manilhamento danificado na zona rural do Distrito de Sobral Pinto, responsável pela ligação com a Comunidade da Serra dos Contínuos.\n¿ Duas vias públicas com danos no pavimento asfáltico em CBUQ, sendo uma localizada na entrada principal do Distrito de Sobral Pinto e outra no Bairro Laville, na Rua Manoel Basílio Lopes, no Município de Astolfo Dutra.\n\n¿ Uma ponte de madeira danificada na zona rural do Distrito de Sobral Pinto.\n\nDestruídas \n\n¿ Uma ponte de concreto totalmente destruída na zona rural do Distrito de Sobral Pinto, responsável pela ligação com a Comunidade da Serra dos Contínuos.\n\n¿ Duas pontes de madeira totalmente destruídas na Comunidade dos Contínuos.\n\n', '2025-12-18 15:40:37', '2025-12-18 15:40:37', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28052, 460, 11, 154, 'Houve a necessidade de contração emergencial  de Caminhões e maquinas para auxiliar na limpeza das areas afetadas.', '2025-12-18 15:40:37', '2025-12-18 15:40:37', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28053, 3670, 8, 156, NULL, '2025-12-18 18:50:04', '2025-12-18 18:50:04', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28054, 3670, 9, 156, 'Devido ao evento registrado através deste FIDE foram registrados entre o dia 15 de dezembro de 2025 às 18h00min e o dia 18 de\ndezembro de 2025 às 12h00min, um total de 201 boletins de ocorrência pela Defesa Civil de Juiz de Fora. As ocorrências mais impactantes\nforam vinculadas aos seguintes desastres: - Alagamentos - Total de 77 ocorrências; - Escorregamentos de Talude - Total de 49 ocorrências;\n- Inundações - Total de 31 ocorrências; No que tange à distribuição destas ocorrências, essas se encontram em andamento e afetaram todo\no território do Município de Juiz de Fora', '2025-12-18 18:50:04', '2025-12-30 17:49:25', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28055, 3670, 10, 156, 'O desastre indicado neste FIDE pode ter suas causas analisadas, sob duas perspectivas: a primeira, causadora de desastres do tipo hidrológico (inundações bruscas, alagamentos e enxurradas), do tipo geológico (movimentos de massa - escorregamentos de talude; formação de erosões de margem fluvial), assim como formação de grandes erosões) e do tipo tecnológico (colapso de edificações), que tiveram como evento gerador, as precipitações pluviométricas significativas que incidiram no Município de Juiz de Fora no dia 15 de dezembro de 2025 entre 18h00min e 19h30min, ficando os volumes de chuva mais expressivos, concentrados em um período de apenas 1 hora. Também pode ser analisado sob a perspectiva do acúmulo de precipitações em um período de 96 horas, ou seja, entre o dia 13 de dezembro de 2025 e o dia 17 de dezembro de 2025, haja vista que o acúmulo expressivo de precipitações, contribui para o processo de saturação do solo e deflagração de movimentos gravitacionais de massa. \nNeste sentido, considerando os dados do Centro Nacional de Monitoramento e Alerta de Desastres (Cemaden), os dados do Instituto Nacional de Meteorologia (Inmet), bem como dados de estações meteorológicas da Subsecretaria de Proteção e Defesa Civil de Juiz de Fora, tem-se os dados causadores dos desastres apresentados a seguir.\nVOLUME DE CHUVAS QUE INCIDIU SOBRE O MUNICÍPIO DE JUIZ DE FORA NO DIA 15 DE DEZEMBRO DE 2025 - CONCENTRADAS EM 1 HORA\nBairro: Linhares (Região de Planejamento Leste) - 109,74 mm;\nBairro: Santa Rita de Cássia (Região de Planejamento Leste) - 105,01 mm;\nBairro: Bandeirantes (Região de Planejamento Nordeste) - 101,40 mm;\nBairro: Marumbi (Região de Planejamento Leste) - 101,09 mm.\nNos pontos onde foram identificados registros de volume de chuvas mais significativos no período supracitado (concentrado em 1 hora), tem-se um total de 35% da média histórica para o mês de dezembro em Juiz de Fora (que é de 310,4 mm), sendo assim, um valor muito expressivo para o período de 1 hora. Com base na equação IDF do Município, isso representa uma chuva com Tempo de Recorrência (TR) de 143 anos.\nVOLUME DE CHUVAS QUE INCIDIU SOBRE O MUNICÍPIO DE JUIZ DE FORA, ENTRE OS DIAS 13 DE DEZEMBRO DE 2025 E 17 DE DEZEMBRO DE 2025 - PERÍODO DE 96 H\nBairro: Filgueiras (Região de Planejamento Nordeste) - 174,2 mm;\nBairro: Linhares (Região de Planejamento Leste) - 167,0 mm;\nNos pontos onde foram identificados registros de volume de chuvas mais significativos no período supracitado (concentrado em 96 horas), tem-se um total de 56,2% da média histórica para o mês de dezembro em Juiz de Fora (que é de 310,4 mm), sendo assim, um valor muito expressivo para o período de 1 hora.\n	Em ambas as perspectivas, considerando o plano de contingência do período chuvoso (2025-2026) do Município de Juiz de Fora/MG, verifica-se que foi ultrapassado os limiares de chuva relacionados ao nível de alerta máximo para deflagração de movimentos de massa e inundações.\n	Os efeitos deste evento foram:\nDestruição da infraestrutura viária de algumas vias;\nDestruição parcial e total de edificações;\nPerdas materiais oriundas de eventos de inundações, alagamentos e movimentos de massa (escorregamentos de talude);\nTrânsito bloqueado e com velocidade reduzida em áreas atingidas;\nPerdas materiais em edificações;\nPerdas de veículos em áreas atingidas por desastres;\nUnidade Básica de Saúde (UBS) do Bairro Linhares com atendimento paralisado por ter sido atingida por inundação;\n	Em alguns locais, foi identificado que a lâmina d¿água oriunda das inundações atingiu uma altura de aproximadamente 2,0 m. Estima-se que com o desastre em questão, quase 5.000 pessoas foram afetadas. Foi decretada Situação de Emergência devido ao desastre.\n', '2025-12-18 18:50:04', '2025-12-18 18:50:04', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28056, 3670, 1, 156, 'As pessoas que ficaram temporariamente desalojadas são aquelas que tiveram seus imóveis temporariamente ou totalmente interditados pela Defesa Civil. As famílias que se enquadram nos perfis socioeconômicos foram encaminhadas para o Programa Auxílio-Moradia do Município. Em suma as interdições foram realizadas por estarem relacionados a desastres deflagrados gerando danos nos imóveis, ou devido a condição de risco iminente de desastre. Neste sentido, o Serviço Social da Defesa Civil identificou um total de 61 (sessenta e uma) pessoas. \n\nNa área outros afetados, foi considerada toda a população que tiveram seus imóveis atingidos pelas inundações nos Bairros Linhares, Vitorino Braga, Bom Jardim, Vila dos Sonhos, Grama; que foram atingidos por alagamentos nos Bairros Centro, São Mateus, Alto dos Passos; bem como aqueles que tiveram seus imóveis impactados por movimentos de massa ou outros tipos de ocorrência registradas pela Defesa Civil, mas que não geraram interdição.\n', '2025-12-18 18:50:04', '2025-12-18 18:50:04', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28057, 3670, 2, 156, 'Na ocasião do desastre foi verificada a destruição total de 01 (uma) unidade habitacional, bem como a destruição parcial de outras 10 (dez) edificações. Considerando as estimativas de danos com destruição destas unidades habitacionais, bem como as perdas de mobiliários e prejuízos indiretos, estima-se danos na faixa de R$ 929.274,00.\n\nTambém na ocasião do desastre, uma Unidade Básica de Saúde (UBS) situada na Rua Odilon Braga - Bairro: Linhares, foi atingida por cenário de inundação, gerando prejuízos para o Poder Público. Estima-se danos materiais na ordem de R$ 45.250,00.\n\nObras de Infraestrutura Pública - Localizadas destruídas:\n1 - Rua Professor Francisco Faria - Bairro: Bonfim - R$ 3.500.000,00\n2 - Rua Miguel Jacobe - Bairro: Grajaú - R$ 4.000.000,00\n\nObras de Infraestrutura Pública - Localizadas parcialmente destruídas:\n1 - Rua Diva Garcia, próximo ao nº 3082 - Bairro: Linhares - R$ 250.000,00\n2 - Rua Goiás - Bairro: São Bernardo - R$ 100.000,00\n3 - Avenida Doutor Moacyr Siqueira - Bairro: Jardim do Sol - R$ 150.000,00\n4 - Rua Luiz Fávero - Bairro: Linhares - R$ 100.000,00.\n\nCom isso, estima-se um total de danos à infraestrutura pública de R$ 8.100.000,00.\n', '2025-12-18 18:50:04', '2025-12-18 18:50:04', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28058, 3670, 11, 156, 'No que tange ao sistema de limpeza urbana do Município, foi necessário a realização de serviços de raspagem de lama e lavação de via pública, após cenários de inundações nos Bairros Grama, Vila dos Sonhos, Linhares, Vitorino Braga, Bom Jardim, Industrial, bem como de enxurradas em Cachoeira e remoções de solo após deslizamentos. Estima-se cerca de 6.439 metros de via que demandaram serviços de raspagem de lama e lavação de via pública, após cenários de inundação. Devido a efeitos de inundações, boa parte dessas ruas também demandaram recolhimento de grande volume de resíduos, mobiliários, eletrodomésticos e vestuário. Estima-se que tal serviço esteja sendo realizado em aproximadamente 5.600 metros de via.\n\nForam utilizados retroescavadeiras, caminhões pipa, pás carregadeiras, caminhões basculantes e equipes de limpeza urbana neste serviço. Considera-se por fim, o custo com bota-fora para destinação dos resíduos oriundos do recolhimento após inundações. Estima-se assim, que o custo somente com a limpeza das áreas afetadas diretamente pelo desastre é de aproximadamente R$ 1.969.653,60;\n\nHá ainda de se citar os serviços de limpeza de boca de lobo e desobstrução de córregos. Com os efeitos do desastre, se fez necessário a remoção de resíduos sólidos e sedimentos de bocas de lobo, bem como serviços de desobstrução de redes de drenagem com caminhões limpa fossa. Além disso, com grande volume de resíduos carregados pela força dos córregos alvo de inundações, geraram a necessidade de desobstrução de galerias em diversos pontos da cidade. Estima-se que com a ação em questão, tenha sido necessário um volume de recursos de aproximadamente R$ 599.864,26.\nEm relação a limpeza e desinfecção de imóveis, considerando a disponibilização de itens de ajuda humanitária às famílias atingidas, limpeza dessas edificações, bem como incentivos tributários (como cálculo da conta de água pela média mensal), para minimizar as perdas destas famílias e os gastos com lavação dos imóveis pós-desastre, estima-se um prejuízo de aproximadamente R$ 2.472.500,00;\n\nAdemais, por ser uma área afetada por inundação, tem-se ainda o prejuízo vinculado à necessidade de assistência médica, vacinação, cuidados com doenças como a leptospirose, dentre outros. Foi realizada a mobilização de vacimóvel para atender a população local. Estima-se assim, que o custo somente com questões simples relacionados à assistência médica, seja de R$ 143.750,00;\n\nNo que tange às questões relacionadas aos danos à rede pública de esgoto e à rede pública de águas pluviais, estima-se que o prejuízo do poder público - R$ 5.274.851,70, isto aplicado a recuperação emergencial para não gerar danos e prejuízos ainda maiores à população;\n\nA área de transportes foi prejudicada com grandes congestionamentos na cidade, devido a obstruções e vias que ficaram intransitáveis, após os desastres, haja vista outros tipos de perdas, como de veículos que tiveram danos severos após serem atingidos por alagamentos e inundações. Estima-se nessa área, um prejuízo de aproximadamente R$ 98.140,34.\n\nPontua-se ainda outros prejuízos públicos, haja vista que visando minimizar o impacto para a população atingida pelas inundações foi concedida isenção tributária de IPTU para o ano de 2026. Com isso, estima-se inicialmente uma perda de receita para o Município de Juiz de Fora com o desastre, de aproximadamente R$ 907.500,00;\n\nAssim, inicialmente estima-se um prejuízo econômico público de aproximadamente R$ 11.466.259,90, com o desastre indicado neste FIDE.', '2025-12-18 18:50:04', '2025-12-18 18:50:04', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28059, 3670, 12, 156, 'Devido aos desastres que incidiram sobre as áreas listadas neste FIDE foi identificado um impacto significativo, para a área de comércio e serviços. Estima-se que cerca de 200 estabelecimentos comerciais e de serviços foram diretamente impactados, com perdas de mercadorias, equipamentos, eletrodomésticos, mobiliários, dentre outros itens. Considerando que em cenários de inundações, as áreas não são atingidas em mesmo nível de intensidade, ou seja, ao longo da mancha atingida, alguns imóveis com maiores danos e outros com menores, estima-se que os prejuízos para os empresários locais sejam de cerca de R$ 12.789.811,00.', '2025-12-18 18:50:04', '2025-12-18 18:50:04', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28060, 2352, 8, 157, NULL, '2025-12-18 18:55:31', '2025-12-18 18:55:31', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28061, 2352, 9, 157, 'Os Povoados de Dores e Andradas, Comunidade de Terra Seca e Soledade, Vila de São Francisco de Assis, e Córregos Santo Agostinho, Pouso Alegre, São João, Córrego Beira Rio e São Pedro, afetando aproximadamente 2.000 pessoas', '2025-12-18 18:55:31', '2025-12-18 18:55:31', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28062, 2352, 10, 157, 'entre as 14 horas do dia 14/12/2025 e as 16 horas do dia 15/12/2025 o município de Durandé foi atingido por forte precipitações chuvosas, caracterizadas como chuvas intensas (COBRADE 13214), causando desastres múltiplos, vários córregos transbordaram na zona rural, ocasionando a destruição e abalo de pontes de concreto, destruindo bueiros e tubulões, deslizamento de massa (taludes e encostas) e destruição de estadas por enxurradas.', '2025-12-18 18:55:31', '2025-12-18 18:55:31', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28063, 2352, 1, 157, 'Em decorrência do desastre apontado, 2000 (duas mil) pessoas residentes na proximidade dos cursos d\'água transbordados foram afetadas com o com os desastres, tendo sua locomoção nas estradas afetadas, devido à inundação dos afluentes e o abalo de pontes, bueiros e deslizamentos de massa (queda de barreira).', '2025-12-18 18:55:31', '2025-12-18 18:55:31', NULL);
