	(28068, 3360, 10, 158, 'O município de Itapeva / MG, conforme previsão meteorológica e alertas emitidos, por volta das 00h25min do dia 17 de dezembro de 2.025, foi assolado por VENDAVAL, ocasionando em queda de árvores, obstrução de vias, danos à rede elétrica e avarias em residências, especialmente na zona rural, e em decorrência do evento, houve registro de danos humanos, materiais e ambientais, consequentemente, houvera prejuízos sociais e econômicos.', '2025-12-18 19:26:33', '2025-12-18 19:26:33', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28069, 3360, 1, 158, '1.	AFETADAS DIRETAMENTE:\n5.1 - Foram registradas aproximadamente 25 familias/imoveis, afetadas em decorrência de queda de árvores, obstrução de vias, danos à rede elétrica e avarias em residências, bem como interrompendo a rotina diária.\n', '2025-12-18 19:26:33', '2025-12-18 19:26:33', NULL);
