	(28180, 4015, 10, 181, 'No dia 01/01/1026 um forte chuva atingiu o município de Mario campos, acompanhada de ventos fortes e alagamentos, afetando varias residências destelhamentos alagamentos, varias quedas de arvores, vários danos materiais , 02 PSS, Cras e uma escola municipal, pessoas desalojadas , desabrigadas, falta de energia .', '2026-01-05 12:59:35', '2026-01-05 12:59:35', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28181, 4015, 1, 181, '06 pessoas desabrigadas forram para a escola municipal. 5 pessoas foram para casa de parentes e amigos, varias pessoas tiveram suas casas alagadas, ruas interditadas devido a quedas de arvores, falta energia.', '2026-01-05 12:59:35', '2026-01-05 12:59:35', NULL);
