INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28305, 2710, 9, 207, 'PRATICAMENTE TODAS AS MUNICÍPIOS, TANTO URBANAS QUANTO RURAIS, FORAM AFETADOS COM FORTES VENTOS ACOMPANHADOS DE CHUVA.', '2026-01-19 12:44:32', '2026-01-19 12:44:32', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28306, 2710, 10, 207, 'EVENTO TEVE DURAÇÃO DE 40 MINUTOS, PRECIPITAÇÃO CHEGOU A 18.9 MM.', '2026-01-19 12:44:33', '2026-01-19 12:44:33', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28307, 6860, 8, 208, NULL, '2026-01-20 12:48:46', '2026-01-20 12:48:46', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28308, 6860, 9, 208, 'A população afetada pelas chuvas torrenciais concentra-se tanto em áreas urbanas quanto em área rural. Na zona urbana, os impactos atingem com maior incidência os bairros Frei Dimas, Lourival Soares da Costa, Manoel Pimenta, Castro Pires, Taquara, Tabajaras, Novo Horizonte, Ipiranga, Frei Júlio e Palmeiras. Além disso, há registros de população afetada na zona rural de Pedro Versiani e Topázio. Evidenciando a abrangência do desastre em diferentes regiões do município.', '2026-01-20 12:48:47', '2026-01-20 12:48:47', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28309, 6860, 10, 208, 'As chuvas registradas ao longo da segunda- feira, que era esperado os volumes estimados entre 60 e 80 mm e que na região totalizou 29 mm, tiveram como principal causa a atuação de sistemas atmosféricos instáveis, caracterizados por elevado volume de precipitação em curto intervalo de tempo. Como efeitos, foram observados alagamentos, saturação do solo, elevação do nível de cursos d\'água e deslizamentos, ocasionando transtornos à população, danos à infraestrutura urbana e rural e a necessidade de ações preventivas e emergenciais por parte do poder público.', '2026-01-20 12:48:47', '2026-01-20 12:48:47', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28310, 6860, 1, 208, 'Casa no bairro Castro Pires foi abalada com as chuvas e houve o destelhamento. Esses deslizamentos comprometeram a estabilidade de terrenos, colocando residências em iminente risco de desabamento.\nComo consequência direta dos efeitos do desastre, moradores foram expostos a situações de risco à integridade física, com necessidade de atendimentos reativos de imóveis e monitoramento contínuo das áreas afetadas, a fim de evitar acidentes mais graves e preservar vidas.', '2026-01-20 12:48:47', '2026-01-20 12:48:47', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28311, 6860, 2, 208, ' evento ocasionou danos ao patrimônio público, com alagamentos em diversas vias da cidade, acúmulo de lama, resíduos e entulhos. Tal cenário demandou a mobilização de equipes e recursos para a execução de serviços de limpeza urbana, desobstrução de vias e restauração das condições de trafegabilidade, gerando custos adicionais ao poder público municipal, principalmente na via Central da cidade, que a vários anos já vem sofrendo com os alagamentos.', '2026-01-20 12:48:47', '2026-01-20 12:48:47', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28312, 6860, 11, 208, 'Foi necessária a realização de limpeza urbana em toda a cidade, incluindo remoção de lama e detritos, desobstrução de vias e bocas de lobo e restabelecimento da trafegabilidade, ações que demandaram horas extras de servidores e reforço na logística municipal. Tais despesas decorrem diretamente dos efeitos do desastre, que comprometeram o funcionamento normal dos serviços públicos e exigiram resposta imediata para garantir a segurança da população e a retomada das atividades urbanas.', '2026-01-20 12:48:47', '2026-01-20 12:48:47', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28313, 1140, 8, 209, NULL, '2026-01-20 12:51:50', '2026-01-20 12:51:50', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28314, 1140, 9, 209, 'Moradores de parte do bairro Vila Junqueira, na área urbana, foram diretamente prejudicados.', '2026-01-20 12:51:50', '2026-01-20 12:51:50', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28315, 1140, 10, 209, 'No dia 15 de janeiro de 2026, por volta das 17 horas, a cidade de Campo Florido foi atingida por uma forte chuva, com o volume de aproximadamente 25 mm, acompanhada de granizo e fortes ventos, com duração média de 30 minutos. A Defesa Civil Municipal foi informada que danos foram causados na Rua Itaúna, no bairro Vila Junqueira. Prontamente foi realizado o deslocamento. No local, foi constatado a queda de uma árvore, que causou a queda de quatro postes de energia. Além desse local afetado, houve outras ocorrências de queda de árvore na cidade: duas árvores na Rua Ituiutaba, em frente ao Florescer, uma árvore na Rua Ibiá, em frente ao reservatório da Copasa e uma palmeira no quintal de uma residência na Rua Arthur Antônio da Silva.', '2026-01-20 12:51:50', '2026-01-20 12:51:50', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28316, 3670, 8, 210, NULL, '2026-01-20 13:28:59', '2026-01-20 13:28:59', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28317, 3670, 9, 210, 'Devido ao evento registrado através deste FIDE foram registrados entre o dia 15 de dezembro de 2025 às 18h00min e o dia 18 de\ndezembro de 2025 às 12h00min, um total de 201 boletins de ocorrência pela Defesa Civil de Juiz de Fora. As ocorrências mais impactantes\nforam vinculadas aos seguintes desastres: - Alagamentos - Total de 77 ocorrências; - Escorregamentos de Talude - Total de 49 ocorrências;\n- Inundações - Total de 31 ocorrências; No que tange à distribuição destas ocorrências, essas se encontram em andamento e afetaram todo\no território do Município de Juiz de Fora', '2026-01-20 13:29:00', '2026-01-20 13:29:00', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28318, 3670, 10, 210, 'O desastre indicado neste FIDE pode ter suas causas analisadas, sob duas perspectivas: a primeira, causadora de desastres do tipo\nhidrológico (inundações bruscas, alagamentos e enxurradas), do tipo geológico (movimentos de massa - escorregamentos de talude;\nformação de erosões de margem fluvial), assim como formação de grandes erosões) e do tipo tecnológico (colapso de edificações), que\ntiveram como evento gerador, as precipitações pluviométricas significativas que incidiram no Município de Juiz de Fora no dia 15 de\ndezembro de 2025 entre 18h00min e 19h30min, ficando os volumes de chuva mais expressivos, concentrados em um período de apenas 1\nhora. Também pode ser analisado sob a perspectiva do acúmulo de precipitações em um período de 96 horas, ou seja, entre o dia 13 de\ndezembro de 2025 e o dia 17 de dezembro de 2025, haja vista que o acúmulo expressivo de precipitações, contribui para o processo de\nsaturação do solo e deflagração de movimentos gravitacionais de massa. Neste sentido, considerando os dados do Centro Nacional de\nMonitoramento e Alerta de Desastres (Cemaden), os dados do Instituto Nacional de Meteorologia (Inmet), bem como dados de estações\nmeteorológicas da Subsecretaria de Proteção e Defesa Civil de Juiz de Fora, tem-se os dados causadores dos desastres apresentados a\nseguir. VOLUME DE CHUVAS QUE INCIDIU SOBRE O MUNICÍPIO DE JUIZ DE FORA NO DIA 15 DE DEZEMBRO DE 2025 - CONCENTRADAS\nEM 1 HORA Bairro: Linhares (Região de Planejamento Leste) - 109,74 mm; Bairro: Santa Rita de Cássia (Região de Planejamento Leste) -\n105,01 mm; Bairro: Bandeirantes (Região de Planejamento Nordeste) - 101,40 mm; Bairro: Marumbi (Região de Planejamento Leste) -\n101,09 mm. Nos pontos onde foram identificados registros de volume de chuvas mais significativos no período supracitado (concentrado em\n1 hora), tem-se um total de 35% da média histórica para o mês de dezembro em Juiz de Fora (que é de 310,4 mm), sendo assim, um valor\nmuito expressivo para o período de 1 hora. Com base na equação IDF do Município, isso representa uma chuva com Tempo de Recorrência\n(TR) de 143 anos. VOLUME DE CHUVAS QUE INCIDIU SOBRE O MUNICÍPIO DE JUIZ DE FORA, ENTRE OS DIAS 13 DE DEZEMBRO DE 2025\nE 17 DE DEZEMBRO DE 2025 - PERÍODO DE 96 H Bairro: Filgueiras (Região de Planejamento Nordeste) - 174,2 mm; Bairro: Linhares\n(Região de Planejamento Leste) - 167,0 mm; Nos pontos onde foram identificados registros de volume de chuvas mais significativos no\nperíodo supracitado (concentrado em 96 horas), tem-se um total de 56,2% da média histórica para o mês de dezembro em Juiz de Fora\n(que é de 310,4 mm), sendo assim, um valor muito expressivo para o período de 1 hora. Em ambas as perspectivas, considerando o plano\nde contingência do período chuvoso (2025-2026) do Município de Juiz de Fora/MG, verifica-se que foi ultrapassado os limiares de chuva\nrelacionados ao nível de alerta máximo para deflagração de movimentos de massa e inundações. Os efeitos deste evento foram: Destruição\nda infraestrutura viária de algumas vias; Destruição parcial e total de edificações; Perdas materiais oriundas de eventos de inundações,\nalagamentos e movimentos de massa (escorregamentos de talude); Trânsito bloqueado e com velocidade reduzida em áreas atingidas;\nPerdas materiais em edificações; Perdas de veículos em áreas atingidas por desastres; Unidade Básica de Saúde (UBS) do Bairro Linhares\ncom atendimento paralisado por ter sido atingida por inundação; Em alguns locais, foi identificado que a lâmina d¿água oriunda das\ninundações atingiu uma altura de aproximadamente 2,0 m. Estima-se que com o desastre em questão, quase 5.000 pessoas foram\nafetadas. Foi decretada Situação de Emergência devido ao desastre.', '2026-01-20 13:29:00', '2026-01-20 13:29:00', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28319, 3670, 1, 210, 'As pessoas que ficaram temporariamente desalojadas são aquelas que tiveram seus imóveis temporariamente ou totalmente interditados\npela Defesa Civil. As famílias que se enquadram nos perfis socioeconômicos foram encaminhadas para o Programa Auxílio-Moradia do\nMunicípio. Em suma as interdições foram realizadas por estarem relacionados a desastres deflagrados gerando danos nos imóveis, ou\ndevido a condição de risco iminente de desastre. Neste sentido, o Serviço Social da Defesa Civil identificou um total de 63 (sessenta e três)\npessoas. Na área outros afetados, foi considerada toda a população que tiveram seus imóveis atingidos pelas inundações nos Bairros\nLinhares, Vitorino Braga, Bom Jardim, Vila dos Sonhos, Grama; que foram atingidos por alagamentos nos Bairros Centro, São Mateus, Alto\ndos Passos; bem como aqueles que tiveram seus imóveis impactados por movimentos de massa ou outros tipos de ocorrência registradas\npela Defesa Civil, mas que não geraram interdição.', '2026-01-20 13:29:00', '2026-01-20 13:29:00', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28320, 3670, 2, 210, NULL, '2026-01-20 13:29:00', '2026-01-20 13:29:00', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28321, 3670, 11, 210, 'No que tange ao sistema de limpeza urbana do Município, foi necessário a realização de serviços de raspagem de lama e lavação de via\npública, após cenários de inundações nos Bairros Grama, Vila dos Sonhos, Linhares, Vitorino Braga, Bom Jardim, Industrial, bem como de\nenxurradas em Cachoeira e remoções de solo após deslizamentos. Estima-se cerca de 6.439 metros de via que demandaram serviços de\nraspagem de lama e lavação de via pública, após cenários de inundação. Devido a efeitos de inundações, boa parte dessas ruas também\ndemandaram recolhimento de grande volume de resíduos, mobiliários, eletrodomésticos e vestuário. Estima-se que tal serviço esteja sendo\nrealizado em aproximadamente 5.600 metros de via. Foram utilizados retroescavadeiras, caminhões pipa, pás carregadeiras, caminhões\nbasculantes e equipes de limpeza urbana neste serviço. Considera-se por fim, o custo com bota-fora para destinação dos resíduos oriundos\ndo recolhimento após inundações. Estima-se assim, que o custo somente com a limpeza das áreas afetadas diretamente pelo desastre é de\naproximadamente R$ 1.969.653,60; Há ainda de se citar os serviços de limpeza de boca de lobo e desobstrução de córregos. Com os efeitos\ndo desastre, se fez necessário a remoção de resíduos sólidos e sedimentos de bocas de lobo, bem como serviços de desobstrução de redes\nde drenagem com caminhões limpa fossa. Além disso, com grande volume de resíduos carregados pela força dos córregos alvo de\ninundações, geraram a necessidade de desobstrução de galerias em diversos pontos da cidade. Estima-se que com a ação em questão,\ntenha sido necessário um volume de recursos de aproximadamente R$ 599.864,26. Em relação a limpeza e desinfecção de imóveis,\nconsiderando a disponibilização de itens de ajuda humanitária às famílias atingidas, limpeza dessas edificações, bem como incentivos\ntributários (como cálculo da conta de água pela média mensal), para minimizar as perdas destas famílias e os gastos com lavação dos\nimóveis pós-desastre, estima-se um prejuízo de aproximadamente R$ 2.472.500,00; Ademais, por ser uma área afetada por inundação, temse ainda o prejuízo vinculado à necessidade de assistência médica, vacinação, cuidados com doenças como a leptospirose, dentre outros.\nFoi realizada a mobilização de vacimóvel para atender a população local. Estima-se assim, que o custo somente com questões simples\nrelacionados à assistência médica, seja de R$ 143.750,00; No que tange às questões relacionadas aos danos à rede pública de esgoto e à\nrede pública de águas pluviais, estima-se que o prejuízo do poder público - R$ 5.274.851,70, isto aplicado a recuperação emergencial para\nnão gerar danos e prejuízos ainda maiores à população; A área de transportes foi prejudicada com grandes congestionamentos na cidade,\ndevido a obstruções e vias que ficaram intransitáveis, após os desastres, haja vista outros tipos de perdas, como de veículos que tiveram\ndanos severos após serem atingidos por alagamentos e inundações. Estima-se nessa área, um prejuízo de aproximadamente R$ 98.140,34.\nPontua-se ainda outros prejuízos públicos, haja vista que visando minimizar o impacto para a população atingida pelas inundações foi\nconcedida isenção tributária de IPTU para o ano de 2026. Com isso, estima-se inicialmente uma perda de receita para o Município de Juiz de\nFora com o desastre, de aproximadamente R$ 907.500,00; Assim, inicialmente estima-se um prejuízo econômico público de\naproximadamente R$ 11.466.259,90, com o desastre indicado neste FIDE.', '2026-01-20 13:30:59', '2026-01-20 13:30:59', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28322, 3670, 12, 210, 'Devido aos desastres que incidiram sobre as áreas listadas neste FIDE foi identificado um impacto significativo, para a área de comércio e\nserviços. Estima-se que cerca de 200 estabelecimentos comerciais e de serviços foram diretamente impactados, com perdas de mercadorias,\nequipamentos, eletrodomésticos, mobiliários, dentre outros itens. Considerando que em cenários de inundações, as áreas não são atingidas\nem mesmo nível de intensidade, ou seja, ao longo da mancha atingida, alguns imóveis com maiores danos e outros com menores, estima-se\nque os prejuízos para os empresários locais sejam de cerca de R$ 12.789.811,00.\n', '2026-01-20 13:30:59', '2026-01-20 13:30:59', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28323, 6860, 8, 211, NULL, '2026-01-20 16:38:20', '2026-01-20 16:38:20', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28324, 6860, 9, 211, 'A população afetada pelas chuvas torrenciais concentra-se tanto em áreas urbanas quanto em área rural. Na zona urbana, os impactos atingem com maior incidência os bairros Taquara, vila Betel, Jardim Iracema, Castro Pires, Centro e Zona Rural de Topázio. Evidenciando a abrangência do desastre em diferentes regiões do município. ', '2026-01-20 16:38:21', '2026-01-20 16:38:21', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28325, 6860, 10, 211, 'As chuvas registradas ao longo da quarta- feira, que era esperado chuvas não significativas no dia e que fomos surpreendidos e houve um volume bem significativo para a região totalizou 45 mm, tiveram como principal causa a atuação de sistemas atmosféricos instáveis, caracterizados por elevado volume de precipitação em curto intervalo de tempo. Como efeitos, foram observados alagamentos, saturação do solo, elevação do nível de cursos d\'água e deslizamentos, ocasionando transtornos à população, danos à infraestrutura urbana e rural e a necessidade de ações preventivas e emergenciais por parte do poder público.', '2026-01-20 16:38:21', '2026-01-20 16:38:21', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28326, 6860, 1, 211, 'Embora não tivemos chamados significativos, como já de costume houve alagamentos, inundações da Zona sul e Central da cidade.\nComo consequência direta dos efeitos do desastre, moradores foram expostos a situações de risco à integridade física, com necessidade de atendimentos reativos de  limpeza e monitoramento contínuo das áreas afetadas, a fim de evitar acidentes mais graves e preservar vidas.', '2026-01-20 16:38:21', '2026-01-20 16:38:21', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28327, 6860, 2, 211, 'o evento ocasionou danos ao patrimônio público, com alagamentos em diversas vias da cidade, acúmulo de lama, resíduos e entulhos. Tal cenário demandou a mobilização de equipes e recursos para a execução de serviços de limpeza urbana, desobstrução de vias e restauração das condições de trafegabilidade, gerando custos adicionais ao poder público municipal, principalmente na via sul e Central da cidade, que a vários anos já vem sofrendo com os alagamentos.', '2026-01-20 16:38:21', '2026-01-20 16:38:21', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28328, 6860, 11, 211, 'Foi necessária a realização de limpeza urbana em toda a cidade, incluindo remoção de lama e detritos, desobstrução de vias e bocas de lobo e restabelecimento da trafegabilidade, ações que demandaram horas extras de servidores e reforço na logística municipal. Tais despesas decorrem diretamente dos efeitos do desastre, que comprometeram o funcionamento normal dos serviços públicos e exigiram resposta imediata para garantir a segurança da população e a retomada das atividades urbanas.', '2026-01-20 16:38:21', '2026-01-20 16:38:21', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
