INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28353, 6870, 1, 218, 'Em decorrência das chuvas intensas acompanhadas de rajadas de vento, foi registrado destelhamento parcial de uma residência, localizada na Rua Gameleira, nº 11, bairro Recanto Verde, com a quebra de 05 (cinco) telhas.\nNão houve registro de vítimas fatais, feridos, enfermos, desaparecidos, desabrigados ou desalojados.\nO morador foi diretamente afetado, em razão dos danos materiais à edificação, sendo necessária a doação de 05 (cinco) telhas pela Defesa Civil Municipal para recomposição emergencial da cobertura e mitigação dos riscos imediatos.', '2026-01-22 18:48:41', '2026-01-22 18:48:41', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28354, 6870, 2, 218, '01 (uma) unidade habitacional com destelhamento parcial, localizada na Rua Gameleira, nº 11, bairro Recanto Verde, com quebra de 05 (cinco) telhas, sem necessidade de desocupação do imóvel;\n\nVias públicas com acúmulo de lama e sedimentos, em razão de serviços de terraplanagem executados de forma inadequada, afetando temporariamente a trafegabilidade;\n\nDispositivos de drenagem (boca de lobo e manilhas) demandando limpeza preventiva e corretiva, em função do aumento do escoamento superficial após chuvas intensas;\n\nInterferências pontuais em infraestrutura urbana, relacionadas a obras de concessionárias (água e esgoto), com alteração do fluxo superficial de águas pluviais e registros de alagamento pontual em imóvel residencial;\n\nÁreas com instabilidade superficial de solo, decorrentes de cortes irregulares e processos erosivos, exigindo monitoramento, orientação aos responsáveis e medidas de contenção e revegetação.', '2026-01-22 18:48:41', '2026-01-22 18:48:41', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
