	(28356, 2330, 9, 219, 'ZONA URBANA\n\nRua Aquiles Marotta, Centro\nRua São Crsitovão, Centro. ', '2026-01-22 18:52:56', '2026-01-22 18:52:56', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28357, 2330, 10, 219, 'Ocorreram Chuvas Intensas na Zona Urbana e Rural do Município de Dores do Turvo por volta das 05h do dia 20 de Janeiro de 2026, que duraram ao longo de toda a madrugada e deste dia, com acumulado de 60 mm de precipitações, afetando várias Comunidades Rurais e o perímetro urbano. Tendo afetado várias Comunidades e pontos da Zona Urbana. Na Rua Aquiles Marotta, a intensidade das chuvas provocou a danificação de um sistema de drenagem pluvial ocasionando uma expressiva erosão levando a interdição da via pública. E, na Rua São Cristóvão, ocasionou alagamentos em residências vindo os moradores sofrerem bens materiais). Foram registradas 06 pessoas desabrigadas após a ocorrência de alagamento, estimando-se que 300 pessoas foram afetadas direta e indiretamente pelo desastre em razão do dano na drenagem e alagamento da via pública ilhada.', '2026-01-22 18:52:56', '2026-01-22 18:52:56', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28358, 2330, 1, 219, 'Ocorreram Chuvas Intensas na Zona Urbana e Rural do Município de Dores do Turvo por volta das 05h do dia 20 de Janeiro de 2026, que duraram ao longo de toda a madrugada e deste dia, com acumulado de 60 mm de precipitações, afetando várias Comunidades Rurais e o perímetro urbano. Tendo afetado várias Comunidades e pontos da Zona Urbana. Na Rua Aquiles Marotta, a intensidade das chuvas provocou a danificação de um sistema de drenagem pluvial ocasionando uma expressiva erosão levando a interdição da via pública. E, na Rua São Cristóvão, ocasionou alagamentos em residências vindo os moradores sofrerem bens materiais). Foram registradas 06 pessoas desabrigadas após a ocorrência de alagamento, estimando-se que 300 pessoas foram afetadas direta e indiretamente pelo desastre em razão do dano na drenagem e alagamento da via pública ilhada.', '2026-01-22 18:52:56', '2026-01-22 18:52:56', NULL);
