	(28377, 7080, 9, 225, 'zona urbana. BAIRROS LAMEIRÃO I E II, CAIÇARA, PAULO VI, PEDRAS GRANDES E PLANALTO , CENTRO', '2026-01-25 18:06:22', '2026-01-25 18:06:22', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28378, 7080, 10, 225, 'No dia 24/01/2026, o município foi atingido por uma intensa chuva, com volume acumulado de aproximadamente 110 mm, ocasionando alagamentos e enxurradas, que evidenciam a extensão dos impactos na vida da população local.\n\nComo consequência do evento, várias pessoas ficaram desalojadas, havendo o registro de 01 pessoa desabrigada. Foram registrados alagamentos em diversas residências, além de danos em estradas vicinais, pontes e vias urbanas.\n\nO evento resultou em prejuízos econômicos tanto no setor público quanto no privado.', '2026-01-25 18:06:22', '2026-01-25 18:06:22', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
