	(28388, 4430, 9, 228, 'Bairros: Centro, Campinho, Vila Esperança, UDR, UDR2e  Naknuk.', '2026-01-26 12:11:44', '2026-01-26 12:11:44', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28389, 4430, 10, 228, 'No dia 21/01/2026, ocorreram chuvas intensas na cidade de Nanuque. Foram registrados 100 mm de precipitação medidos durante 24h, segundo pluviômetro instalado pela Prefeitura Municipal. A chuva começou por volta das 12h00 do dia 21/01, no qual teve um pico de intensidade com duração até as 14h,  e durou até o dia 22/01 as 21h. A água subiu rapidamente, causando enxurrada pelas vias publica, causou alagamento em casas e comércio. Isso ocasionou entupimento de bueiros e danificou algumas pavimentações.\n', '2026-01-26 12:11:44', '2026-01-26 12:11:44', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
