INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28495, 350, 9, 249, 'Bairros Bosque, Jardim Botânico, Sibipiruna e Paineiras tiveram maiores danos e prejuízos com o vendaval. Também tivemos danos e prejuízos por toda a cidade principalmente com quedas de arvores em cima de telhados e veículos,  quiosques públicos, interdição de vias, queda de arvores sobre postes de energia cortando seu fornecimento.   ', '2026-01-28 16:50:44', '2026-01-28 16:50:44', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28496, 350, 10, 249, 'sete eucaliptos de grande porte tombaram sobre a via pública e sobre a rede de energia elétrica da concessionária, ocasionando a interrupção do fornecimento de energia em diversos bairros da cidade. Ainda nessa ocorrência, foram registradas quedas de árvores no interior do Frigorífico Santa Lúcia, atingindo setores da empresa.\nDiversos bairros apresentaram alagamentos causados pelo excesso de chuvas, entupimento de bueiros e, em alguns locais, pela inexistência ou ineficiência do sistema de drenagem pluvial, prejudicando significativamente o deslocamento de pedestres e veículos. Houve intenso escoamento de enxurradas pelas ruas Bias Fortes e Coronel José Ferreira Alves, transportando grande quantidade de barro e resíduos para vias adjacentes, agravando as condições de tráfego e segurança dos moradores da região.\nHouve na Av. Theodoreto Veloso de Carvalho queda de 07 arvores sendo 05 arrancadas com raiz inteira, além de galhos e uma dessas arvores caiu sobre um quiosque publico. ', '2026-01-28 16:50:44', '2026-01-28 16:50:44', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28497, 350, 2, 249, 'Quiosque publico danificado seu telhado, 05 postes de energia foram quebrados com queda de 07 arvores de eucaliptos, prejudicando o fornecimento de energia elétrica para vários bairros da região leste.', '2026-01-28 16:50:44', '2026-01-28 16:50:44', NULL);
