INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28517, 5340, 9, 256, 'O local do desastre refere-se a localidade rural QUATI, que dá acesso a diversas localidades rurais. São elas: Comunidade Água Boa, Raiz, Cipó, Pindaíba, Duas Barras, Cais. O local ainda é percursso de acesso ao municipio vizinho Santana de Pirapama', '2026-01-29 16:17:17', '2026-01-29 16:17:17', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28518, 5340, 10, 256, 'Em decorrência do grande volume de chuvas, na localidade rural QUATI, houve rompimento de manilha para passagem de água pluvial e fluvial. A via foi interditada. A via é responsável por dar acesso a diversas propriedades rurais desemcadeando transtornos quanto a atividades de agricultura, pecuária, mineração, e turismo. ', '2026-01-29 16:17:17', '2026-01-29 16:17:17', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28519, 5340, 2, 256, 'Queda de muro de arrimo e rompimento de manilha para passagem de água fluvial e pluvial. Com o colapso estrutural houve o movimento de massa para o leito do curso d agua. ', '2026-01-29 16:17:17', '2026-01-29 16:17:17', NULL);
