INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28559, 6110, 1, 263, 'Muitas regiões do nosso município foram afetadas principalmente da zona rural, com estradas sendo danificadas e moradores tendo perdas, principalmente em suas plantações devido as inundações provocadas pela elevação no nível do Rio São Francisco, muitos moradores tiveram perdas de móveis e danos em suas residências na área rural devido as inundações provocadas pela elevação do nível do rio São Francisco, sendo que cerca de 800 pessoas foram desalojadas, indo para casa de parentes e amigos e no total cerca de 5.000 pessoas foram afetadas pelo desastre das chuvas intensas e inundações em nosso município.', '2026-01-30 17:15:49', '2026-01-30 17:15:49', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28560, 6110, 2, 263, '100 unidades habitacionais foram danificadas necessitando de reparos para que os moradores tenham segurança e dignidade.\n\nDANIFICADO\n\n\nNa zona rural: Comunidades Ilha das Porteiras, Bom Jardim de Baixo, Ilha da união, Cascalho e Ilha do Vitor, foram as mais afetadas pelas inundações provocadas pela elevação do nível do rio São Francisco tendo cerca de 166 pessoas desalojados nessas regiões cerca de 100 casas danificadas, estrada da comunidade Assentamento São francisco e Tapera foram prejudicadas prejudicada devido as enxurradas e alagamento no local, estrada que dá acesso a comunidade do Mocambo também foi prejudicada pelas enxurradas com buracos prejudicando a trafegabilidade na região, estrada na comunidade Travessão de Minas foi alagada pelo córrego devido as chuvas prejudicando a trafegabilidade no local, na comunidade Boa Vista estradas ficaram prejudicadas pelas chuvas, com buracos na via e lama e na comunidade São Domingos a via também ficou alagada e prejudicada pelo desastre e as pontes da comunidade Tapera e Caroba foram danificadas.\n\nNa zona urbana: As ruas mais afetadas foram a Silva Jardim localizada próximo ao centro da cidade no bairro Jardim Regalito que além do lixo entupindo galerias teve parte do asfalto arrancado e a via danificada, a rua Padre Elifaz e Padre Melquíades  e Avenida Arnaldo Lima no bairro Sagrada Família e Rua F no bairro Funcionários também foram muito danificadas pelas enxurradas causando buracos na via e alagamentos que atrapalharam a trafegabilidade na região e prejudicaram moradores locais, a Avenida Oscar Caetano Gomes que foi danificada e alagada prejudicando a trafegabilidade na região, a rua Amadeu Gomes da Mata também foi muito afetada no bairro Santo Antônio.\nRuas foram danificadas tendo seu calçamento arrancado, bueiros obstruídos por lixo, causando alagamentos em diversos pontos, principalmente na área central da cidade e na zona rural muitas estradas foram afetadas e obras de infraestruturas públicas também.\n\nA Até o momento envio do processo, os levantamentos, e as vistorias ainda estão sendo  feitos,  devido a grande quantidade de danos nas estradas  do município tanto na zona urbana como rural.\n', '2026-01-30 17:15:49', '2026-01-30 17:15:49', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28561, 6110, 11, 263, 'Gastos com:\nLocação maquinário para limpeza das rua, vias, desobstrução das estradas, - R$120.000,00  -\nAbastecimento do maquinário em Combustível para as limpeza e obras de restabelecimento das vias do município - R$ 50.000,00\nManutenção e conserto das casas de bombas das bacias dos Quebra e Luzia - R$ 3.572,50\nMão de Obra e Funcionários Contratados para o serviço de limpeza urbana: R$ 46.427,50\nTotalizando: Aproximadamente 220.000,00 de prejuízos em função do desastre.\n\nValores Aproximados pois ainda estamos fazendo os levantamentos dos prejuízos causados pelo desastre.', '2026-01-30 17:15:49', '2026-01-30 17:15:49', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28562, 6110, 12, 263, 'Houve bastante chuva no município e nas regiões da bacia do rio São Francisco, causando enchente do rio São Francisco, houve inundações nas comunidades ribeiras, causando perdas nas roças de feijão, abóbora, milho, sorgo, hortaliças e diminuição das áreas de pastagens trazendo prejuízos aos agricultores, sendo: \n\nFeijão 1ª Safra - R$ 525.000,00\nFeijão 2ª Safra - R$ 477.800,00\nAbóbora - R$ 424.000,00\nMilho - R$ 2.016.000,00\nSorgo Forrageiro - R$ 3.150.000,00\nTotalizando R$ 6.592.800,00 de perdas na Agricultura.\n\nNa pecuária houve prejuízo Econômico em função da redução da produção de carne: 126.905,80\n\nConforme relatório da Emater.', '2026-01-30 17:15:49', '2026-01-30 17:15:49', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28563, 855, 8, 264, NULL, '2026-01-30 17:31:49', '2026-01-30 17:31:49', NULL);
