INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28616, 3652, 10, 275, 'Que em decorrência desse desastre vários danos e prejuízos foram ocasionados no Município, com alagamentos em diversos pontos, com\ndanos humanos: estima-se que toda a população do município foi afetada pelas fortes chuvas, sendo assim discriminado: 1 pessoa foi\ndesabrigada, certa de 3000 pessoas da zona rural com acesso parcialmente interditado em estradas vicinais. Danos matérias: foram\nsignificativos e abrangem diversos setores, afetando a infraestrutura pública e privada, incluindo, unidades habitacionais, vias urbanas,\nestradas vicinais, assim descritas: alagamento em diversos pontos, danos materiais na Farmácia e Abrigo Municipais e em diversos\ncomércios localizados na rua principal que foram invadidos pela água e lama, a quadra poliesportiva municipal também foi invadida pela\nlama, destruição parcial do encabeçamento da ponte do ribeirão Gangorras, que é o principal acesso à sede do município, rompimento de\nparte da estrada que liga a comunidade de Limeira a Sede, rompimento do gabião da estrada rural sentido a comunidade rural do córrego\ndo arrozal, danos da estrutura de concreto do manilhamento da estrada vicinal da comunidade de Ribeirão Gangorras, destruição do\nsistema de drenagem em tubo de concreto na estra', '2026-02-03 18:00:27', '2026-02-03 18:00:27', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28617, 3652, 1, 275, '1 pessoa desalojada foi deslocada para casa de parentes, das 4577 pessoas afetadas algumas ficaram isoladas sem acesso possível,\nalgumas com deslocamentos interditados por deslizamento de terra em estradas vicinais outras com moradia em situação de risco devido a\ndeslizamento de taludes, o que afetou a todos de maneira direta e indireta.', '2026-02-03 18:00:27', '2026-02-03 18:00:27', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28618, 3652, 2, 275, '-02 residências na área urbana danificadas - Cerca de 15 comércios inundados - Danos ao calçamento de bloquetes na rua São Sebastião e\ntravessa José Paulo Pereira. - Danos na estrutura de concreto do manilhamento da estrada vicinal da comunidade de Ribeirão Gangorras. -\nponte de madeira danificada - Comunidade de Dileta - O abrigo da UBS Municipal e a Farmácia foram danificados . quadra poliesportiva\nmunicipal foi alagada , ocasionando danos parciais na estrutura - Rompimento de parte da estrada que liga a Comunidade de Limeira a\nSede. - Rompimento de gabião de estrada rural sentido comunidade Córrego do Arrozal - Destruição parcial na cabeceira da ponte do\nRibeirão Gangorras - Destruição do sistema de drenagem em tubo de concreto na estrada vicinal no sentido da comunidade de Limeira -\nAssoreamento do Ribeirão Gangorras\n', '2026-02-03 18:00:27', '2026-02-03 18:00:27', NULL);
