INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28776, 4530, 9, 308, 'ZONA RURAL: Comunidade de Capão, Distrito de Queixada e Lufa.', '2026-02-10 12:05:18', '2026-02-10 12:05:18', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28777, 4530, 10, 308, 's fortes chuvas que atingiram o município de Novo Cruzeiro, em Minas Gerais, no dia 6 de fevereiro de 2026, causaram impactos significativos nas comunidades rurais: Comunidade de Capão, Distrito de Queixada e Lufa. As intensas enxurradas danificaram aproximadamente 30 estradas vicinais que interligam os povoados aos distritos; bueiros foram arrancados e cabeceiras de pontes sofreram danos estruturais.', '2026-02-10 12:05:18', '2026-02-10 12:05:18', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28778, 4530, 1, 308, 'As consequências das chuvas intensas deixaram 3.100 pessoas afetadas em Novo Cruzeiro (MG), cujas rotinas foram gravemente comprometidas. Muitas famílias ficaram ilhadadas ou impossibilitadas de transitar com veículos em razão dos danos na infraestrutura viária rural. As escolas estão fechadas, prejudicando diretamente a educação dos alunos.\nAlém do isolamento físico, a população rural enfrenta diversos outros impactos decorrentes da falta de acesso pelas estradas vicinais danificadas ou interditadas.', '2026-02-10 12:05:18', '2026-02-10 12:05:18', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28779, 4530, 2, 308, 'As fortes chuvas que atingiram o município de Novo Cruzeiro (MG) provocaram danos graves na infraestrutura viária rural, resultando no comprometimento de 30 estradas vicinais, aproximadamente 100km de malha viária prejudicada. \n\nOutros principais danos identificados incluem:\n\n-Erosão profunda do leito e dos taludes das vias, com formação de crateras de erosão e grandes voçorocas, tornando trechos intransitáveis para veículos;\n-Rompimento de 2 bueiros de drenagem transversal (que conduzem a água por baixo das estradas), causando colapso do aterro e interrupção total do tráfego;\n-Desabamento ou arrancamento de 10 cabeceiras de pontes (estruturas de contenção nas extremidades das pontes), levadas pela força das enxurradas, o que comprometeu a estabilidade das obras e isolou acessos a comunidades.', '2026-02-10 12:05:18', '2026-02-10 12:05:18', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28780, 4530, 11, 308, 'A Prefeitura Municipal de Novo Cruzeiro, por meio da Secretaria de Obras e Serviços Públicos, mobilizou uma máquina carregadeira, uma patrol e uma caçamba para realizar operações de desobstrução, limpeza e recuperação emergencial das estradas vicinais afetadas pelas fortes chuvas. Diversos voluntários e servidores municipais participaram ativamente das ações, trabalhando em conjunto para restabelecer, na medida do possível, a normalidade nas localidades impactadas.', '2026-02-10 12:05:18', '2026-02-10 12:05:18', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28781, 4530, 12, 308, 'Em virtude das fortes chuvas que provocaram alagamentos e enxurradas na região, as lavouras de milho, mandioca, feijão e demais cultivos destinados à subsistência familiar foram severamente afetadas, com grande parte sendo arrastada ou completamente destruída pelas águas.', '2026-02-10 12:05:18', '2026-02-10 12:05:18', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28782, 1080, 8, 309, NULL, '2026-02-10 12:10:33', '2026-02-10 12:10:33', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28783, 1080, 9, 309, 'No dia 06 de fevereiro de 2026, o município foi atingido por um evento de tempestade severa. A precipitação iniciou-se de forma moderada por volta das 05h00. A partir das 05h40, houve um aumento significativo na intensidade pluviométrica, evoluindo para um temporal de forte magnitude entre as 07h00 e 08h30.\nDados Meteorológicos Estimados:\nVolume Estimado: Aproximadamente 70mm.\nJanela Crítica: 01h30min (período de maior concentração).\nIntensidade: A alta taxa de precipitação em curto intervalo de tempo superou a capacidade de escoamento do sistema de drenagem urbana/rural.', '2026-02-10 12:10:34', '2026-02-10 12:10:34', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28784, 1080, 10, 309, 'Considerando o volume de 70mm em pouco mais de uma hora, ocorreu:\nAlagamentos repentinos e enxurradas.\nTransbordamento de córregos ou canais.\nDanos à infraestrutura viária (erosão ou obstrução) em área urbana e rural. ', '2026-02-10 12:10:34', '2026-02-10 12:10:34', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28785, 1080, 1, 309, 'Devido à intensidade da precipitação 70mm em curto período, apesar da magnitude do evento e da afetação generalizada da população, não houve registro de desalojados ou desabrigados. O impacto humano concentrou-se na afetação direta dos munícipes pela interrupção da mobilidade, isolamento temporário de bairros e invasão de águas em residências, sem que houvesse necessidade de remoção definitiva ou temporária para abrigos ou casas de terceiros.', '2026-02-10 12:10:34', '2026-02-10 12:10:34', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28786, 1080, 2, 309, 'Drenagem: Colapso do sistema de escoamento pluvial em diversos pontos.\nInfraestrutura: Danos em vias públicas (pavimentação e estradas vicinais) e obstrução de bueiros e galerias.', '2026-02-10 12:10:34', '2026-02-10 12:10:34', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28787, 1270, 8, 310, NULL, '2026-02-10 12:18:07', '2026-02-10 12:18:07', NULL);
