	(28790, 1530, 9, 311, 'Todos os bairros e distritos foram afetados. ', '2026-02-10 12:22:20', '2026-02-10 12:22:20', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28791, 1530, 10, 311, 'O evento durou 2 dias choveu 160 mm, com rajadas de ventos 50 km .Foram medidos nos dias 02/02/2026 a 06/02/2026. Enxurradas em diversos pontos da cidades e distritos. Elevação dos córregos ,ribeirão Meia Pataca e o Rio Pomba. Mas por enquanto sem transbordo.', '2026-02-10 12:22:20', '2026-02-10 12:22:20', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28792, 1530, 2, 311, 'Desmoramento de um muro de conteção na divisa da Av: Rotary com o ribeirão meia pataca. Via inteditada,somento mão única.', '2026-02-10 12:22:20', '2026-02-10 12:22:20', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
