	(28794, 1550, 9, 313, 'Bairro Santa Tereza, Bairro Centro', '2026-02-10 12:27:50', '2026-02-10 12:27:50', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28795, 1550, 10, 313, 'Na data de 05/02/2026 as 16 horas a Defesa Civil foi acionada devido ao colapso de um muro de divisa. A defesa civil deslocou até ao endereço e pode constatar que devido as fortes chuvas ocorridas na cidade e de que a saída da agua pluvial proveniente das casas acima estava entupida, fato que provocou o acumulo de agua no muro, gerando peso excessivo e que posteriormente levou ao colapso do muro. Durante ao atendimento da ocorrência a defesa civil procedeu com a desobstrução da saída da agua, fato que em menos de 5 minutos toda agua já havia escoado. Posteriormente procedemos com a eliminação do risco de colapso do restante do muro e orientamos aos proprietários que providenciassem a limpeza do local.\nQuanto aos afetados diretamente foram 2.', '2026-02-10 12:27:50', '2026-02-10 12:27:50', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28796, 1550, 1, 313, 'As pessoas foram afetadas devido as fortes chuvas, fato que gerou interdição de ruas desvios de transito.', '2026-02-10 12:27:50', '2026-02-10 12:27:50', NULL);
