	(28800, 4650, 8, 315, NULL, '2026-02-10 12:30:46', '2026-02-10 12:30:46', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28801, 4650, 9, 315, 'A área afetada está localizada no perímetro urbano, esquina da Rua Joaquim Murtinho com a Av. 1° de Janeiro, afetando cerca de 30 residenciais diretamente com o abatimento do solo que está vindo de forma recorrente, mesmo a prefeitura realizando intervenções no local. \n', '2026-02-10 12:30:47', '2026-02-10 12:30:47', NULL);
