INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28805, 7047, 9, 316, 'Na data mencionada, uma árvore arrastada pela força da correnteza do rio chocou-se contra a estrutura da Ponte do São Miguel, ocasionando danos parciais. O ocorrido resultou em interdição parcial, restrita à passagem de ônibus e caminhões, comprometendo o fluxo do transporte escolar. O tráfego de veículos leves permaneceu liberado, até a realização de avaliação técnica e adoção das medidas necessárias para a recuperação da estrutura.', '2026-02-10 12:34:13', '2026-02-10 12:34:13', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28806, 6850, 8, 317, NULL, '2026-02-10 12:39:09', '2026-02-10 12:39:09', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28807, 6850, 9, 317, 'As principais áreas atingidas foram os bairros Centro, Vila Santana, Patrimônio e Progresso, todos de caráter urbano e próximos a áreas de Preservação Permanente (APP).\n\nOs principais impactos registrados foram a invasão de água em estabelecimentos comerciais e vias públicas, o desplacamento de vias com remoção de pavimentação, a queda de um muro, além de demais transtornos à população e à mobilidade urbana.\n\nO evento pluviométrico apresentou duração aproximada de 40 (quarenta) minutos.\n\nNa zona rural, foram registradas enchentes e danos em estradas vicinais, ocasionando dificuldades no escoamento da produção agrícola e pecuária, sendo as comunidades mais afetadas: Vai e Volta, São Pedro, Bota Fogo, Bom Jardim, Bom Sucesso, Barreira, Paiol, Deveras, Contendas e Pau D¿Ário.\n\nRessalta-se que o município não dispõe de equipamento pluviométrico para medição oficial dos índices de precipitação. Contudo, observou-se que os cursos d¿água localizados na zona urbana permaneceram dentro de suas calhas, apesar da elevação significativa do nível.', '2026-02-10 12:39:09', '2026-02-10 12:39:09', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28808, 6850, 10, 317, 'O desastre foi desencadeado por precipitações pluviométricas intensas concentradas em curto intervalo de tempo, com duração aproximada de 40 (quarenta) minutos, caracterizando um evento extremo de chuva convectiva, típico do período chuvoso.\nA elevada intensidade das chuvas ocasionou rápido escoamento superficial das águas pluviais, resultando em alagamentos em áreas urbanas, formação de enxurradas, e sobrecarga do sistema de drenagem, especialmente em bairros situados em áreas mais baixas e próximas a Áreas de Preservação Permanente (APP).\nA magnitude do evento foi evidenciada pelos seguintes fatores:\nInvasão de água em estabelecimentos comerciais e vias públicas;\nDeslocamento e arrancamento de pavimentação (bloquetes) em diversas ruas;\nColapso estrutural de um muro anteriormente interditado;\nInterrupção da trafegabilidade urbana e rural;\nDanos em estradas vicinais, dificultando o escoamento da produção agrícola e pecuária;\nElevação significativa do nível dos cursos d¿água urbanos, embora sem extravasamento da calha.\nRessalta-se que o município não dispõe de estação pluviométrica, impossibilitando a quantificação precisa dos índices de precipitação, contudo, os impactos materiais, estruturais e socioeconômicos observados confirmam a relevância e a severidade do evento, enquadrando-o como desastre de origem hidrometeorológica, com ocorrência de alagamentos e enxurradas.', '2026-02-10 12:39:09', '2026-02-10 12:39:09', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28809, 6850, 1, 317, NULL, '2026-02-10 12:39:09', '2026-02-10 12:39:09', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28810, 6850, 2, 317, '1. Estabelecimento comercial ¿ Mercado Vilela\nLocalizado na Rua Antônio Moreira Barros, bairro Centro, o estabelecimento sofreu perda de mercadorias e materiais comercializados, em razão da invasão de água proveniente do alagamento, ocasionado pelas chuvas intensas e sobrecarga do sistema de drenagem urbana.\n\n2. Estrutura particular ¿ Queda de muro\nNa Rua João Abraão, nº 95, bairro Vila Santana, foi registrada a queda de um muro de propriedade particular, provocada pela ação direta da enxurrada, cujo fluxo intenso comprometeu a estabilidade estrutural da edificação, resultando em colapso da estrutura.\n\n3. Infraestrutura urbana ¿ Danificação de via pública\nNa Vila Santana, Travessa Córrego do Sapo, Rua Rubens Carneiro, verificou-se o desbloquetamento e remoção total da pavimentação intertravada, em decorrência da força do escoamento superficial das águas pluviais, que ocasionou o arraste do material e a completa perda da estrutura viária no trecho afetado.', '2026-02-10 12:39:09', '2026-02-10 12:39:09', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28811, 6850, 3, 317, 'Foram registrados danos ambientais associados à ocorrência de alagamentos e enxurradas, decorrentes das chuvas intensas concentradas em curto intervalo de tempo, que ocasionaram processos erosivos, carreamento de sedimentos e alteração temporária das condições ambientais locais, especialmente em áreas urbanas e rurais próximas a Áreas de Preservação Permanente (APP).\n\nNa zona urbana, verificou-se o arraste de resíduos sólidos, sedimentos e materiais diversos para a rede de drenagem e para os cursos d¿água, resultando em assoreamento pontual, turbidez elevada da água e potencial contaminação por resíduos urbanos, afetando temporariamente a qualidade ambiental.\n\nNa zona rural, foram observados processos de erosão superficial em estradas vicinais e áreas adjacentes, com carreamento de solo para áreas de drenagem natural e corpos hídricos, contribuindo para o assoreamento de valas, córregos e áreas de baixada, além de degradação temporária da vegetação marginal em trechos de APP.\n\nRessalta-se que os danos ambientais estão diretamente relacionados à intensidade do escoamento superficial das águas pluviais, característico de eventos de chuva extrema, e se manifestaram principalmente por erosão, transporte de sedimentos, deposição de material e alteração da dinâmica hídrica local, sem, contudo, registro de impactos ambientais permanentes até o momento da avaliação.', '2026-02-10 12:39:09', '2026-02-10 12:39:09', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28812, 6850, 11, 317, 'O desastre ocasionou impactos diretos ao sistema municipal de limpeza urbana e de recolhimento e destinação de resíduos sólidos, em razão do arraste de grande volume de resíduos, sedimentos, lama e materiais diversos para as vias públicas, bocas de lobo, galerias pluviais e áreas de acúmulo.\n\nA ocorrência de alagamentos e enxurradas demandou a mobilização extraordinária de equipes, veículos e equipamentos da limpeza urbana, para a execução de serviços emergenciais de varrição, desobstrução de drenagens, retirada de entulhos e destinação adequada dos resíduos, gerando aumento não previsto de custos operacionais, consumo de combustível, horas extras de pessoal e contratação de serviços complementares.\n\nDessa forma, o prejuízo econômico público está diretamente relacionado à necessidade de restabelecimento das condições de salubridade, segurança e mobilidade urbana, em decorrência dos efeitos do desastre hidrometeorológico.', '2026-02-10 12:39:09', '2026-02-10 12:39:09', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28813, 6850, 12, 317, 'Pecuária:\nNa zona rural, as enchentes e danos em estradas vicinais dificultaram o acesso às propriedades rurais e o transporte de insumos e produtos, ocasionando atrasos no manejo dos animais, interrupção temporária da logística de comercialização e aumento de custos operacionais, além de perdas indiretas decorrentes da impossibilidade de escoamento da produção pecuária.\n\nAgricultura:\nAs chuvas intensas e o escoamento superficial provocaram alagamento de áreas produtivas, encharcamento do solo e processos erosivos, resultando em danos às lavouras, perda de parte da produção agrícola e degradação temporária da capacidade produtiva do solo, impactando diretamente a renda dos produtores rurais.\n\nComércio:\nNo setor comercial, os alagamentos em áreas urbanas ocasionaram a invasão de água em estabelecimentos, provocando perda de mercadorias, danos a equipamentos e interrupção temporária das atividades, o que resultou em redução do faturamento e prejuízos financeiros diretos aos comerciantes locais.', '2026-02-10 12:39:09', '2026-02-10 12:39:09', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28820, 4820, 8, 321, NULL, '2026-02-11 10:26:38', '2026-02-11 10:26:38', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28821, 4820, 9, 321, 'AREA URBANA: CENTRO: Rua Cristo Rei, Travessa Rua Cristo Rei, Rua Projetada, Rua Nana Pompei, Beco Severino,\nRua Mario Daher, Av. Cel. Telêmaco Pompei e Rua Alvaro Vitor:\nAREA RURAL: COMUNIDADE PEDRA REDONDA, COMUNIDADE BARRA DO GAVIÃO; COMUNIDADE DO IVAÍ; COMUNIDADE DO MIRAVAL; COMUNIDADE DO POÇO FUNDO; COMUNIDADE DAS TRÊS BARRAS; COMUNIDADE BOA ESPERANÇA; COMUNIDADE PEROBAS; COMUNIDADE ANASTÁCIA; COMUNIDADE POUSO ALEGRE; COMUNIDADE PEROBAS; COMUNIDADE DO VALÃO; COMUNIDADE DE ENGENHO DE SERRA.', '2026-02-11 10:26:40', '2026-02-11 10:26:40', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28822, 4820, 10, 321, 'Devido às chuvas intensas que caíram no Município de Patrocínio do Muriaé, por volta das 00:30 do dia 10 de fevereiro de 2026 o Rio\nMuriaé atingiu o nível máximo de 06 metros e 76 centímetros, causando inundações em partes da cidade e de áreas rurais ribeirinhas dos\nrios Muriaé, Gavião e Ribeirão do Gato, bem como provocou alagamentos, deslizamentos de terra, danificações de pontes, danificação em\nestradas vicinais e danificação do calçamento de vias públicas, além de danos em imóveis residenciais e comerciais. Ao amanhecer foram\nverificados os seguintes danos humanos e prejuízos públicos e privados no Município de Patrocínio do Muriaé: A prefeitura Municipal através\nSecretaria Municipal de Assistência Social contabilizou 23 pessoas desabrigadas (que ficaram abrigados na sede da Secretaria de Proteção e\nDefesa Civil, no Centro Nucleo de Educação, nas salas do Sindicato rural, no salão da CELT e nos dormitórios do Ginasio Central), sendo que\n98 pessoas ficaram desalojadas(essas ficando em residências de familiares, amigos e casas alugadas provisoriamente) e 766 pessoas que\ntiveram sua rotina completamente alterada por conta do evento tendo que mudar rotas de transporte, não conseguindo ir até o trabalho e\naté ficando isoladas em alguns pontos rurais, gerando assim um total de 887 pessoas afetadas pelo evento. Devido à incapacidade material\ne alimentar momentânea das famílias afetadas a Secretaria de Assistência Social distribuiu às vítimas do desastre: 08 cestas básicas, sendo\nadquiridas para complementar o atendimento à todas as vítimas abrigadas nos abrigos, além do fornecimento de alimentação completa e\nprodutos de higiene para os desabrigados. Foram danificadas as seguintes estruturas: danos à estrada vicinal que liga Patrocínio do Muriaé\nàs comunidades do Miraval e Engenho de Serra; danos a estrada vicinal que liga Patrocínio do Muriaé às comunidades de Pouso Alegre,\nPerobas, Quissé, Jacarezinho e Anastácia; danos a estrada vicinal que liga a comunidade da Anastácia ás comunidades do Jacarezinho e\nCasa de Tábuas; danos a estrada vicinal que liga o município Barão do Monte Alto à comunidade Miraval; danos a estrada vicinal que liga a\nComunidade Valão à Comunidade Pouso Alegre; danos a estrada vicinal que liga Patrocínio do Muriaé à Comunidade das Três Barras; danos\na estrada vicinal que liga Anastácia às comunidades de Valão e Pouso Alegre; danos a estrada vicinal que liga Patrocínio do Muriaé à\nComunidade do Ivaí e danos a estrada vicinal que liga o Ivaí às Comunidades da Boa Esperança, Perobas e Anastácia. Foram verificados\ndanos no calçamento das ruas: Cristo Rei e Mario Daher. Também ocorreram várias quedas de árvores em diversos pontos do Município de\nPatrocínio do Muriaé. O Departamento de Engenharia da Prefeitura identificou cerca de 72 imóveis residenciais e 02 imóveis comerciais\ndanificados e ainda outros 36 imoveis atingidos, mas sem danificações. Foram ainda constatados também perdas e prejuízos na agricultura,\npecuária e piscicultura local devido às chuvas intensas e ao volume de água das inundações que ocorreram no Município causando\ninterdição de estradas vicinais de acesso devido queda de barreiras, danificação em pontes e inundações. A Secretária Municipal de Obras,\nInfraestrutura e Urbanismo encontra-se realizando limpeza das vias públicas. Tendo em vista a proporção de áreas afetadas, a Prefeitura\nnecessitou de contratar de maneira emergencial um caminhões pipa, uma retroescavadeira e um caminhão carroceria', '2026-02-11 10:26:40', '2026-02-23 15:30:49', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28823, 2490, 8, 322, NULL, '2026-02-11 10:31:44', '2026-02-11 10:31:44', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28824, 2490, 9, 322, 'AREA RURAL: COMUNIDADE DA PRATINHA, Sitio conhecido como "Sitio Gentil"(Local onde ocorreu o deslizamento de terra que atingiu a residencia).', '2026-02-11 10:31:45', '2026-02-11 11:53:04', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28825, 2490, 10, 322, 'O deslizamento de terra ocorrido no dia 10/02/2026, na Comunidade da Pratinha (Sítio Gentil), no município de Eugenópolis, teve como principal causa o acúmulo excessivo de chuvas nos dias anteriores ao evento, com registro de 102 mm nas últimas 96 horas e 35 mm nas últimas 24 horas. Esse elevado volume de precipitação aparentemente provocou a saturação do solo, aumentando seu peso e reduzindo sua resistência, especialmente por se tratar de uma área em encosta. A infiltração contínua da água comprometeu a estabilidade do terreno, favorecendo o deslocamento da massa de terra. Como efeito, ocorreu o rompimento do solo e o deslizamento de grande volume de material, acompanhado pela queda e arraste de árvores existentes na encosta, que aumentaram a força do impacto. A massa de terra e as árvores atingiram diretamente a residência localizada na área inferior, provocando sua destruição', '2026-02-11 10:31:45', '2026-02-11 11:53:04', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28826, 740, 8, 323, NULL, '2026-02-11 10:44:07', '2026-02-11 10:44:07', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28827, 740, 9, 323, 'Bairro Esplanada; Vila Aurora, Santa Efigênia', '2026-02-11 10:44:08', '2026-02-11 10:44:08', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28828, 740, 10, 323, 'Considerando que em  23/01/2026,  o sistema de drenagem, "Boca de Lobo", não suportou o volume excessivos das chuvas contínuas e intensas,   vindo a ocorre uma queda de parte do barranco. Não ouve colapso da rua ou do passeio. Contudo observamos sinais de movimentação como trinco no passeio e no asfalto. Como medida de prevenção isolamos e sinalizamos parte do passeio e do asfalto e comunicamos o setor responsável, para a eliminação do risco. \nNesta data, 10/02/2026, por volta de 10h, novamente após uma chuva intensa, o sistema de frenagem não suportou, houve um  deslizamento e colapsou a estrutura de drenagem, conhecida por ¿boca de lobo¿, uma parte do passeio e comprometeu uma parte da pista.', '2026-02-11 10:44:08', '2026-02-11 10:44:08', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28829, 740, 2, 323, 'Pilares de concreto para a contenção do barranco; \nSistema de drenagem, boca de lobo, caixa de passagem e manias de concreto; \nCalçada aproximadamente vinte metros\nasfalto aproximadamente vinte metros', '2026-02-11 10:44:08', '2026-02-11 10:44:08', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28830, 3240, 8, 324, NULL, '2026-02-11 10:50:25', '2026-02-11 10:50:25', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28831, 3240, 9, 324, 'O município conta com sistema de monitoramento hidrológico e de alagamentos em tempo real, composto por estações pluviométricas, réguas de nível em cursos d¿água e pontos de monitoramento instalados em vias críticas, cujos dados são acompanhados continuamente pela Defesa Civil.\n\nNo período de 06 a 09/02/2026, foram registrados os seguintes acumulados médios pluviométricos no município:\n\n06/02: 26,0 mm\n07/02: 13,7 mm\n08/02: 12,4 mm\n09/02: 53,3 mm\n\nOs dados evidenciam precipitação persistente ao longo dos dias, com aumento expressivo do volume no dia 09/02, mantendo o solo saturado e contribuindo diretamente para a ocorrência generalizada de alagamentos, extravasamento de cursos d¿água, quedas de árvores, deslizamentos e obstruções de vias urbanas e rurais.', '2026-02-11 10:50:26', '2026-02-11 10:50:26', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28832, 3240, 10, 324, 'A continuidade das chuvas manteve o solo permanentemente encharcado, gerando saturação progressiva em todo o território do município. Essa condição resultou em resposta hidrológica imediata dos ribeirões Anhumas e Piranguçu, com registros de extravasamento e pontos de alagamento em todas as vias dotadas de estações de monitoramento da Defesa Civil.\n\nNo dia 09/02/2026, diversas estações hidrológicas e pontos de monitoramento de alagamento atingiram níveis de atenção, com registros de 1,73 m na Estação Borges às 18h44, 1,65 m na UNIFEI e lâminas d¿água superiores a 0,80 m em vias monitoradas, confirmando a ocorrência generalizada de inundação nas áreas acompanhadas pela Defesa Civil.\n\nA saturação do solo provocou perda de coesão superficial do terreno, desencadeando quedas de árvores, quedas de muros, processos erosivos, deslizamentos pontuais e sucessivas obstruções de vias urbanas e rurais, incluindo interdições totais e parciais da BR-459 e estradas vicinais.\n\nNesse contexto, foi constatado ainda dano estrutural no encontro da ponte sobre o Rio Sapucaí, localizada na Rua Andardino de Souza, bairro Santos Dumont, onde a ação erosiva da elevação da vazão do rio provocou solapamento da cabeceira da ponte, com exposição do maciço de solo, formação de vazio sob o pavimento e risco iminente de colapso do bordo da via, exigindo interdição parcial emergencial do trecho.\n\nO evento teve duração contínua de aproximadamente quatro dias, com necessidade de atuação ininterrupta das equipes da Defesa Civil e Secretaria de Obras, inclusive durante a madrugada, para desobstrução de vias, limpeza de sedimentos e restabelecimento da segurança e da mobilidade da população.\n\nO desastre não se caracterizou por uma precipitação extrema isolada, mas sim por acúmulo pluviométrico progressivo associado à persistência das chuvas, condição que potencializou significativamente os efeitos hidrológicos, geotécnicos e viários observados no município. O acumulado de chuva nesses quatro dias foi de 101,3 mm.\n\nDestaca-se que, somente no dia 09/02/2026, foram registrados picos de 82,90 mm na Estação Borges, 75,80 mm na Torre de TV e 65,10 mm na UNIFEI, evidenciando a magnitude do volume precipitado em curto intervalo de tempo.\n\nDurante o evento, o sistema de monitoramento emitiu 12 alertas automáticos à Defesa Civil, sendo 6 de observação e 6 de atenção, em função dos níveis hidrológicos atingidos.\n\nObservou-se ainda elevação significativa do nível do Rio Sapucaí, com registros de 3,40 m na estação FEPI e 2,42 m na Ponte do Batalhão, demonstrando resposta hidrológica em toda a bacia que corta o município.', '2026-02-11 10:50:26', '2026-02-11 10:50:26', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28833, 3240, 1, 324, 'Durante o período do evento, apesar da magnitude das ocorrências registradas em áreas urbanas e rurais, não houve registro de vítimas, feridos, enfermos, desabrigados, desalojados ou desaparecidos.\n\nAs situações atendidas estiveram relacionadas principalmente a obstruções de vias por quedas de árvores, quedas de muros, processos erosivos, deslizamentos pontuais, alagamentos e extravasamento de cursos d¿água, sem atingimento direto a edificações habitadas que demandasse retirada de moradores ou necessidade de abrigo público.\n\nA atuação preventiva e emergencial das equipes da Defesa Civil e Secretaria de Obras, com intervenções rápidas para desobstrução de vias e monitoramento das áreas críticas, contribuiu para que não houvesse danos humanos decorrentes do evento.', '2026-02-11 10:50:26', '2026-02-11 10:50:26', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28834, 3240, 2, 324, 'Foram registrados danos pontuais a duas unidades habitacionais localizadas na Rua Barão do Rio Branco, bairro Boa Vista, em decorrência direta dos efeitos do desastre.\n\nFoi constatado dano estrutural relevante no encontro da ponte sobre o Rio Sapucaí, localizada na Rua Andardino de Souza, bairro Santos Dumont, em decorrência direta da elevação da vazão do rio durante o evento chuvoso.\n\nA ação erosiva hídrica provocou solapamento da cabeceira da ponte, com remoção significativa do maciço de solo que promovia o confinamento lateral e o apoio da estrutura, resultando na exposição parcial da base estrutural e formação de vazio sob o pavimento.\n\nForam identificados indícios claros de instabilidade do aterro de transição entre a ponte e a via, como trinca longitudinal no bordo da pista e exposição de tubulação anteriormente envolvida pelo solo, caracterizando falha crítica no encontro ponte¿via.\n\nEmbora a superestrutura da ponte não apresente danos aparentes, o comprometimento do apoio da cabeceira gera risco iminente de colapso localizado da pista, especialmente sob tráfego de veículos pesados e novas elevações da vazão do rio.\n\nA situação demandou interdição parcial emergencial do trecho e caracteriza dano a obra de infraestrutura pública, necessitando de intervenção de engenharia para recomposição do maciço, proteção hidráulica da cabeceira e estabilização estrutural do encontro da ponte com a via.\n\nAs demais ocorrências estiveram relacionadas a obstruções de', '2026-02-11 10:50:26', '2026-02-11 10:50:26', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28835, 3240, 3, 324, 'O desastre provocou obstruções totais e parciais de vias urbanas, rurais e da BR-459 em diversos pontos do município, em decorrência de quedas de árvores, quedas de barreiras, processos erosivos e arraste de vegetação e detritos sobre a pista, comprometendo diretamente o serviço essencial de transportes.\n\nAlém disso, foi constatado dano estrutural no encontro da ponte sobre o Rio Sapucaí, localizada na Rua Andardino de Souza, bairro Santos Dumont, onde a ação erosiva da elevação da vazão do rio provocou solapamento da cabeceira da ponte, exigindo interdição parcial emergencial do trecho por risco de colapso do bordo da via.\n\nTambém foi necessária atuação do sistema de limpeza urbana, com emprego de maquinário pesado e caminhão pipa para remoção de lama, sedimentos e detritos carreados pelas enxurradas sobre as vias públicas e rurais.\n\nOs prejuízos econômicos públicos estão relacionados aos custos operacionais dessas ações emergenciais realizadas pela Defesa Civil e Secretaria de Obras para restabelecimento da trafegabilidade, segurança viária e condições adequadas de circulação da população.', '2026-02-11 10:50:26', '2026-02-11 10:50:26', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28836, 3240, 11, 324, 'O desastre provocou obstruções totais e parciais de vias urbanas, rurais e da BR-459 em diversos pontos do município, em decorrência de quedas de árvores, quedas de barreiras, processos erosivos e arraste de vegetação e detritos sobre a pista, comprometendo diretamente o serviço essencial de transportes.\n\nAlém disso, foi necessária atuação do sistema de limpeza urbana, com emprego de maquinário pesado e caminhão pipa para remoção de lama, sedimentos, vegetação e detritos carreados pelas enxurradas sobre as vias públicas e rurais.\n\nOs prejuízos econômicos públicos estão relacionados aos custos operacionais dessas ações emergenciais realizadas pela Defesa Civil e Secretaria de Obras para restabelecimento da trafegabilidade, segurança viária e condições adequadas de circulação da população', '2026-02-11 10:50:26', '2026-02-11 10:50:26', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28837, 3240, 12, 324, 'Apesar das obstruções temporárias de vias urbanas, rurais e da BR-459 em decorrência de quedas de árvores, processos erosivos e acúmulo de lama e detritos, não foram identificados prejuízos econômicos privados mensuráveis nos setores da agricultura, pecuária, indústria, comércio ou serviços.\n\nAs ocorrências tiveram caráter pontual e foram prontamente atendidas pelas equipes da Defesa Civil e Secretaria de Obras, com rápida desobstrução das vias e restabelecimento da trafegabilidade, não havendo registro de perdas materiais ou produtivas que justificassem contabilização de prejuízo econômico privado.', '2026-02-11 10:50:26', '2026-02-11 10:50:26', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28838, 3700, 8, 325, NULL, '2026-02-11 11:14:13', '2026-02-11 11:14:13', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28839, 3700, 9, 325, 'Rua Bernardo Passos na sede do município afetada com passeio desabando em uma residência\nRua João Eleutério na sede do município afetada com passeio desabando em uma residência\nRua Major Tavares na sede do município afetada com passeio desabando em uma residência\nComunidade de São Domingos de Neco Pinto Trecho de um morro cedendo\nComunidade São Domingos dos Boas com grande erosão causada pelas chuvas\nComunidade de Brejaúba Trecho da Estrada cedendo \nEscadão da Rua Major Tavares cedendo\nDistrito de Concórdia do Mucuri com trechos da estrada afetados pelas chuvas\n', '2026-02-11 11:21:04', '2026-02-11 11:21:04', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28840, 3700, 10, 325, 'Desde o início de janeiro, o município vem sendo castigado por fortes chuvas. O volume acumulado causou o desgaste severo das estradas vicinais, processos erosivos e desabamentos de vias na zona urbana.', '2026-02-11 11:21:04', '2026-02-11 11:21:04', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28841, 3700, 1, 325, 'Houve danos em ruas e em estradas vicinais de comunidade rurais do município, além de desabrigados da zona rural.\nTambém houve perda de plantio de trabalhadores da agricultura familiar.\nCerca de 7.000 pessoas foram afetadas', '2026-02-11 11:21:04', '2026-02-11 11:21:04', NULL);
