	(28887, 7160, 10, 332, 'TODO TERRITORIO URBANO E RURAL DO MUNICÍPIO DE VIRGEM DA LAPA/MG.', '2026-02-13 10:55:26', '2026-02-13 10:55:26', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28888, 7160, 1, 332, 'estima-se que 1548 pessoas foram afetadas, assim sendo discriminadas: Cerca de 1188 pessoas com o acesso parcialmente interditado em estradas vicinais e, 360 pessoas em condições de outros afetados, pois os acessos a cidade de Virgem da Lapa/MG foram obstruídos por alagamentos e erosões de algumas vias.', '2026-02-13 10:55:26', '2026-02-13 10:55:26', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28889, 7160, 2, 332, 'Danos significativos abrangendo diversos setores, afetando a infraestrutura pública e privada, incluindo, vias urbanas, estradas vicinais, pontes, alagamento em diversos pontos, danos materiais assim descritas: Erosão na Rua São Paulo e Rua Belo Horizonte (Bairro Boa Vista); Colapso da estrutura de contenção na estrada vicinal da comunidade Paredão; Colapso da via na Travessa Uruguai (Bairro Ponte); Destruição de tubulações da rede de esgoto que passa pelo Córrego São Domingos (Bairro Ponte); Danos no tabuleiro de madeira da Ponte Colatino na comunidade do Barra do Vacaria - comércios locais inundados além de varias vias urbanas e rurais tendo seu acesso obstruído.', '2026-02-13 10:55:26', '2026-02-13 10:55:26', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28890, 7160, 11, 332, 'ABASTECIMENTO DOS MAQUINÁRIOS PARA LIMPEZA DAS RUAS E DESOBSTRUÇÃO DE ESTRADAS VICINAIS.', '2026-02-13 10:55:27', '2026-02-13 10:55:27', NULL);
