INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28993, 420, 8, 355, NULL, '2026-02-24 13:01:31', '2026-02-24 13:01:31', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28994, 420, 9, 355, 'No perímetro urbano foram atendidos varias chamadas, sendo que as ocorrências mais significativas na sexta-feira, em recorrência das chuvas. Foram referente a patologias em residências e quedas de árvores. Foram registradas quatro ocorrências em residências, sendo que uma residência no Centro da cidade foi interditada provisoriamente ficando quatro pessoas desalojadas  temporariamente, 02 adultos e 02 crianças, ambos foram casa de amigos. Patologias em duas casas no bairro São José afetando 03 pessoas. Atendimento em um murro som infiltração afetando 04 pessoas de uma casa no bairro São Pedro.\n O vários atendimentos como queda de árvore e inclinação de outra árvore sobre fiação da CEMIG sobre uma residência foram registradas e atendidas.\nTambém ocorreu  deformação de pavimentação asfáltico, com formação de buracos em algumas vias.\nA COPASA teve seu atendimento parcialmente comprometido provisoriamente por danos provenientes de inundação nas áreas dos motores das bombas de recalque.\nDanos na zona rural;  com as precipitações mais elevadas associadas ao solo encharcado as estradas rurais foram severamente danificadas com erosões. O grande volume d`água provocou enchente e alagamento em rios e córregos da zona rural,  principalmente  na região da Vargem dos Britos, Barreiro, carrego das almas. Também danificou varias cercas de propriedades rurais.', '2026-02-24 13:01:31', '2026-02-24 13:01:31', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28995, 420, 10, 355, 'Relatório Chuvas Intensas,\nNo dia 23 de janeiro ¿sexta-feira¿,  deste ano de 2026, no município de Arcos ocorreu chuvas intensas com precipitação 134,3mm durante a madrugada e no decorrer da tarde.   Conforme as previsões meteorológicas já indicavam fortes chuvas, esta defesa Civil Municipal, entrou em situação de alerta, e tomou as medidas de mitigação e preparação três dias antes. Mas como havia previsão para o dia 23 apenas 30 mm e como choveu 134,3mm ocorreram diversas patologias com danos em diversos pontos do perímetro urbano e rural deste município.\nNo perímetro urbano foram atendidos varias chamadas, sendo que as ocorrências mais significativas na sexta-feira, em recorrência das chuvas. Foram referente a patologias em residências e quedas de árvores. Foram registradas quatro ocorrências em residências, sendo que uma residência no Centro da cidade foi interditada provisoriamente ficando quatro pessoas desalojadas  temporariamente, 02 adultos e 02 crianças, ambos foram casa de amigos. A Secretaria Municipal de Obras fizeram a adequação necessária para a contenção dos riscos, a Secretaria Municipal de Assistência Social foi acionada e prestou assistência a família.\nO vários atendimentos como queda de árvore e inclinação de outra árvore sobre fiação da CEMIG sobre uma residência foram registradas e atendidas.\nTambém ocorreu  deformação de pavimentação asfáltico, com formação de buracos em algumas vias.\nA COPASA teve seu atendimento parcialmente comprometido provisoriamente por danos provenientes de inundação nas áreas dos motores das bombas de recalque.\nDanos na zona rural;  com as precipitações mais elevadas associadas ao solo encharcado as estradas rurais foram severamente danificadas com erosões. O grande volume d`água provocou enchente e alagamento em rios e córregos da zona rural,  principalmente  na região da Vargem dos Britos, Barreiro, carrego das almas. Também danificou varias cercas de propriedades rurais. daniicou a cabeceira da Ponte do Barreiro e dois mataburros na zona rural.', '2026-02-24 13:01:31', '2026-02-24 13:01:31', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28996, 420, 1, 355, 'No Centro da Cidade 04 qpessoas desalojadas  temporariamente, 02 casas no bairro São José Afetando 03 Pessoas, e No bairro São Pedro afetando 04 pessoas.', '2026-02-24 13:01:31', '2026-02-24 13:01:31', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(28998, 6990, 1, 357, NULL, '2026-02-24 10:46:39', '2026-02-24 10:46:39', NULL);
