INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29053, 4340, 8, 368, NULL, '2026-02-24 20:01:22', '2026-02-24 20:01:22', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29054, 4340, 10, 368, 'Em 05 de fevereiro de 2026, em consonância com as previsões meteorológicas e alertas preventivos previamente emitidos, por volta das 18h15min, o município de Monte Sião/MG foi atingido por chuvas intensas, resultantes de elevados volumes de precipitação pluviométrica concentrada. O evento foi agravado pelo fenômeno hidrológico conhecido como ¿cabeça d¿água¿, originado nas áreas de zona rural a montante, ocasionando a rápida elevação dos níveis do Córrego do Grotão e do Rio das Antas. Como consequência, verificaram-se inundações classificadas como COBRADE 1.2.1.0.0, atingindo diversos bairros da zona rural e Urbano do município, provocando transbordamentos, alagamentos extensos e impactos diretos à população e à infraestrutura local. ', '2026-02-24 20:01:22', '2026-02-24 20:01:22', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29055, 4340, 1, 368, 'Em decorrência do comprometimento, obstrução, interdição de vias e pontes públicas rurais e urbanas com destaque para as estradas rurais que interligam o município aos bairros Batinga, Sertãozinho, Três Cruzes, Guardinha de Baixo, Coqueiral e Guardinha de Cima e na Zona Urbana no Distrito da Mococa das Gerais e no Bairro Jardim América a Rua Peru, s/n erosao classificada como RAVINA vem ocasionando serios riscos a risidencias e ruas proximas. Em face da relevância e da magnitude dos impactos, equipes da Prefeitura Municipal de Monte Sião permaneceram mobilizadas de forma contínua nas Ações de Resposta.\n', '2026-02-24 20:01:22', '2026-02-24 20:01:22', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29056, 4340, 2, 368, 'Em decorrência do evento adverso, foram registrados danos materiais de natureza pública, caracterizados por avarias generalizadas na malha viária rural do município, decorrentes de deslizamentos de terra e carreamento de solo e vegetação em estradas vicinais. Constatam-se ainda danos estruturais em pontes, bem como obstruções em estradas rurais, ocasionando interdições totais e parciais de vias, além de danos em dispositivos de drenagem, especialmente bueiros, e em pavimentações e calçamentos, comprometendo a mobilidade e a segurança viária. Na zona urbana, especificamente no Bairro Jardim América, verificou-se a ocorrência de processo erosivo de grande porte, classificado como ravina, em evolução, oferecendo risco iminente a residências e às vias públicas localizadas no entorno da área afetada, com potencial de agravamento em caso de continuidade das precipitações pluviométricas. Em face da relevância do evento, equipes da Prefeitura Municipal permanecem mobilizadas nas ações de resposta, realizando levantamentos técnicos, vistorias em campo e coleta de informações, com vistas à avaliação dos danos, mitigação dos riscos e planejamento das intervenções necessárias.', '2026-02-24 20:01:22', '2026-02-24 20:01:22', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29057, 4340, 11, 368, 'A Prefeitura disponibilizou funcionarios publicos da secretaria de obras, secretaria de agricultura e departamento de serviços urbanos com pagamentos de horas extras nos diversos dias de serviço devido a manutenção de estradas vicinais, desobstrução e limpeza da via publica devido ao deslizamento de encostas, lama ocasionado por inundação, alem da retirada de agua de uma erosao (ravina) em bairro da Zona urbana de Monte Sião. DISTRUIBUIÇÃO DE COMBUSTIVEIS foi utilizado no abastecimento de maquinas, caminhoes da frota municipal e caminhoes utilizados na limpeza e desobtrução das vias.', '2026-02-24 20:01:22', '2026-02-24 20:01:22', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29058, 5590, 8, 370, NULL, '2026-02-24 20:13:31', '2026-02-24 20:13:31', NULL);
