INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29218, 2660, 9, 408, 'As chuvas acumuladas nos últimos dias somando com as chuvas intensas madrugada do 28 de fevereiro fez estragos em todas as comunidades rurais do Município principalmente comunidade de Cipó região de santo Antônio e Nova esperança', '2026-03-02 17:13:14', '2026-03-02 17:13:14', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29219, 2660, 10, 408, 'As chuvas acumuladas nos últimos dias somando com as chuvas intensas do dia 27 e  madrugada do 28 de fevereiro trouxe prejuízos e danos as comunidades rurais causando danos e prejuízos desalojando e ilhando varias famílias. ', '2026-03-02 17:13:14', '2026-03-02 17:13:14', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29220, 3580, 8, 410, NULL, '2026-03-02 17:23:06', '2026-03-02 17:23:06', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29221, 3580, 9, 410, 'Foram afetadas as seguintes áreas rurais: comunidade Campo Novo, Pedra Grande, Retiro Krant ,Córrego do São Pedro, Araçatuba, Palmaço,\nOratório; Craúno, Mumbuca, Brejão, Ilha do Pão, Maranhão, Assentamento Franco Duarte, Santo Antônio Rural, Transval, Distrito do São\nPedro do Jequitinhonha, Guaranilândia, Estiva, Cajú. Na área urbana os bairros: Centro, Nova Esperança I e II, Santo Antônio e Alvorada.', '2026-03-02 17:23:07', '2026-03-02 17:23:07', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29222, 3580, 10, 410, 'Em decorrência das intensas chuvas registradas entre os meses de janeiro a março de 2026, verificou-se um volume acumulado de 303,2 mm, com distribuição bastante irregular ao longo do período. Destaca-se que, entre os dias 28 de fevereiro a 2 de março houve precipitação excessiva, somando 74.3 mm, o que contribuiu para um total de 209,3 mm no mês de fevereiro e março.\nEsse cenário resultou na deterioração de vias rurais comprometendo o escoamento da produção local. Além disso, diversas vias urbanas ficaram alagadas, residências foram destruídas e rodovias sofreram danos significativos, dificultando o acesso à cidade. Também foram registrados prejuízos materiais e impactos ambientais relevantes.\nA situação foi agravada pelo aumento do volume de água do Rio Jequitinhonha, proveniente de municípios situados a montante, o que provocou o transbordamento de suas margens.', '2026-03-02 17:23:07', '2026-03-02 17:23:07', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29223, 3580, 1, 410, 'Considerando o efeito do período chuvoso, 1965 pessoas foram afetadas, 65 ficaram desalojados devido ao grande volume de precipitação, perderam seus meios de sobrevivência, afetando o emocional e o bem estar familiar.', '2026-03-02 17:23:07', '2026-03-02 17:23:07', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29224, 3580, 2, 410, 'Foram danificadas parcialmente cerca de 13 unidades habitacionais e 2 completamente destruída. Cerca de 12 estradas foram degradadas nas comunidades: Mumbuca, Brejão, Transval, Campo Novo, Ilha do Pão, Maranhão, Araçatuba, Porto Alegre, Assentamento Franco Duarte, Distrito do Caju, Cachoeira, Boa Vista e Krant. 2 bueiros danificados na comunidade Brejão, 2 na Araçatuba. Na zona Urbana dois bueiros danificados na Rua Cipestre e dois na Avenida São Cristóvão.', '2026-03-02 17:23:07', '2026-03-02 17:23:07', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29225, 4390, 8, 411, NULL, '2026-03-02 17:35:50', '2026-03-02 17:35:50', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29226, 4390, 9, 411, 'Após ocorrência de chuvas volumosas e intensas registradas nas cabeceiras dos rios Muriaé e Fubá, ambos no município de Miraí, elevaram o nível do rio Muriaé no perímetro urbano do município causando extrapolamento de calha nos bairros: SANTANA, JOSÉ CIRILO, NAPOLEÃO, DORNELAS, PRAINHA E BARRA. ', '2026-03-02 17:35:51', '2026-03-02 17:35:51', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29227, 4390, 10, 411, 'Devido formação de áreas de instabilidade na região Sudeste do país, o município de Muriaé no dia vinte e seis (26) de fevereiro, às 16h, recebeu grande volume de chuva que foi acumulando até a noite do dia vinte e sete (27) com valores superiores aos 85 mm (FONTE: CEMADEN). Por consequência dessa chuva vários pontos de alagamento atingiram a área central do município, como também, alguns bairros e a BR-116 somados aos pontos de deslziamentos de encostas em áreas públicas e paticulares.\nComo essa instabilidade atingiu toda região, incluindo o município de Miraí, grande volume de precipitação foram registradas nas cabeceiras dos rio Muriaé e Fubá direcionando toda água ao município de Muriaé (jusante à Miraí) causando extrapolamento da calha do rio Muriaé em regiões ribeirinhas da cidade.', '2026-03-02 17:35:51', '2026-03-02 17:35:51', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29228, 4390, 1, 411, NULL, '2026-03-02 17:35:51', '2026-03-02 17:35:51', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29229, 4390, 2, 411, 'Após ocorrência de chuva forte e volumosa na noite do dia 26/02 o município registrou diversos pontos de alagamento, inundação em regiões ribeirinhas e vários pontos de deslizamentos de encosta. \nEstima-se que, devido a cheia do rio Muriaé 350 unidades habitacionais (com ou sem morador) tiveram danificações na pintura e portas de madeira, após entrada da água no interior dos imóveis. O custo estimado por unidade habitacional, segundo relatório da Secretaria Municipal de Obras Públicas e Urbanismo, é de R$ 3.500,00 com valor total de R$ 1.225.000,00.\nO município apresentou danos em 1 instalações pública de ensino após direcionamento de água da chuva ao terreno da Escola Estadual Engenheiro Orlando Flores causando queda de um muro com consequente isolamento da área afetada. Sem estimativa de preço até o momento.  ', '2026-03-02 17:35:51', '2026-03-02 17:35:51', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29230, 4390, 11, 411, 'Após evento adverso foram registrados pontos para limpeza das vias em áreas inundadas como retirada de material perdido depositado nas vias para recolhimento. A limpeza das ruas ocorrem em 3 etapas: remoção de árvores e entulhos, retirada de barro e desobstrução de bocas de lobo e, para finalizar, limpeza com água potável e higienização das vias. Estima-se que o valor do prejuízo público para execução dessas ações foi de R$ 130.000,00 (valor baseado nos registros históricos apresentados pelo DEMSUR e o histórico dos eventos adversos na cidade).', '2026-03-02 17:35:51', '2026-03-02 17:35:51', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29231, 5810, 8, 413, NULL, '2026-03-03 12:44:47', '2026-03-03 12:44:47', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29232, 5810, 9, 413, 'ZONA URBANA: PLANALTO E BELA VISTA, VISTA LINDA\n\nZONA RURAL: comunidade Fró, Pimenteira, Palmeiras, Enchadão, Córrego Seco, Serrinha, Piaui, Areia Branca', '2026-03-03 12:44:47', '2026-03-03 12:44:47', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29233, 5810, 10, 413, 'Que as fortes chuvas intensas corridas a a partir do dia 28 de fevereiro, com um volume aproximado de 360mm, elevaram o nível dos rios que cortam o município de Santa Maria do Salto e culminaram no rompimento de barragens e movimentação de massa; e em  decorrência do evento, pessoas ficaram desabrigadas, desalojadas, residências, pontes e cabeceiras danificadas e destruídas, estradas vicinais, bueiros foram danificados, gerando assim prejuízos econômicos públicos e sociais ao município.', '2026-03-03 12:44:47', '2026-03-03 12:44:47', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29234, 5810, 1, 413, '30 (trinta) pessoas ficaram desabrigadas e foram encaminhadas às escolas municipais, onde estão sendo acompanhadas pela Assistência Social do Município.\n\n20 (vinte) pessoas ficaram desalojadas, deslocando-se para a casa de parentes e amigos. MUITAS FAMÍLIAS PERDERAM MÓVEIS, ELETRODOMÉSTICOS, UTENSÍLIOS DE COZINHA, DOCUMENTOS, \n\nDiversas pessoas ficaram impossibilitadas de trafegar em razão dos danos nas pontes e estradas do Município.\n\nAlém disso, vários alunos deixaram de frequentar as escolas devido às condições precárias das estradas', '2026-03-03 12:44:47', '2026-03-03 12:44:47', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29235, 5810, 2, 413, '04 residencias danificadas.\n02 pontes , com 4 cabeceiras danificadas. Comunidade Areia Branca que liga a sede do município ao Distrito da Talisma ;\n\n10 bueiros destruídos nas: comunidade Fró, Pimenteira, Palmeiras, Enchadão, Córrego Seco, Serrinha, Piaui, Areia Branca\n\n12 estradas vicinais , comunidade Fró, Pimenteira, Palmeiras, Enchadão, Córrego Seco, Serrinha, Piaui, Areia Branca\n', '2026-03-03 12:44:47', '2026-03-03 12:44:47', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29236, 5810, 11, 413, 'DEVIDO OS EFEITOS CAUSADOS PELAS CHUVAS, O MUNICÍPIO TEVE QUE FAZER LOCAÇÃO DE VEÍCULOS PARTICULARES DE OUTRAS CIDADES, FAZENDO BALDEAÇÃO PARA TRANSPORTAR PACIENTES USUÁRIOS PARA OUTROS CENTROS DE SAÚDES, DEVIDO A INTERDIÇÃO INTERDIÇÃO DAS ESTRADAS VICINAIS. CONSIDERANDO OS EFEITOS CAUSADO PELAS FORTES CHUVAS DOS ÚLTIMOS DIAS, EM SE TRATANDO DE SISTEMA DE LIMPEZA URBANA E DE RECOLHIMENTO E DESTINAÇÃO DO LIXO, O MUNICÍPIO FEZ LOCAÇÃO DE PARTICULARES, COMO CAMINHÃO BASCULANTE, RETROESCAVADEIRA E ETC.', '2026-03-03 12:44:47', '2026-03-03 12:44:47', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29237, 5810, 12, 413, 'Agricultura: PERDAS milho, mandioca, café, banana, feijão e horta gramjeiro.\n\nPecuária: não sendo possível o escoamento de leite devido às condições das estradas.', '2026-03-03 12:44:47', '2026-03-03 12:44:47', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29238, 2880, 8, 414, NULL, '2026-03-03 13:01:54', '2026-03-03 13:01:54', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29239, 2880, 9, 414, 'Zona urabana - Centro, Padre Baião\nzona rural  as comunidades do Pombal, Vargem Alegre, Serra da Onça e Comunidade do Guido e Capoeirinha', '2026-03-03 13:01:54', '2026-03-03 13:01:54', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29240, 2880, 10, 414, 'Durante a noite do dia 23/02/2026 até a madrugada do dia 28/02/2026 o município passou por um período de chuva que chegou a contabilizar 140mm em 96 horas, tendo também recebido uma grande quantidade de agua do Rio Uba, dos afluentes do Rio Xopoto como por exemplo Visconde do Rio Branco e Guiricema, e uma grande quantidade de chuva oriundo das cabeceiras da cidade. Como o volume de agua foi enorme vindo da cidade de uba, o encontro do Rio Xopoto com o Rio Uba causou transbordo que afetou varias casas, e com a grande quantidade de chuva que caiu no municipio, tivemos diversos danos geologicos, onde possuimos duas areas em que temos moradores e necessitamos fazer encostas urgente, temos a sede da assistencia social que necessita realizar obra de contenção pois cedeu-se a parte de tras, temos pontes de acesso danificadas, e temos vias de acesso danificadas também que necessitam a construção de muros para contenção e reestabelecimento.', '2026-03-03 13:01:54', '2026-03-03 13:01:54', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29241, 2880, 1, 414, '104 pessoas ficaram desalojadas, indo para casa de parentes e amigos. Tivemos a maior parte dos afetados entre as intermediações da\ncomunidade da Vargem Alegre até a comunidade do Guido por problemas de transbordo, impedindo a passagem das pessoas e no centro\ntivemos os afetados por problemas geológicos, várias quedas de encosta. Tivemos o serviço de ensino prejudicado por conta das cheias do\nRio Uba e Rio Xopoto, mas que não gerará prejuízos econômicos, pois as aulas serão repostas em dias a serem definidos pelo calendário\nescolar', '2026-03-03 13:01:54', '2026-03-03 14:33:06', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29242, 2880, 2, 414, '104 casas ficaram alagadas 01 secretaria municipal de assistência social, o muro de contenção totalmente destruído. 02 pontes tiveram as\nsuas cabeceiras danificadas - uma na comunidade do Guido e outra na comunidade do Sossego . 06 encostas danificadas. 01 rede pluvial da\nrua 7 de setembro danificada.', '2026-03-03 13:01:54', '2026-03-03 14:33:06', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29243, 2880, 11, 414, 'Abastecimento do maquinário para limpeza de ruas e estradas', '2026-03-03 13:01:54', '2026-03-03 14:33:06', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29244, 2880, 12, 414, 'O prejuizo na Agricultura se deu pelas cheias das aguas, que ocasionou a perca de materiais que estavam plantados onde o rio veio transbordar. O prejuizo no comercio se faz por termos o posto de gasolina denominado como Posto Guidoval tendo sua parte de baixo atingida pela cheia do Rio Xopoto, ocasionando nos dias de cheia a não comercialização dos produtos vendidos no local.', '2026-03-03 13:01:54', '2026-03-03 13:01:54', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29245, 1010, 8, 415, NULL, '2026-03-03 13:06:34', '2026-03-03 13:06:34', NULL);
