	(29246, 1010, 9, 415, 'A CIDADE DE CAIANA, JUNTAMENTE COM O DISTRITO DE DORES DE MINAS E AS COMUNIDADES RURAIS', '2026-03-03 13:06:34', '2026-03-03 13:06:34', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29247, 1010, 10, 415, 'GRANDE VOLUME DE CHUVA RESGISTRADO CERCA DE 80 MM EM 6 HORAS, OCASIONANDO GRANDE VOLUME DE ÁGUA E DESTRUINDO PONTES, CAUSANDO DESLIZAMENTO DE TERRAS E ALAGAMENTOS E VIAS.', '2026-03-03 13:06:34', '2026-03-03 13:06:34', NULL);
