	(29248, 1010, 1, 415, 'COM GRANDE VOLUME DE ÁGUA ALGUMAS MORADIAS FORAM AFETADAS DEIXANDO CERCA DE 150 PESSOAS DESALOJADAS, ENTRANDO BARRO EM SUAS MORADIAS E DANIFICANDO MOVEIS, ELETRODOMESTICOS, ENTRE OUTROS.', '2026-03-03 13:06:34', '2026-03-03 13:06:34', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29249, 1010, 2, 415, '6 PONTES NA ÁREA RURAL DO MUNCIPIO FORAM DESTRUIDAS, OBSTRUINDO PASSAGEM DE MUITOS MORADORES QUE PRECISAM DA VIA APARA ACEISSO A ESCOLA,  UNIDADES BASICAS DE SAUDE TAMBÉM PARA ESCOAMENTO DA PRODUÇÃO.', '2026-03-03 13:06:34', '2026-03-03 13:06:34', NULL);
