	(29594, 3730, 9, 427, 'TODAS AS COMUNIDADES RURAIS DO MUNICÍPIO FORAM AFETADAS. Zona urbano- centro e cidade nova.', '2026-03-17 11:28:39', '2026-03-17 11:28:39', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29595, 3730, 10, 427, 'nNO DIA 28/02/2026 O MUNICIPIO FOI ACOMETIDO DE FORTES CGUVAS, ONDE VARIAS PESSOAS FICARAM ISOLADAS DEVIDO A CHEIA\nDOS RIOS , JEQUITAÍ, E SÃO FRANCISCO. RANCHOS FORAM ALAGADOS DEVIDO AS CHEIAS. OS RIOS E CÓRREGOS VÊM ELEVANDO OS\nNÍVEIS DOS RIO SÃO FRANCISCO, RIO JEQUITÍ, CORREGO DO BARRO E RIACHO FUNDO E BARREIROS QUE ACABAM TRANSBORDANDO\nCAUSANDO BLOQUEIO DE ESTRADAS ALAGANDO AS LAVOURAS E PASTAGENS, ISOLANDO COMUNIDADES, QUEDA DE BARREIRAS,\nVOÇOROCAS E ESTRAGOS NAS ESTRADAS VICINAIS DO MUNICÍPIOS PRINCIPALMENTE NA QUE LIGA LAGOA DOS PATOS A PIRAPORA E A\nBR 365 POR ONDE ESCOA A MAIOR PARTE DA PRODUÇÃO DO MUNICÍPIO. CERCA DE 1500 PESSOAS FORAM AFETADAS PELAS CHUVAS\nINTENSAS E INUNDAÇÕES EM NOSSO MUNICÍPIO.', '2026-03-17 11:28:39', '2026-03-17 11:28:39', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29596, 3730, 1, 427, 'ALGUMAS RESIDÊNCIAS FORAM AFETADAS TENDO MUITOS PREJUÍZ0S PARA AS FAMÍLIA AS PESSOAS AFETADAS SÃO PRINCIPALMENTE\nOS MORADORES DA ZONA RURAL DO MUNICÍPIO ALGUNS ESTÃO ISOLADOS DEVIDOS AOS ALAGAMENTOS, DESLIZAMENTOS E\nDEGRADAÇÃO DAS ESTRADAS. AGRICULTORES COM SUAS LAVOURAS DE FEIJÃO, MILHO, SORGO E CANA GERANDO UM PREJUÍZO . JÁ\nNA pecuária PRODUÇÃO DE LEITE, NA PRODUÇÃO DE GADO DE CORTE O PREJUÍZO. OS PESCADORES DAS ILHAS DO SÃO FRANCISCO E\nJEQUITAÍ TIVERAM QUE DEIXAR AS ILHAS POIS ESTÃO IMUNDADAS. A BARRAGEM DA COMUNIDADE TESOURA TRANSBORDOU\nDEIXANDO A COMUNIDADE SEM ACESSO A SEDE DO MUNICÍPIO, NA MESMA COMUNIDADE O CÓRREGO DO TOSTADINHO ENCHEU\nARRANCANDO A REDE DE AGUA QUE LEVA AGUA PARA 08 FAMÍLIAS QUE RESIDEM PRÓXIMAS AO CÓRREGO, NA COMUNIDADE RABECA\nO RIO JEQUITAÍ ENCHEU TRANSBORDANDO DEIXANDO ALGUMAS FAMÍLIAS DE RIBEIRINHOS ILHADAS. OS PESCADORES DAS ILHAS DO SÃO FRANCISCO E JEQUITAÍ TIVERAM QUE DEIXAR AS ILHAS POIS ESTÃO IMUNDADAS.\n', '2026-03-17 11:28:39', '2026-03-17 11:28:39', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29597, 3730, 2, 427, 'ESTRADAS DANIFICADAS NA COMUNIDADE: BOA VISTA, CAIÇARA, COCAL , FUMAÇA, BOQUEIRÃO, JACARÉ, RIACHO FUNDO, TESOURA ,RABECA, GOIABEIRA VELHA, PIDAIBINHA, BONSUCESSO, SUMIDOURO.\n', '2026-03-17 11:28:39', '2026-03-17 11:28:39', NULL);
