INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29601, 5670, 9, 460, 'Todo o município de Sabará foi afetado.', '2026-03-18 19:27:57', '2026-03-18 19:27:57', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29602, 5670, 10, 460, 'O desastre registrado no Município de Sabará ocorreu no dia 09 de março de 2026, por volta das 14h04, tendo o fenômeno se repetido de forma mais intensa no dia 11 de março de 2026, ambos provocados por evento hidrometeorológico caracterizado por fortes temporais, com ocorrência de chuvas intensas concentradas em curto período de tempo, acompanhadas de rajadas de vento e elevada precipitação pluviométrica. \nO fenômeno resultou em grande volume de água escoando rapidamente pelas vias urbanas, ocasionando alagamentos, enxurradas, elevação do nível de córregos e sobrecarga dos sistemas de drenagem, em diferentes pontos do município, além da queda de postes da rede elétrica. \nNo dia 11 de março de 2026, foi registrado acumulado pluviométrico aproximado de 80 milímetros, volume suficiente para provocar significativa sobrecarga da rede de drenagem urbana, transbordamentos pontuais de cursos d¿água e acúmulo de água em áreas mais baixas da cidade.\nA intensidade das chuvas contribuiu ainda para o carreamento de sedimentos, lama e resíduos, comprometendo a mobilidade urbana e causando transtornos relevantes à população.\nEm decorrência da magnitude do evento adverso, diversas áreas do território municipal foram atingidas por enxurradas e alagamentos, afetando residências, estabelecimentos comerciais e vias de circulação.\nO grande volume de água precipitado em curto período provocou danos materiais, interrupções em serviços essenciais e demandou atendimento emergencial por parte da Defesa Civil Municipal.\nEm decorrência dos fatos, registra-se a ocorrência de uma pessoa que veio a obito, além de pessoas desalojadas e desabrigadas, a população foi diretamente afetada, circunstâncias que exigiram a mobilização das equipes de resposta do município.', '2026-03-18 19:27:57', '2026-03-18 19:27:57', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29603, 5670, 1, 460, '01 óbito confirmado.\n06 desabrigados que se abrigaram na casa de parentes e amigos.\n149 Pessoas ficaram enfermas e foram encaminhadas as UPAS e/ou UBS.\n138 Pessoas ficaram desalojadas e se abrigaram em casas de parentes e amigos.\nOs danos humanos registrados no município de Sabará/MG estão diretamente relacionados ao evento hidrometeorológico ocorrido em 09 e 11 de março de 2026, caracterizado por chuvas intensas concentradas em curto período de tempo, ocasionando enxurradas, alagamentos, deslizamentos de terra e sobrecarga do sistema de drenagem urbana em diversas localidades do município.\nRegistra-se ainda um total de 3.197 pessoas classificadas como outros afetados, abrangendo moradores atingidos por alagamentos, perdas de bens móveis, interrupção de serviços essenciais, comprometimento de acessos viários e prejuízos diversos decorrentes das enxurradas e da sobrecarga do sistema de drenagem.', '2026-03-18 19:27:57', '2026-03-18 19:27:57', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29604, 5670, 2, 460, NULL, '2026-03-18 19:27:57', '2026-03-18 19:27:57', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29605, 5670, 11, 460, 'Abastecimento de todo maquinário, caminhão, carros de todas as secretarias que firam afetadas pelo desastre , para limpeza, de ruas, vias, transporte das famílias afetadas, retirada de entulhos lixo para levar aos locais destinados. ', '2026-03-18 19:27:58', '2026-03-18 19:27:58', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29606, 5670, 12, 460, 'Durante o periodo chuvoso, o comércio (mercados, lanchonetes, bares, restaurantes, padarias, casa de ração e etc...) sofreu com alagamento, falta de energia e perda de suprimentos. ', '2026-03-18 19:27:58', '2026-03-18 19:27:58', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29607, 30, 8, 470, NULL, '2026-03-18 19:28:59', '2026-03-18 19:28:59', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29608, 30, 9, 470, 'Povoado do Barroso; Córrego São Manoel; Córrego Romeiro de Cima; Córrego Serra Queimada; Córrego das Almas, Córrego da Areia Branca.', '2026-03-18 19:28:59', '2026-03-18 19:28:59', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29609, 30, 10, 470, 'Devido às fortes chuvas que acometeram o município, houve elevação significativa do nível de diversos curso d\'água, associada a intensas enxurradas, resultando na destruição de duas pontes no Córrego São Manoel, uma ponte no Córrego das Almas, uma ponte no Córrego Romerio de Cima e uma ponte no Povoado do Barroso, bem como na destruição parcial de outra ponte na mesma localidade. Verificou-se\nainda o comprometimento das cabeceiras de manilhamentos no Córrego Serra Queimada, além de alagamentos no Povoado do Barroso, afetando residências e estabelecimentos comerciais. Ademais, ocorreram desabamentos de encostas que provocaram a interdição de estradas, impossibilitando o acesso às referidas localidades.', '2026-03-18 19:28:59', '2026-03-18 19:28:59', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29610, 30, 1, 470, 'Devido ao grande volume de chuvas, foram registrados alagamentos de residências na Povoado do Barroso, resultando no desalojamento\nde diversas famílias. Além disso, ocorreram quedas de barreiras, ocasionando a interdição de estradas rurais e comprometendo o acesso às\nlocalidades afetadas', '2026-03-18 19:28:59', '2026-03-18 19:28:59', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29611, 30, 2, 470, 'Devido as fortes enxurradas e o aumento do nível das águas foram destruídas duas pontes no Córrego São Manoel, uma ponte no Córrego\ndas Almas, uma ponte no Romeiro de Cima e uma ponte no Povoado do Barroso, bem como na destruição parcial de outra ponte na mesma\nlocalidade. Verificou-se ainda o comprometimento das cabeceiras de manilhamento no córrego Serra Queimada.', '2026-03-18 19:28:59', '2026-03-18 19:28:59', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29612, 30, 11, 470, 'Mobilização de máquinas e mão de obra para limpeza das ruas atingidas por alagamentos, bem como para desobstrução de vias interditadas\nem decorrência de quedas de barreiras em estradas.', '2026-03-18 19:28:59', '2026-03-18 19:28:59', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29613, 30, 12, 470, 'Em decorrência das quedas de barreiras e processos erosivos registrados nas estradas vicinais do município, diversos trechos ficaram parcialmente ou totalmente interditados. Essa situação comprometeu o tráfego de veículos utilizados para o transporte da produção rural. Em razão dessas condições, produtores de leite não conseguiram realizar o escoamento regular de sua produção até os pontos de coleta e\nlaticínios. Considerando que o leite é um produto altamente perecível e depende de transporte diário, parte da produção foi perdida ou teve\nsua comercialização comprometida.\n', '2026-03-18 19:28:59', '2026-03-18 19:28:59', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29614, 3170, 8, 474, NULL, '2026-03-19 11:02:25', '2026-03-19 11:02:25', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29615, 3170, 9, 474, 'ZONA URBANA E RURAL :Bairros Chapada, Boa esperança, Barro Branco', '2026-03-19 11:02:25', '2026-03-19 11:02:25', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29616, 3170, 10, 474, 'No dia 09/03/2026, chuvas intensas atingiram diversas localidades, com registro de precipitação de aproximadamente 50,0 mm em um\nintervalo inferior a 2 horas, causando danos humanos e materiais. Diversas pessoas tiveram suas casas alagadas. Foram registrados danos\nem edificações públicas, como escolas e associações de bairro. A Escola Estadual José Ricardo Martins Fonseca ficou alagada. No PSF,\nhouve alagamento que danificou móveis e materiais de escritório. Na Escola de Ensino Infantil (CMEI) Joaquim Francisco Gomes, também\nfoi registrado alagamento, com danos na estrutura do telhado, no forro de gesso e no pátio, além de salas de aula inundadas. Houve ainda\nobstrução e arruinamento da rede pluvial no bairro Chapada, provocando alagamento da via e comprometendo o fluxo de veículos, sendo\nesta a principal via de acesso ao município. Também foram registrados diversos prejuízos econômicos ao município.', '2026-03-19 11:02:25', '2026-03-19 11:02:25', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29617, 3170, 1, 474, 'Pessoas foram afetadas indiretamente, tendo suas residências alagadas. Houve a suspensão das aulas nas escolas, a interrupção do atendimento no PSF e a interdição da via alagada, que é a principal via de acesso ao município, localizada na MG-129, próxima ao km 18.', '2026-03-19 11:02:25', '2026-03-19 11:02:25', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29618, 3170, 2, 474, '15 casas foram alagadas com perdas moveis, objetos pessoais, alimentos, devido a grande quantidade enxurrada e lama; No PSF, houve\nalagamento onde danificou móveis e material de escritório, tendo as atividades interrompidas, temporariamente; suspensão da Assistência\nmédica e saúde pública. sendo necessário a remoção de lama 400,00m²; Ensino: Suspensão 1 semana de aula no CMEI Boa Esperança (100 alunos), devido ao alagamento e danos na estrutura do telhado, desplacamento de forro mineral, alagando as salas de aula, além do alagamento no pátio e dependencias da escola. A Escola Estadual José Ricardo Martins Fonseca, ficou alagada, danificando material de escritório, moveis e eletrodomésticos, tendo as atividades interrompidas temporariamente; 01 associação chapada Lama no interior sendo necessário a remoção de lama 50,00m²; Alagamento e obstrução de vias danificadas, rompimento de rede de drenagem, alagamento na\nSede da Associação do Bairro Chapada; Obstrução a arruinamento da rede Pluvial, do bairro Chapada, alagando a pista, comprometendo oMfluxo de veículos, sendo a via o principal acesso ao município; Aproximadamente 900 pessoas afetadas diretamente devidos a via obstruída pelo alagamento , ficaram com a locomoção limitada, ', '2026-03-19 11:02:25', '2026-03-19 11:02:25', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29619, 3170, 11, 474, 'Abastecimento de todo maquinário para limpeza das áreas afetadas pelo evento, , limpeza de vias, ruas, escolas. PSF. Sistema de desinfestação/desinfecção do habitat/controle de pragas e vetores, das escolas, casas , psf, comércio local, sede da associação de bairros desobstrução e desassoreamento da rede de drenagem e boca', '2026-03-19 11:02:26', '2026-03-19 11:02:26', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29620, 3930, 8, 475, NULL, '2026-03-19 17:04:05', '2026-03-19 17:04:05', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29621, 3930, 9, 475, 'A área afetada pela chuva corresponde a população da zona rural e da zona urbana.\n', '2026-03-19 17:04:05', '2026-03-19 17:04:05', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29622, 3930, 10, 475, 'As chuvas do dia 23 de fevereiro de 2026 concorreram como agravantes da situação de anormalidade, onde o grande volume precipitado\nem um pequeno intervalo de tempo que com a precariedade do sistema de drenagem de águas pluviais e devido a chuvas intensas do dia\n27 de novembro de 2025, com valores de precipitação de 144 mm resultaram em danos materiais e prejuízos econômicos e sociais. As\nchuvas no município são escassas, irregulares e concentradas no verão. A média mensal de precipitação em Manga-MG, varia dependendo\ndo mês, com os valores mais altos concentrados entre novembro e dezembro. Em fevereiro de 2025, a média foi de 8,8 mm. No mês de\nfevereiro de 2026 a média foi de 132,5 mm. No dia 23 e 24 de fevereiro de 2026 foram 52,8 mm.\n', '2026-03-19 17:04:05', '2026-03-19 17:04:05', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29623, 3930, 1, 475, NULL, '2026-03-19 17:04:05', '2026-03-19 17:04:05', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29624, 3930, 2, 475, '2 pontes da zona rural: Ponte de Canabrava e Ponte de Moendinha, causando problemas de locomoção para 217 pessoas e danos no\nsistema de drenagem da Rua Almirante Barroso, Bairro: Centro.\n', '2026-03-19 17:04:05', '2026-03-19 17:04:05', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29625, 3930, 12, 475, 'AGRICULTURA: danos no escoamento econômico, em estradas rurais e na produção agrícola. PECUARIA: percas no escoamento econômico\ne nas pastegens', '2026-03-19 17:04:05', '2026-03-19 17:04:05', NULL);
