	(29726, 1600, 9, 494, 'Os Distritos de Penha do Coco e Professor Sperber e Córregos de Água Limpa, Varginha, Mata Fria, Volta Grande, Bananal de Cima, Bananal\nde Baixo, Palmital, Portugueses, Santana e Santaninha, afetando aproximadamente 2500 pessoas.', '2026-03-31 11:53:32', '2026-03-31 11:53:32', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29727, 1600, 10, 494, 'entre os dias 20/03/2026 e o dia 21/03/2026 o município de Chalé foi atingido por forte precipitações chuvosas, caracterizadas como chuvas\nintensas (COBRADE 13214), causando desastres múltiplos, vários córregos transbordaram na zona rural, ocasionando a destruição e abalo\nde pontes de concreto, destruindo bueiros e tubulões, deslizamento de massa (taludes e encostas) e destruição de estadas por enxurradas.', '2026-03-31 11:53:32', '2026-03-31 11:53:32', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29728, 1600, 1, 494, 'Em decorrência do desastre apontado, 2500 (duas mil e quinhentas) pessoas residentes na proximidade dos cursos d\'água transbordados\nforam afetadas com o com os desastres, tendo sua locomoção nas estradas afetadas, devido à inundação dos afluentes e o abalo de pontes,\nbueiros e deslizamentos de massa (queda de barreira).\n', '2026-03-31 11:53:32', '2026-03-31 11:53:32', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29729, 1600, 2, 494, '01 ponte do distrito de Penha do Coco, 01 bueiro no Córrego volta grande, 01 bueiros no Córrego Bananal de baixo, 01 bueiro no Córrego\nÁgua Limpa, 01 bueiro no Córrego Santaninha, 01 bueiro no Córrego Santana, 01 bueiro no Córrego Varginha, 01 bueiro no Córrego Mata\nFria e 01 bueiro na estrada que lida a sede do município de Chalé ao Distrito de Professor Sperber\n', '2026-03-31 11:53:32', '2026-03-31 11:53:32', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29730, 1600, 11, 494, 'Gasto com abastecimento das maquinas para retiradas de barreiras nas estradas que liga a sede do município aos distritos e córregos\natingidos', '2026-03-31 11:53:32', '2026-03-31 11:53:32', NULL);
