INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29733, 6555, 9, 495, 'Toda zona rural e Parte da zona urbana (bairros Planalto, João Barbosa Sena, Centro, Jacinta Ambrosina e Tima Pimenta)', '2026-03-31 12:04:24', '2026-03-31 12:04:24', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29734, 6555, 10, 495, 'Chuva intensa prolongada, aproximadamente com 70mm de precipitação, provocando o encharcamento do solo, enxurradas, alagamentos e\npequenos deslizamentos de terra. Em decorrência disso foram registrados danos humanos causados a cerca de 5110 afetados mediante\nimpactos em sua rotina. Também houve prejuízos econômicos diversos, públicos e privados, com atraso no escoamento de produtos da\nagricultura e da pecuária e na restrição de atividades de setores do comércio e serviços. Danos materiais com avarias e perdas em infra\nestruturas diversas públicas, trechos de calçamentos, galerias pluviais, perda do revestimento primário em estradas, danos de residências\ndentre outros.', '2026-03-31 12:04:24', '2026-03-31 12:04:24', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29735, 6555, 1, 495, '8 Unidades habitacionais tiveram entrada de água, 1 Unidade habitacional teve queda de muro 3 Unidades habitacionais tiveram\ndeslizamento de encostas conforme chamados realizados 1 Ponte Interditada, com acesso para cerca de 10 residências Diversas quedas de\nbarreiras nas comunidades Obras De Infraestrutura Pública: Obras De Infraestrutura Pública Danificadas (Av. Santo Antônio No-Bairro João\nBarbosa Sena, Rua Monsenhor Jorge Lopes No Bairro Planalto, Rua Minervina Santos Pereira No Centro, Rua Francisco De Assis No Centro,\nRua Giomar S.Otoni No Centro, Rua José Lucas GoMes No Bairro Jacinta Ambrosina, Rua Gabriela De Paula No Bairro Jacinta Ambrosina E\nOutras Ruas Na Zona Urbana E Zona E Rural. Os Danos Ainda Estão Em Levantamento Devido A Quantidade De Ruas E Comunidades.\nComunidade Soturno e Cará com infraestrutura muito danificada devido erosões das enxurradas e quedas de barreiras.', '2026-03-31 12:04:24', '2026-03-31 12:04:24', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29736, 6555, 2, 495, '8 Unidades habitacionais tiveram entrada de água, 1 Unidade habitacional teve queda de muro 3 Unidades habitacionais tiveram\ndeslizamento de encostas conforme chamados realizados 1 Ponte Interditada, com acesso para cerca de 10 residências Diversas quedas de\nbarreiras nas comunidades Obras De Infraestrutura Pública: Obras De Infraestrutura Pública Danificadas (Av. Santo Antônio No-Bairro João\nBarbosa Sena, Rua Monsenhor Jorge Lopes No Bairro Planalto, Rua Minervina Santos Pereira No Centro, Rua Francisco De Assis No Centro,\nRua Giomar S.Otoni No Centro, Rua José Lucas GoMes No Bairro Jacinta Ambrosina, Rua Gabriela De Paula No Bairro Jacinta Ambrosina E\nOutras Ruas Na Zona Urbana E Zona E Rural. Os Danos Ainda Estão Em Levantamento Devido A Quantidade De Ruas E Comunidades.\nComunidade Soturno e Cará com infraestrutura muito danificada devido erosões das enxurradas e quedas de barreiras.\n', '2026-03-31 12:04:24', '2026-03-31 12:04:24', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29737, 6555, 11, 495, 'Sistema de limpeza urbana e de recolhimento e destinação do lixo, realização de limpeza e desobstrução de vias do município com veíulos\npróprios e contratados Transportes locais, regionais e de longo curso - Empenho e deslocamento de veículos em regime de prestação de\nserviço com aluguel de retroescavadeira e caçamba para remoção de entulhos, lamas e desobstrução da vias publicas. Abastecimentos de\ncombustíveis das maquinas e veículos da prefeitura municipal para auxilio de limpezas já citadas', '2026-03-31 12:04:24', '2026-03-31 12:04:24', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29738, 6555, 12, 495, 'O forte volume de chuvas, aliado às condições topográficas do município e devido às consequências nos danos em infraestruturas,\nAgricultura: acarretou a elevação das perdas na produção primária, que além de danos causados na produção de forragens, cereais, demais\nculturas, principalmente em regiões de baixadas, provocou grandes inundações favorecendo o desgaste da fertilidade dos solos,\nassoreamentos e interferindo na produção de leite, carne, dificuldades no manejo de produção. Assim, a Agricultura e a Pecuária local\ntiveram grandes prejuízos econômicos.\n', '2026-03-31 12:04:24', '2026-03-31 12:04:24', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29739, 5240, 8, 496, NULL, '2026-03-31 12:33:32', '2026-03-31 12:33:32', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29740, 5240, 9, 496, 'Os bairros Centro e Floresta foram os mais atingidos, com registros de destelhamentos, quedas de árvores sobre vias e imóveis, além de alagamentos severos. O volume das enxurradas provocou a inundação de logradouros, o arraste de sedimentos e detritos, e a erosão do solo, resultando na abertura de valas em diversos pontos.', '2026-03-31 12:33:32', '2026-03-31 12:33:32', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29741, 5240, 10, 496, 'Em 19 de março de 2026, por volta das 14h20, o município de Poté foi atingido por uma tempestade severa do tipo convectiva. O fenômeno, que durou cerca de 30 minutos, combinou chuvas intensas e vendavais, afetando diversas áreas urbanas ¿ com impactos severos no Centro e no bairro Floresta. Os danos registrados incluem o destelhamento de edificações, queda de árvores sobre vias e residências, além de alagamentos e enxurradas que comprometeram a trafegabilidade das ruas.', '2026-03-31 12:33:32', '2026-03-31 12:33:32', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29742, 5240, 1, 496, 'Informa-se que o Município de Poté/MG registrou aproximadamente 500 (quinhentas) pessoas afetadas pelo desastre, as quais tiveram suas residências alagadas, ocasionando significativos transtornos à população, incluindo a perda de móveis e eletrodomésticos.\nRessalta-se, ainda, que houve 04 (quatro) pessoas desalojadas, as quais, em razão da impossibilidade temporária de permanência em suas residências, encontram-se acolhidas na casa de amigos.\n\nAinda, que houve danos ao sistema de drenagem, o que contribuiu para o agravamento da situação e intensificou os prejuízos e transtornos enfrentados pelos munícipes.', '2026-03-31 12:33:32', '2026-03-31 12:33:32', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29743, 5240, 2, 496, 'Registra-se a ocorrência de destelhamento de diversas residências, ocasionado por vendavais, bem como o alagamento de múltiplos imóveis, resultando em perdas de móveis e eletrodomésticos, o que gerou consideráveis transtornos à população afetada.\n\nAdicionalmente, informa-se que houve danos na Rua Adolfo Colen, em razão de problemas no sistema de drenagem, impactando diretamente os moradores das áreas adjacentes.\n\nRessalta-se, ainda, que a Casa de Acolhimento Nunes teve um de seus dormitórios danificado, além de ter ocorrido destelhamento da edificação em decorrência do vendaval.', '2026-03-31 12:33:32', '2026-03-31 12:33:32', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29744, 6970, 8, 497, NULL, '2026-03-31 12:46:21', '2026-03-31 12:46:21', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29745, 6970, 9, 497, 'TODO O TERRITORIO DO MUNICIPIO DE TURMALINA (TODA A ZONA RURAL E  ZONA URBANA).', '2026-03-31 12:46:21', '2026-03-31 12:46:21', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29746, 6970, 10, 497, 'Considerando que as chuvas vivenciadas no município de Turmalina/MG, na madrugada do do dia 16/03/2026, com acúmulo de volume\npluviométrico de 105mm, fato que não é recorrente no município. Que em decorrência desse\ndesastre vários danos foram ocasionados no município na zona urbana e rural. Danos Humanos: estima-se que cerca de 20 mil pessoas foram afetadas, assim sendo discriminadas - 04 pessoas desabrigadas; 07 pessoas desalojadas; aproximadamente 3.761 pessoas ilhadas (devido as 01 ponte sob\no rio araçuai que está submersa; além das outras 16.228 afetadas indiretamente (devido as interdições parciais das vias em função dos deslizamentos de terra e dos diversos danos nas estruturas públicas de saúde, de ensino e do mercado municipal, impactando diretamente na vida de todos os\nmunícipes. Danos Materiais: afetaram a infraestrutura pública e privada, incluindo, unidades habitacionais, vias urbanas, estradas vicinais e\npontes, assim descritas: Danos Ambientais: deslizamento de terra em diversos pontos das áreas urbanas e rurais, assoreamento do leito do\nCórrego Santo Antônio, Córrego do Lamba, Córrego São Franscisco e Córrego José Silva.\n\n\n', '2026-03-31 12:46:21', '2026-03-31 12:46:21', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29747, 6970, 1, 497, 'Estima-se que cerca de 20 mil pessoas foram afetadas, assim sendo discriminadas: 04 pessoas desabrigadas; 07 pessoas desalojadas;\naproximadamente 3.761 pessoas ilhadas (devido as 01 ponte sob o rio araçuai que está submersa); além das outras 16.228 afetadas indiretamente (devido as interdições parciais das vias em função dos deslizamentos de terra e dos diversos danos na estrutura pública de saúde, impactando diretamente na vida de todos os munícipes).', '2026-03-31 12:46:21', '2026-03-31 12:46:21', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29748, 6970, 2, 497, 'A Defesa Civil Municipal realizou o levantamento dos pontos mais críticos afetados pelas intensas chuvas da madrugada do dia 16 de março\nde 2026, os danos materiais foram significativos e abrangem diversos setores, afetando a infraestrutura pública e privada, incluindo,\nunidades habitacionais, vias urbanas, estradas vicinais e pontes, assim descritas: - Quatro residências na área urbana danificada; - Duas casas interditadas na zona urbana; - Seis residências na área rural danificadas; - Uma ponte submersa na comunidade de Ponte do Quincas que afeta outras 7 comunidades; - Seis estradas destruídas (zona rural); - Sete ruas danificadas (zona urbana).', '2026-03-31 12:46:21', '2026-03-31 12:46:21', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29749, 6970, 3, 497, 'Ocorreu deslizamento de terra em diversos pontos das áreas urbanas e rurais, assoreamento do leito do Córrego Santo Antônio, Córrego do Lamba, Córrego São Franscisco e Córrego José Silva.', '2026-03-31 12:46:21', '2026-03-31 12:46:21', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29750, 6970, 11, 497, '- Desobstrução de vias em decorrência de deslizamentos de terras e manutenção nas estradas urbanas e vicinais. - Compra de combustivel\npara as máquinas patrol, retro e pá carregadeira para limpeza de ruas e estradas. - Envio de carros para transportes de pacientes,\nestudantes e agricultores. - Aluguel de caminhão pipa para limpeza de manilhas nas estradas vicinais e de ruas. - Aquisição de produtos e\ncontratação de equipe para combate ao caramujo, que aumentou muito a proliferação durante o período chuvoso.', '2026-03-31 12:46:21', '2026-03-31 12:46:21', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29751, 6970, 12, 497, 'Várias famílias tiveram perda de lavouras como milho,cana, abobora e hortaliças e frutas, devido a inacessibilidade, tendo em consideração\nque a maioria vivem exclusivamente da venda de sua produção. Os danos causados pelas chuvas nas estradas não perrmitindo o\nescoamento dos produtos.', '2026-03-31 12:46:21', '2026-03-31 12:46:21', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29752, 2675, 8, 499, NULL, '2026-03-31 13:26:08', '2026-03-31 13:26:08', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29753, 2675, 9, 499, 'Toda zona Urbana e Rural foram afetadas pela chuva.', '2026-03-31 13:26:08', '2026-03-31 13:26:08', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29754, 2675, 10, 499, 'HOUVE FORTE PRECIPITAÇÃO PLUVIOMÉTRICA CHOVENDO CERCA DE 60 MM EM 02 HORAS, SENDO ESSE TOTAL MAIS DE 65 % DA MÉDIA PREVISTA PARA O MÊS DE MARÇO, AFETANDO TODO O TERRITÓRIO DO MUNICÍPIO. ', '2026-03-31 13:26:08', '2026-03-31 13:26:08', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29755, 2675, 1, 499, 'Em Decorrência da forte chuva as estradas queligam a sede as comunidades rurais, ficaram praticamente intransitáveis, impedido que as pessoas pudessem manter suas necessidades básicas como: acesso a saúde, educação e alimentação. Muitos dos produtores de leite tiveram perca em sua produção devido a impossibilidade de escoação do leite e devido a queda de energia.', '2026-03-31 13:26:08', '2026-03-31 13:26:08', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29756, 2675, 2, 499, 'danificadas: 4 residencias foram inundadas e os moradores perderam moveis como: geladeira, sofá, cama, cadeiras, roupas etc. Tambem tres calçamentos foram danificados.', '2026-03-31 13:26:08', '2026-03-31 13:26:08', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29757, 2675, 11, 499, 'Houve um gasto no valor de R$ 34.700,00 com mão de obra, locação de máquinas e caçamba e combustível para abastecimento de maquinários para limpeza das vias urbanas, nas quais houve deslizamento de terra e R$ 120,000,00 com locação de máquinas e combustível para desobstrução de estradas vicinais, retirada de barreiras, reparos empontes e mata-burros para restabelecimento do acesso.', '2026-03-31 13:26:08', '2026-03-31 13:26:08', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29758, 2675, 12, 499, 'Analisando o período em questão, houve grande volume de precipitação, resultando em altos volumes de enchentes, causando vários prejuízos, como afogamento de animais, destruição de cercas, destruição de lavouras, pastagens e edificações. As estradas rurais estão bastante esburacadas, com muitos atoleiros, além de muitas barreiras, obstruindo apassagem de veículos, o que dificulta o escoamento da produção agropecuária. Houve queda de energia ocasionando perda da produção armazenada de leite, consequentemente causando queda na produção de produtos lácteos nos laticínios.', '2026-03-31 13:26:08', '2026-03-31 13:26:08', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29759, 285, 9, 404, 'toda área rural e urbana', '2026-03-31 17:10:02', '2026-03-31 17:10:02', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29760, 285, 10, 404, 'choveu 110 ml em curto período, rios transbordaram, enxurrada de grande proporção pontes destruídas, deixando famílias ilhadas', '2026-03-31 17:10:02', '2026-03-31 17:10:02', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29761, 285, 1, 404, 'O município registrou 1.232 pessoas afetadas pelas chuvas, das quais 32 ficaram desalojadas, encontrando-se abrigadas em residências de\nparentes e familiares. Na comunidade da Barra do Sape, famílias ficaram ilhadas. Na comunidade do Fanado, famílias precisaram se\ndeslocar para casas de parentes em razão do arraste de uma ponte pela enxurrada. Já na comunidade de São Benedito, o Rio Fanado\ntransbordou, deixando famílias ilhadas e ocasionando o alagamento de residências. Em decorrência desses eventos, foram registrados\ndanos materiais, incluindo a perda de móveis, eletrodomésticos e alimentos', '2026-03-31 17:10:02', '2026-03-31 17:10:02', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29762, 285, 2, 404, 'comunidade do são benedito, 1 casa danificada, eletrodomésticos danificados moveis estragos. na zona urbana 1 casa danificada perda de\neletrodomésticos e moveis fanado 1 casa danificada perda de moveis zona urbana 1 casa danificada 1 unidade de saúde a policlínica\nmunicipal teve o telhado danificado devido a chu', '2026-03-31 17:10:02', '2026-03-31 17:10:02', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29763, 285, 11, 404, 'limpeza de ruas com caminhão pipa retro escavadeira telhado da policlínica municipal\n7.2 PREJUÍZOS ECONÔMICOS PRIVADOS\nValor das perdas nos setores da agricultura, pecuária, indústria, comércio e serviços ocorridas em\ndecorrência direta dos efeitos do desastre.\nVal', '2026-03-31 17:10:02', '2026-03-31 17:10:02', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29764, 285, 12, 404, 'pecuaristas perderam a produção de leite devido o transbordamento de rios, ficando ilhados agricultura familiar perderam algumas\nproduções por não ter como escoar sua produção devido transbordamento do rio e ponte ter sido danificada', '2026-03-31 17:10:02', '2026-03-31 17:10:02', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29765, 3500, 8, 500, NULL, '2026-04-01 18:29:12', '2026-04-01 18:29:12', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29766, 3500, 9, 500, 'Zona Urbana, parte central: Rua Governador Valadares, Rua do Rosario, Rua 19 de Março, Rua Beira Rio, Rua São José, Praça Jaime Morais\nQuintão,Praça João Rolla. *Zona Rural: Fazenda Pimenteira. *Distrito de Lavrinha: Ponte sentido chácara Leão e Estação de Tratamento de\nÁgua.', '2026-04-01 18:29:13', '2026-04-01 18:29:13', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29767, 3500, 10, 500, 'Na madrugada do dia 23 de março de 2026 (dois mil e vinte e seis), por volta das 2 horas da manhã, um forte temporal atingiu o município\nde Jaguaraçu/MG, com acumulado de chuva que chegou à 123mm de volume, em um período de, aproximadamente, 3 (três) horas. Devido\na essa situação, o nível do Ribeirão Onça Grande se elevou rapidamente, alagando vias, moradias e edificações públicas, houve queda de\nárvores, desabamento de muro, entupimento do filtro da barragem e Estação de Tratamento de Água da Lavrinha, afetando o\nabastecimento de água', '2026-04-01 18:29:13', '2026-04-01 18:29:13', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29768, 3500, 1, 500, 'Em decorrência da chuva na madrugada do dia vinte e três de março de dois mil e vinte e seis, estima-se que 457 pessoas foram afetadas\ndireta e indiretamente pelo desastre. Segundo relatório da assistência social foram 15 famílias desalojadas, totalizando 56 pessoas\ndesalojadas. Os outros afetados, totalizando, aproximadamente, 400 pessoas, são comerciantes que foram impossibilitados de abrir o seu\ncomércio, estudantes que deixaram de ir à escola, outras pessoas e trabalhadores que tiveram a sua rotina interrompida total e/ou\nparcialmente e comunidades que ficaram isoladas devido à quedas de pontes, dificultando, em muito a rotina. As importantes atividades que\nacontecem na Escola Municipal Joaquim de Araújo Miranda, como reuniões, apresentações e aulas para crianças do ensino básico e creche,\ntiveram que ser interrompidas', '2026-04-01 18:29:13', '2026-04-01 18:29:13', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29769, 3500, 2, 500, NULL, '2026-04-01 18:29:13', '2026-04-01 18:29:13', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29770, 3500, 3, 500, 'Foi verificado danos ambientais, pois as enchentes carregam grande volume de sedimentos e os depositam no leito do curso d\'água,\ncausando seu assoreamento. Eventos como esse geram impactos ambientais, como a contaminação das fontes para abastecimento público,\ndeteriorando sua qualidade, além de favorecer a ocorrência de doenças de veiculação hídrica e proliferação de vetores. Houve falta de água\nna comunidade central da Lavrinha (23/03/2026 a 26/03/2026) , porque a água foi contaminada com lama, sendo necessário alguns dias\npara limpar a barragem e retirar toda a areia e lama. Também aconteceu o rompimento de canos e tubos no local, o que impossibilitou o\nabastecimento de água. Também houve falta de água, por um dia após o desastre, nos bairros da Sede , pois a tubulação da ETA (Estação\nde Tratamento de Água) foi rompida no desastre.\n', '2026-04-01 18:29:13', '2026-04-01 18:29:13', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29771, 3500, 11, 500, ' O abastecimento de água potável comprometido na sede e no Distrito da Lavrinha, com rompimento da rede adutora, tubulação e sistema\nde tratamento comprometido, gerando um valor estimado de R$ 10.000,00 para reparo * A rede coletora de esgoto da cidade havia sido\ndanificada com a Tempestade Local/Convectiva - Chuvas Intensas ocorrida em 08/01/2023 e, no ano de 2025 havia começado a sua\nreconstrução. Com este novo evento do dia 23/03/2026, essa mesma rede coletora de esgoto ficou prejudicada. *Em relação ao sistema de\nlimpeza urbana, para a retirada de entulhos, estima-se R$ 8.000,00 de gastos, entre maquinários, equipamentos, combustível e mão-deobra. *No Ensino, os prejuízos econômicos públicos gir', '2026-04-01 18:29:13', '2026-04-01 18:29:13', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29772, 3500, 12, 500, 'Segue a estimativa do valor do prejuízo econômico no setor privado neste primeiro momento do desastre: Os pontos comerciais da sede\ncomo farmácia, lanchonetes, Casa dos Fazendeiros, depósito de materiais de construção, lojas, banco e igreja, foram severamente\nprejudicados. Os comerciantes registraram perdas significativas devido à destruição de bens destinados ao comércio, à prestação de\nserviços e à subsistência de suas famílias. Além dos danos materiais, muitos estabelecimentos precisaram interromper suas atividades, e\nvários ainda não conseguiram retomar plenamente o atendimento ao público, comprometendo o fluxo de renda e o sustento familiar. A\nagricultura e a pecuária também foram impactadas, especialmente pela interrupção temporária do escoamento da produção. Isso ocorreu\nem razão dos danos nas pontes que conectam as estradas rurais e urbanas, além de inundações em áreas de plantio. O turismo urbano e\nrural, inserido no setor de serviços, também sofreu prejuízos. No distrito da Lavrinha e Sede do Município, onde se concentram diversos\nsítios para locação, os proprietários foram afetados pelos danos nas pontes de acesso e interior das propriedades. Com a mobi', '2026-04-01 18:29:13', '2026-04-01 18:29:13', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29773, 570, 8, 501, NULL, '2026-04-01 18:37:48', '2026-04-01 18:37:48', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29774, 570, 9, 501, 'Destruição de 02 pontes na comunidade do Fragoso, destruição de 01 bueiro na comunidade de Dobla/São Paulo Vieira; destruição de 01\nponte na comunidade do Pimenta na estrada que liga o município de Barra Longa a Alvinópolis ; danos em 02 pontes na comunidade do\nBonfim; danos em 02 pontes na estrada que liga a comunidade do tabuões a comunidade do Dobla; ; danos em 04 bueiros na comunidade\ndo Bonito; danos em 01 bueiro na estrada que liga Barra Longa as comunidades do Pimenta Covanca e Bomfim; destruição de 01 bueiro na\ncomunidade do Caqui; destruição de 02 bueiros na comunidade do Alto do Bonsucesso; danos em bueiro na comunidade do Barreto; Danos\nem uma residência na comunidade do Tabuões devido alagamento do corgo ao fundo da residência; e duas residências interditadas na sede\npor estar em área de risco alto de queda de talude', '2026-04-01 18:37:48', '2026-04-01 18:37:48', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29775, 570, 10, 501, 'Que ocorreram fortes chuvas que caíram sobre o Município de Barra Longa, Estado de Minas Gerais, com início no dia 23 de março de 2026,\ncom acumulado de chuva ultrapassando a média de 80 milímetros esperada para todo o mês com duração de 02 horas, causando\ndestruição de pontes, bueiros, deslizamento de terra e interrupção das estradas vicinais do município\n', '2026-04-01 18:37:48', '2026-04-01 18:37:48', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29776, 570, 1, 501, 'Várias pessoas foram diretamente afetadas pelo desastre que residem nas comunidades rurais do município. Devido a queda de pontes,\nbueiros e barreiras que permitem acessos às comunidades acima listados, os munícipes que moram na zona rural estão com deslocamentos\ntotalmente prejudicados. Ocorreu deslizamento de terra gerando interrupção das estradas vicinais que ligam o município , Danos em uma\nresidência na comunidade do Tabuões devido alagamento do corgo ao fundo da residência; e duas residências interditadas na sede por\nestar em área de risco alto de queda de talude, Informo que continuamos trabalhando nas buscas das informações em outras comunidades\ne contabilização dos danos\n', '2026-04-01 18:37:48', '2026-04-01 18:37:48', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29777, 570, 2, 501, 'Destruição de 02 pontes na comunidade do Fragoso, destruição de 01 bueiro na comunidade de Dobla/São Paulo Vieira; destruição de 01\nponte na comunidade do Pimenta na estrada que liga o município de Barra Longa a Alvinópolis ; danos em 02 pontes na comunidade do\nBonfim; danos em 02 pontes na estrada que liga a comunidade do tabuões a comunidade do Dobla; ; danos em 04 bueiros na comunidade\ndo Bonito; danos em 01 bueiro na estrada que liga Barra Longa as comunidades do Pimenta Covanca e Bomfim; destruição de 01 bueiro na\ncomunidade do Caqui; destruição de 02 bueiros na comunidade do Alto do Bonsucesso. Danos em uma residência na comunidade do\nTaboões devido alagamento do corgo ao fundo da residência; e duas residências interditadas na sede por estar em área de risco alto de\nqueda de talude.', '2026-04-01 18:37:49', '2026-04-01 18:37:49', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29778, 570, 11, 501, 'Os prejuízos econômicos relacionados ao desastre na área da saúde, está relacionado ao deslocamento da equipe para fins de apoio às\nfamílias que encontram-se afetadas diretamente pelo desastre para medicação e acompanhamento psicológico. Na área de limpeza urbana\ne destinação de lixo, o município precisou locar conteiners de armazenamento de resíduos para deixar em locais estratégicos para fins de\ndestinação adequada e o maior custo do munícipio no presente momento está relacionado ao deslocamento de equipamentos para\nrestabelecimento de acessos para locomoção das pessoas que residem nas áreas afetadas na zona rural.', '2026-04-01 18:37:49', '2026-04-01 18:37:49', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29779, 570, 12, 501, 'Pecuaria: estradas e pontes interditadas onde o escoamento da produção de leite e carne foi comprometido Agricultura: lavoura de m', '2026-04-01 18:37:49', '2026-04-01 18:37:49', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29780, 2390, 8, 502, NULL, '2026-04-01 18:42:37', '2026-04-01 18:42:37', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29781, 2390, 9, 502, 'Comunidade Serra do Camapuã, cujos moradores foram diretamente afetados, uma vez que dependem da ponte atingida para acessar o\nmunicípio, sendo esta estrutura essencial para o deslocamento diário, o transporte de insumos e o acesso a serviços públicos básicos.\n', '2026-04-01 18:42:37', '2026-04-01 18:42:37', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29782, 2390, 10, 502, 'Foram registradas chuvas intensas, acompanhadas de raios, ventos fortes e trovões, com duração aproximada de 4 (quatro) horas,\ntotalizando 35,5 mm de precipitação pluviométrica.\n', '2026-04-01 18:42:37', '2026-04-01 18:42:37', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29783, 2390, 1, 502, 'Apesar de o Município não registrar a existência de pessoas desalojadas ou desabrigadas, estima-se que aproximadamente 100 pessoas\ntenham sido diretamente atingidas pelo desastre, em razão da destruição da ponte, o que ocasionou significativa alteração na rotina da\npopulação local. Ressalta-se que os moradores dependem dessa estrutura para o deslocamento diário, especialmente para o acesso de\ncrianças às escolas, bem como para a busca de medicamentos e atendimento às necessidades de idosos. Diante disso, evidencia-se que o\nMunicípio não dispõe de condições financeiras suficientes para arcar, com recursos próprios, com a reconstrução da ponte, sendo necessária\na adoção de medidas de apoio para restabelecimento da mobilidade e das condições mínimas de acesso da comunidade afetada.', '2026-04-01 18:42:37', '2026-04-01 18:42:37', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29784, 2390, 2, 502, 'Registra-se, ainda, a destruição de 01 (uma) ponte localizada na Comunidade de Camapuã, ocasionando a interrupção do tráfego e\ncomprometendo o acesso dos moradores à sede do município, bem como a serviços essenciais, como transporte escolar, atendimento de\nsaúde e aquisição de medicamentos. Diante disso, evidencia-se que o Município não dispõe de condições financeiras suficientes para arcar,\ncom recursos próprios, com a reconstrução da ponte, sendo necessária a adoção de medidas de apoio para restabelecimento da mobilidade\ne das condições mínimas de acesso da comunidade afetada.', '2026-04-01 18:42:37', '2026-04-01 18:42:37', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29785, 2390, 11, 502, 'foram gastos materiais para isolamento,como fitas zebradas,banners informativos,veiculos publicos,caminhoes, máquinas(retroescavadeiras)', '2026-04-01 18:42:37', '2026-04-01 18:42:37', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29786, 3920, 8, 503, NULL, '2026-04-09 10:26:57', '2026-04-09 10:26:57', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29787, 3920, 9, 503, 'ZONA URBANA: Bairros Centro, Santa Rita, Nossa Senhora das Graças, Pequi, Augusto Teixeira Guedes, Santo Antônio, Bela Vista,\nLoteamento Gêla, Várzea, Vila Boa Sorte. ZONA RURAL: Distritos Jaguaritira e Santo Antônio do Mucuri; Comunidades São João da Serra,\nSerrinha, Morro dos Pereiras, Setúbal I e II, Almeidas, Água Quente, João José I, Caranguejos, Santana, São João da Ponte, Caatingas,\nBarreiro, Lavra dos Rosas, Baixão, Córrego Da Prata, Bimbarra, Córrego da Prata, Córrego da Lama, Córrego da Lua, Ferreirinhas,\nVeredinha, Moreiras, Graminha, Machados.', '2026-04-09 10:26:57', '2026-04-09 10:26:57', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29788, 3920, 10, 503, 'Caracterizou-se pela ocorrência de chuvas intensas no dia 23 de março de 2026, com precipitação acumulada superior a 63 mm em curto\nespaço de tempo; deixando o município com diversos pontos vulneráveis, acarretando em sobrecarga dos sistemas de drenagem e a\nconsequente ocorrência de alagamentos, desmoronamentos e aumento do risco geológico pela vulnerabilidade causada pelo acumulado que\nsuperou os 150mm em apenas 96h.\n', '2026-04-09 10:26:57', '2026-04-09 10:26:57', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29789, 3920, 1, 503, 'Caracterizados por 3.552 pessoas afetadas, incluídas 102 desabrigadas e desalojadas, que diante de risco às suas residências e,\nconsequentemente à integridade física e à vida dos moradores, acataram a orientação/determinação da equipe técnica de Defesa Civil para\nse deslocarem para casa de parentes/familiares ou para moradias temporárias providenciadas pela Assistência Social do município, no\nregime de "aluguel social"; bem como outros afetados, sendo 450 pessoas ligadas a setores econômicos da indústria e serviços,\ncontabilizaram danos/prejuízos em função da perda de matérias primas; 800 pessoas tiveram perdas produção da agricultura e pecuária\nafetando sua subsistência; 2200 pessoas tiveram restrição parcial de acesso a educação em função da intransitabilidade.', '2026-04-09 10:26:57', '2026-04-09 10:26:57', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29790, 3920, 2, 503, '- Unidades habitacionais: 02 duas destruídas nos bairros Vila Boa Sorte e Várzea avaliadas em R$ 570.000,00; 28 vinte e oito danificadas\nnos bairros Vila Boa Sorte, Várzea, Tancredo Neves, Nova Esperança, Bela Vista, Augusto Teixeira Guedes, Jerusalém, Santo Antônio, Santa\nRita e Nossa Senhora das Graças, por atingimento de taludes desmoronados à jusante ou à montante, avaliadas no valor de R$\n2.370.000,00. - Instalação públicas prestadora de outros serviços danificadas: 01 prédio da Secretaria Municipal de Assistência Social, com\navarias importantes em parede e colunas, avaliadas (fins de alçada) em R$ 1,000.00 - Instalações públicas de uso comunitário danificadas:\nAvarias na associação rural na comunidade Monte Cristo e do Bairro Esperança; avaliadas (fins de alçada) em R$ 1.000,00. - Obras de\ninfraestrutura pública: 06 seis destruídas, sendo 03 pontes no Bairro/comunidade (perímetro rural) da Vila Boa Sorte e 01 na comunidade\nJoão José; 02 segmentos da Ruas Francisco Ricardo de Souza, Várzea e Tancredo Neves, com recalque de grade por colapso de estrutura\nsubterrânea de drenagem, avaliadas em R$ 480.000,00. Bem como 22 danificadas, sendo, 07 sete ruas com segmentos de por\ndesmoronamentos de taludes de sustentação, nos bairros Santa Rita, Augusto Teixeira Guedes, Várzea, Tancredo Neves e Nossa Senhora\ndas Graças; 02 segmentos de Ruas, nos Bairros Várzea e Centro, com recalque de grade por colapso de estrutura subterrânea de\ndrenagem; 03 muros de arrimo com rompimentos, rachaduras ou queda parcial, nos Bairros Augusto Teixeira Guedes e Nossa Senhora das\nGraças e Várzea; bem como afetação de 11 doze vias rurais intransitáveis, avaliadas no valor de R$ 2.700.000,00.', '2026-04-09 10:26:57', '2026-04-09 10:26:57', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29791, 3920, 11, 503, 'Sistema de limpeza urbana e de recolhimento e destinação do lixo: Custos para a realização da limpeza e retirada de entulho e terra,\navaliados em R$ 115.000,00; Transportes locais, regionais e de longo curso: Custos com combustível provenientes à operação de veículos e\nmáquinas no atendimento aos afetados, avaliados em R$ 35.000,00; Segurança pública (utilizado para): Distribuição de cestas básicas à\npopulação mais afetada, avaliados em R$ 17.500,00; Ensino(utilizado para): Financiamento de ajuda de custo para moradia provisória\n(aluguél social) fornecimento de materiais de construção (areia, cimento, tijolos) para auxílio de reparos em residências de pessoas\natingidas, avaliados em R$ 49.000,00;', '2026-04-09 10:26:58', '2026-04-09 10:26:58', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29792, 3920, 12, 503, 'Agricultura - Perda de produtividade por alagamento e destruição de lavouras, bem como perdas por insufucência de condições de\nescoamento. Pecuária - Perda de produção da cadeia produtiva de leite, principalmente pela interrupção e/ou restrição trafegabilidade de\nestradas vicinais de regiões de maior produtividade. Indústria - Perda de materias primas em estoque em pátios de fábricas de blocos.\nServiços - Danos/prejuízos em função da afetação na circulação de mercadorias.', '2026-04-09 10:26:58', '2026-04-09 10:26:58', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29793, 5310, 8, 504, NULL, '2026-04-09 10:35:53', '2026-04-09 10:35:53', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29794, 5310, 9, 504, 'Em toda a zona urbana e rural do municipio, principalmente nas localidades de Mato Dentro, Engenho, Barbacena, Taquaraçu, Cachoeira do\nJumirim, Bananeiras, São Nicomedes, Retiro onde houve danos em infraestruturas e quedas de barreiras, de árvores e erosões por todas as\nestradas vicinais;', '2026-04-09 10:35:53', '2026-04-09 10:35:53', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29795, 5310, 10, 504, 'Chuvas intensas precipitaram no município causando inúmeros danos materiais por toda a cidade durante os meses de fevereiro e março.\nNo dia 31 de março, além de outras avarias na cidade, as chuvas provocaram danos e destruição de infraestruturas públicas na zona rural;\nHouve danos em pavimentos da zona urbana. Houve danos nas localidades de Mato Dentro, Engenho, Barbacena, Taquaraçu, Cachoeira do\nJumirim, Bananeiras, São Nicomedes, Retiro e quedas de barreiras, de árvores e erosões por todas as estradas vicinais; Que por ter a\nresposta e o restabelecimento de vários danos terem sido custeados com recursos próprios da prefeitura, sobretudo reconstrução de\npavimentos nas estradas vicinais, limpeza de vias urbanas e desobstrução de vias rurais afetadas por deslizamentos e quedas de árvores a\ncapacidade de resposta orçamentária da prefeitura ficou comprometida\n', '2026-04-09 10:35:53', '2026-04-09 10:35:53', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29796, 5310, 1, 504, 'Apesar das chuvas intensas, não houve danos significativos em residências. As pessoas foram afetadas pela destruíção de infraestruturas\npúblicas que impediu a mobilidae o acesso ao comércio, serviços e também na distribuição da produção econômica local', '2026-04-09 10:35:53', '2026-04-09 10:35:53', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29797, 5310, 2, 504, NULL, '2026-04-09 10:35:53', '2026-04-09 10:35:53', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29798, 5310, 11, 504, 'O recolhimento de detritos decorrentes dos eventos adversos sobrecarregou o contrato de limpeza urbana, além do planejado', '2026-04-09 10:35:53', '2026-04-09 10:35:53', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29799, 5310, 12, 504, 'A agricultura e a pecuária tiveram prejuízos em decorrência da interrupção das estradas vicinais em vários trechos, seja por quebra de\npontes, danos em bueiros, quedas de barreiras e árvores o que impediu o escoamento da produção local. O comércio e os serviços foram\nafetados pela interrupção da mobilidade impedindo o acesso da população aos estabelecimentos comerciais e fornecedores de serviços. Os\nlevantamentos ainda estão em andamento.\n', '2026-04-09 10:35:53', '2026-04-09 10:35:53', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29800, 550, 8, 505, NULL, '2026-04-09 10:47:37', '2026-04-09 10:47:37', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29801, 550, 9, 505, 'Distrito de Silveira Carvalho, todas as ruas do perimetro urbano e rura', '2026-04-09 10:47:37', '2026-04-09 10:47:37', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29802, 550, 10, 505, 'O desastre foi causado por evento climático extremo caracterizado por precipitação pluviométrica intensa e concentrada, ocorrido na noite\ndo dia 23 de março de 2026, no território do Município de Barão do Monte Alto/MG, especialmente no Distrito de Silveira Carvalho. O\nelevado volume de chuva, associado à intensidade e curta duração do evento, provocou rápido escoamento superficial e aumento abrupto\nda vazão dos cursos d¿água, com destaque para o Córrego do Sul (Ribeirão do Sul), que atravessa a área central do Distrito de Silveira\nCarvalho, apresentando elevação superior a 4,00 metros em seu nível, resultando em transbordamento e inundação de áreas urbanas. ', '2026-04-09 10:47:37', '2026-04-09 10:47:37', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29803, 550, 1, 505, 'Os danos humanos registrados estão diretamente relacionados aos efeitos da inundação causada pelo transbordamento do Córrego do Sul\n(Ribeirão do Sul), que atingiu residências urbanas e rurais no Distrito de Silveira Carvalho. As famílias afetadas tiveram suas residências\ninvadidas pela água, resultando na perda de móveis, eletrodomésticos, alimentos e itens essenciais, além de exposição a riscos sanitários\ndecorrentes do contato com lama, resíduos e possível contaminação hídrica. Parte das famílias precisou ser removida de forma preventiva,\nsendo acolhida em residências de parentes e/ou com apoio da Assistência Social do Município. Destaca-se que os danos humanos foram\nagravados pelo caráter recorrente dos eventos climáticos extremos que vêm atingindo o Município. Trata-se da segunda decretação de\nsituação de emergência em um intervalo inferior a 02 (dois) meses, evidenciando a vulnerabilidade da população frente às chuvas intensas.\nEssa recorrência tem causado esgotamento da capacidade de resposta das famílias, que ainda se recuperavam de eventos anteriores,\nampliando os impactos sociais, emocionais e econômicos. A repetição dos eventos também aumenta a exposição da população a riscos\ncontínuos, especialmente em áreas próximas a cursos d¿água e encostas, reforçando a necessidade de ações emergenciais e estruturantes\npor parte do Poder Público.', '2026-04-09 10:47:37', '2026-04-09 10:47:37', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29804, 550, 2, 505, 'Os danos materiais estão diretamente relacionados ao evento de inundação provocado pelo transbordamento do Córrego do Sul (Ribeirão\ndo Sul), que ocasionou impactos significativos na infraestrutura urbana e rural do Distrito de Silveira Carvalho. Foram registradas 37\nresidências diretamente atingidas, com entrada de água no interior dos imóveis, resultando em danos estruturais, comprometimento de\npisos, paredes, instalações elétricas e hidráulicas, além da perda de bens móveis e utensílios domésticos. No que se refere à infraestrutura\npública, destacam-se danos relevantes em obras de arte correntes, especialmente: destruição de uma ponte de grande porte, localizada na\nestrada de acesso à região rural conhecida como Irmãos Rocha, comprometendo o deslocamento de moradores, o acesso a propriedades\nrurais e o escoamento da produção agrícola; destruição de uma ponte de pequeno porte, situada em estrada vicinal que dá acesso à região\nda Fazenda Santa Luzia, impactando diretamente a mobilidade local e o acesso às propriedades da região; Além disso, diversas vias públicas\ne estradas vicinais foram afetadas por processos erosivos, acúmulo de sedimentos, lama e detritos, resultando em obstruções e\ncomprometimento da trafegabilidade. Os danos materiais observados estão diretamente associados à força das águas, à elevação do nível\ndo córrego e à velocidade do escoamento, que ocasionaram o arraste de estruturas, erosão de taludes e sobrecarga nas fundações das\npontes. Tais impactos comprometem significativamente a mobilidade urbana e rural, o acesso a serviços esse', '2026-04-09 10:47:37', '2026-04-09 10:47:37', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29805, 550, 11, 505, 'Para execução das ações emergenciais, o município mobilizou: Três retroescavadeiras, duas locadas emergencialmente, gerando despesa\ndireta com contratação de serviços e uma enviada pela Defesa Civil Estadual para ajudar no restabelecimento do Município do outro\ndesastre. Uma patrol pertencente à frota municipal; Caminhões pertencentes ao município, e dois caminhões enviados pela Defesa Civil\nEstadual para ajudar no restabelecimento do Município do outro desastre, utilizados para transporte de materiais e remoção de resíduos;\nTrês caminhões pipas ajudaram na limpeza pesada, das residências afetadas e ruas. Veículos utilitários de apoio às equipes técnicas.\nSecretaria de obras, A viatura da Defesa Civil Municipal, Secretaria de Saúde e Secretaria de Assistência Social. Além dos custos com locação\nde maquinário, houve despesas significativas com combustível para operação contínua de retroescavadeiras, patrol, caminhões, veículos\nleves, roçadeiras e motosserras utilizadas na remoção de árvores, limpeza de vias e estabilização emergencial de áreas afetadas. Também\nforam gerados gastos com pagamento de horas extras aos servidores municipais, que atuaram inclusive em finais de semana, períodos\nnoturnos e madrugadas, para garantir o restabelecimento do tráfego e a segurança da população. Houve ainda despesas com alimentação\nde servidores deslocados para áreas afetadas, considerando o prolongamento das jornadas de trabalho e a necessidade de atuação contínua\nnas frentes emergenciais. Os prejuízos econômicos públicos estão, portanto, diretamente relacionados à intensidade e persistência das\nchuvas, que provocaram danos estruturais à infraestrutura municipal e exigiram mobilização extraordinária de recursos financeiros,\nhumanos e materiais, impactando significativamente o orçamento público e superando a capacidade ordinária de resposta do município', '2026-04-09 10:47:37', '2026-04-09 10:47:37', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29806, 550, 12, 505, 'As chuvas intensas e persistentes registradas no município provocaram a elevação significativa do nível do Córrego do Sul, que atingiu\naproximadamente 4 (quatro) metros acima do seu nível normal, ocasionando inundações de grande magnitude nas áreas rurais adjacentes.\nEm decorrência da cheia, houve o transbordamento do curso d¿água, com forte correnteza, resultando no arraste de lavouras, pastagens e\nanimais, causando danos severos às atividades agropecuárias do município. No setor agrícola, foram registradas perdas expressivas de\nculturas, com áreas de plantio completamente destruídas pela ação da água, além de prejuízos em áreas destinadas à produção de silagem,\ncomprometidas pelo encharcamento e deposição de sedimentos. No setor pecuário, foram verificadas perdas de animais, arrastados pela\nforça da enxurrada, bem como danos em cercas, currais e demais estruturas rurais. A inundação também comprometeu áreas de pastagem,\nimpactando diretamente a alimentação do rebanho. Além disso, as condições de alagamento dificultaram o acesso às propriedades rurais,\nprejudicando o escoamento da produção, especialmente leiteira, e ocasionando perdas adicionais aos produtores. Os prejuízos causados\nimpactaram diretamente a renda das famílias rurais e a economia local, agravando a situação de vulnerabilidade das comunidades atingidas.', '2026-04-09 10:47:37', '2026-04-09 10:47:37', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29807, 5900, 1, 506, NULL, '2026-04-09 19:05:46', '2026-04-09 19:05:46', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29808, 620, 1, 507, NULL, '2026-04-09 19:07:35', '2026-04-09 19:07:35', NULL);
