INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29812, 3390, 9, 509, 'Bairros do Centro, Bananal, Barra e João Homem', '2026-04-16 13:06:26', '2026-04-16 13:06:26', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29813, 3390, 10, 509, 'Os meses de Fevereiro e Março foram marcado por dias seguidos de chuvas intensas com ventos ventos fortes e níveis elevados de água\nnos rios onde não mais suportaram causando alagamentos.\n', '2026-04-16 13:06:26', '2026-04-16 13:06:26', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29814, 3390, 1, 509, 'No bairro Bananal houve um colapso do murro de contenção devido as fortes chuvas onde o mesmo causou danos a estrutura da casa,\nsendo necessário interditar a casa e move-los para uma habitação temporária. No bairro do Centro tivemos a interdição de uma casa que\ndevido a chuvas intensas houve o desabamento do solo comprometendo a estabilidade estrutural da edificação, sendo assim interditada e a\nmoradora foi habitada em uma casa temporária. Os outros afetados são moradores que sofreram com os alagamentos. mas não\nnecessitaram em sair de seus domicílios.', '2026-04-16 13:06:26', '2026-04-16 13:06:26', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29815, 3390, 2, 509, 'Vias públicas, ruas, passeios, pontes e muros. Unidades habitacionais, casas interditadas, estruturas de contenção, animais e bens\nmateriais.\n', '2026-04-16 13:06:27', '2026-04-16 13:06:27', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29816, 3390, 3, 509, 'Minas d\'águas contaminadas e qualidade reduzida no fornecimento de água pela COPASA.', '2026-04-16 13:06:27', '2026-04-16 13:06:27', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29817, 2430, 1, 401, '60 pessoas foram abrigadas em abrigo público montado pela prefeitura. 1.620 pessoas ficaram desalojadas e foram para casa de parentes e\namigos. 10.000 pessoas foram afetadas da seguinte forma: cerca de 2500 permaneceram nos imóveis, mesmo alagados, por receito de\ninvasão e furto de bens. As demais pessoas foram afetadas pela interrupção da energia, da mobilidade urbana, do acesso a comércio e\nserviços e pela interrupção das aulas. No momento do preenchimento desse fide, ainda havia muitas áreas alagadas e as equipes do\nsistema municipal de defesa civil ainda estavam em campo fazendo levantamento de danos\n', '2026-04-16 13:07:52', '2026-04-16 13:16:58', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29818, 2430, 8, 401, NULL, '2026-04-16 13:16:57', '2026-04-16 13:16:57', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29819, 2430, 9, 401, 'Toda a zona Urbana principalmente os bairros Santa Tereza, Juscelino Kubitschek (JK), Araponga, Centro, São Cristóvão, Santa Cláudia, São\nDomingos, Soledade e Cidade Nova, atingidos por transbordamento dos rios São Domingos e Galheiros, bem como em razão de\nalagamentos decorrentes do acúmulo de água das chuvas. Toda a zona Rural principalmente danos nas estradas vicinais e nas comunidades\nde Tabuleiro, Rio Grande e Capivara de Baixo.', '2026-04-16 13:16:58', '2026-04-16 13:16:58', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29820, 2430, 10, 401, 'No dia 01/03/2026, o Município de Espinosa/MG foi atingido por precipitação intensa e concentrada, com acumulado aproximado de 130\nmm em curto intervalo de tempo, caracterizando Tempestade Local/Convectiva Chuvas Intensas (COBRADE 13214). O elevado volume\npluviométrico provocou aumento abrupto do nível do Rio São Domingos e do Rio Galheiros, resultando em transbordamento das calhas\nnaturais e inundação de áreas urbanas e rurais. A magnitude do evento foi evidenciada pelo número expressivo de residências atingidas\n(405), 1.620 pessoas desalojadas, 60 pessoas desabrigadas e aproximadamente 10.000 pessoas afetadas. Houve ainda destruição de\npassagem molhada na comunidade de Tabuleiro, interrupção parcial do fornecimento de energia elétrica em 294 residências, além de danos\nestruturais, alagamentos extensos e risco sanitário decorrente do contato da população com água contaminada. No momento do\npreenchimento desse fide, ainda havia muitas áreas alagadas e as equipes do sistema municipal de defesa civil ainda estavam em campo\nfazendo levantamento de danos', '2026-04-16 13:16:58', '2026-04-16 13:16:58', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29821, 2430, 2, 401, 'Foram registradas aproximadamente 405 unidades habitacionais danificadas em decorrência direta da inundação provocada pelo\ntransbordamento dos rios São Domingos e Galheiros, com comprometimento de estruturas, revestimentos, instalações elétricas, mobiliário e\nbens essenciais. Na zona rural, houve destruição de ponte do tipo passagem molhada na comunidade de Tabuleiro, além de danos em\nestradas vicinais e vias urbanas, com erosões, assoreamento e deterioração do leito carroçável. No momento da redação deste Fide, as\nequipes dos sistema municipal de proteção e defesa civil ainda estavam em campo fazendo levantamento de danos.', '2026-04-16 13:16:58', '2026-04-16 13:16:58', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29822, 2430, 11, 401, 'Os prejuizos econômicos relacionado a esgotamento das águas pluviais foram decorrentes da necessidade de bombeamento das áreas e\nimóveis situados abaixo da rede de drenagem. Os relacionados à coleta de lixo referem-se ao montante destinado ao recolhimento dos\nresíduos decorrentes do desastre que não estavam programados na rotina de limpeza da cidade. Apesar da interrupção das aulas, não\nhouve prejuízos econômicos relevantes. Apenas prejuízos sociais.', '2026-04-16 13:16:58', '2026-04-16 13:16:58', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29823, 2430, 12, 401, 'Os prejuízos da agricultura estão relacionados à perda de safra e interrupção do escoamento da produção. Na pecuária, morte de animas e\ninterrupção de estradas vicinais que interromperam o escoamento da produção. Na indústria, o alagamento provocou a perda de insumos e\nprodutos além de danos em máquinas e equipamentos. No comércio houve', '2026-04-16 13:16:58', '2026-04-16 13:16:58', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29824, 3390, 11, 509, 'Envio de água potável para o bairro João Homem, transporte e limpeza para os bairros Centro, Bananal, João Homem e Barra. Houve a paralisação temporária no fornecimento de água através da COPASA.', '2026-04-17 11:08:47', '2026-04-17 11:08:47', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29825, 3390, 12, 509, 'Prejuízos em lavouras e morte de animais afogados.', '2026-04-17 11:08:47', '2026-04-17 11:08:47', NULL);
INSERT INTO `dec_entrada_categoria_desastres` (`id`, `municipio_id`, `categoria_id`, `entrada_processo_id`, `descricao`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(29826, 4390, 2, 329, 'Após ocorrência de chuva forte e volumosa na noite do dia 9/02 o município registrou diversos pontos de alagamento, inundação em\nregiões ribeirinhas e vários pontos de deslizamentos de encosta. Estima-se que, devido a cheia dos rios Preto e Muriaé e do transbordo do\ncórrego na Vila Leite, 550 unidades habitacionais (com ou sem morador) tiveram danificações na pintura e portas de madeira, após entrada\nda água no interior dos imóveis. O custo estimado por unidade habitacional, segundo relatório da Secretaria Municipal de Obras Públicas e\nUrbanismo, é de R$ 3.500,00 com valor total de R$ 1.925.000,00. O município apresentou danos em 2 instalações públicas de saúde após\ndeslizamento do talude de corte confrontante aos fundos. De acordo com relatório da Secretaria Municipal de Obras Públicas e Urbanismo, a\nUBS SANTANA tem estimativa de custo de R$ 150.000,00 e a UBS MARAMBAIA estima-se valor de R$ 75.000,00. Com isso, o valor total\norçado estimado para as instalções públicas de saude é de R$ 225.000,00 No que tange infraestrutura pública, devido a ocorrência de\nenxurradas e direcionamento de água, após evento da chuva do dia 9/02, o município registrou 3 ruas parcialmente danificadas (rua Aliete\nMaria de Oliveira - Bairro Marambaia, Rua Jeberson Gomes de Souza - Bairro Recreio e Rua Guilhermino de Oliveira - Bairro Edgar Miranda)\nalém de um Escadão Público no bairro Aeroporto. De acordo com relatório da Secretaria Municipal de Obras Públicas e Urbanismo, o\norçamento estimado para as 4 infraestruturas supracitadas é de R$ 2.750.000,00.', '2026-04-24 11:39:57', '2026-04-24 11:39:57', NULL);
